window.__D("text/torat-chaim/c038",{"p":[[2300550890,"העצמיות ממש וכמ\"ש רחב\"ה מצות\"ך מא\"ד. והנה כדי להמשיך לבחי' המקיפים דיריעות המשכן הוצרך להזהיר להם תחלה במצות השבת שהעיקר הוא בהעלאה מלמטה למעלה באו\"ח בשביתה מן המלאכה שעולה רצה\"ת ומתחבר ברצה\"ע כנ\"ל ואז אח\"כ יוכל רצה\"ע דמצות שנק' לבושים לירד למטה להיות שורה בבחינת מקיף עדיין שהן היריעות דמשכן (וכמו וקראת לשבת עונג העליון דעוה\"ב כנ\"ל). וזהו שנסמכה פ' שבת למלאכת המשכן בכלל וכמ\"ש את שבתותי תשמרו ומקדש\"י תירא\"ו<sup data-n=\"8929\">1894</sup> דהא בהא תליא דאם שבתות\"י תשמר\"ו (בב' שבתות כהלכתן באו\"ח ואו\"י כנ\"ל) אזי ממילא מקדש\"י תירא\"ו שזהו גלוי שכינה בהיכל ק\"ק במקיפים ובפנימי' בבחי' כלים, כידוע שהיראה הוא בבחינת המל'<sup data-n=\"8930\">1895</sup> (כי המשכן הוא בבחי' מל'<sup data-n=\"8931\">1896</sup> שנק' שכינה כמ\"ש ועשו לי מקדש ושכנתי בתוכם כו').\n<b>והנה</b> בסדר מלאכת המשכן צוה משה לעשות היריעות דמשכן תחלה וכמ\"ש כאן קחו מאתכם כו' עד וכל חכם לב בכם<sup data-n=\"8932\">1897</sup> יבאו ויעשו [את] כל אשר צוה ה' את המשכן ואת אהלו<sup data-n=\"8933\">1898</sup> (יריעות עיזים) ואת מכסהו (עורות תחשים)<sup data-n=\"8934\">1899</sup> ואת קרשיו<sup data-n=\"8935\">1900</sup> כו' ואח\"כ את הארון<sup data-n=\"8936\">1901</sup> כו', וכן בעושי המלאכה א' ויעשו כל חכם לב בעושי המלאכה את המשכן עשר יריעות כו' ואח\"כ הארון והשולחן כו'. והענין הוא דבהמשכה וירידה מלמעלה למטה צריך לעשות בחי' המקיף תחלה שהן היריעות שנק' אהל כו' ואח\"כ צריך לעשות האו\"פ בכלים שהוא הארון ושולחן כו', וזהו ענין המקיפים דרצה\"ע שבמצות שלמעלה בהעלם בלתי נגלה בגלוי אור עדיין רק בבחי' העלם דלבושים (ולע\"ל יתגלה מן ההעלם ויהיה מזה התגלות העונג העצמות דעדן דעוה\"ב כנ\"ל), וכן א' כי נר מצוה ותורה אור שהתורה באה בבחי' או\"ח<sup data-n=\"8937\">1902</sup> בגלוי מן העלם דרצה\"ע [דמצות] (כמ\"ש במ\"א דתרי\"ג מצות הן בתרי\"ג ארחין דגלגלתא<sup data-n=\"8938\">1903</sup> שלמעלה מח\"ס שזהו תו' אור כטעם כמוס לרצה\"ע בסודות התורה כידוע ושרש המצות בעצם הרצון שאין טעם לרצון כלל שהוא העוה\"ב כו' ונמשך בלבוש ומקיף לבד כנ\"ל).\n<b>והנה</b> מה שהתורה נקרא אור היינו מה שאנו רואים שבחי' המקיף הנעלם דרצה\"ע שבמצות למעלה כנ\"ל בא לגלוי בתושב\"כ כמו בצרופי אותיות שבתושב\"כ בכל מצוה שהן בחי'",[["8929","1894","<b>את שבתותי תשמרו ומקד \"י תירא\"ו</b>: קדושים יט, ל. בהר כו, ב."],["8930","1895","<b>שהיראה. . המל'</b>: ראה ת\"ז בהקדמה (ו, א)."],["8931","1896","<b>המשכן הוא בבחי' מל'</b>: ראה זהר פקודי רלה, ב. בחוקותי קיד, א. בהעלותך קנד, א [וכן צ\"ל במאמרי אדה\"א שמות ח\"ב ע' ת]."],["8932","1897","<b>וכל חכם לב בכם</b>: ויקהל לה, י."],["8933","1898","<b>את המשכן ואת </b>[יז: את]<b> אהלו</b>: שם לה, יא."],["8934","1899","<b>אהלו (יריעות עיזים. . תחשים)</b>: רש\"י שם."],["8935","1900","<b>ואת קרשיו</b>: ויקהל שם [ושם: את קרסיו ואת קרשיו]."],["8936","1901","<b>את הארון</b>: ויקהל לה, יב."],["8937","1902","<b>או\"ח</b>: טזיזיט: אור."],["8938","1903","<b>דתרי\"ג מצות. . דגלגלתא</b>: ראה זהר (אד\"ר) נשא קכט, א. קלו, א. מאמרי אדה\"ז תקס\"ח ח\"א ע' שמא ואילך. מאמרי אדה\"א במדבר ח\"ב ע' תרעה."]]],[2300550891,"כלים לאור הרצה\"ע כידוע, וזה הי' ענין הארון ולוחות שבמשכן עם הכפורת שעלי' שבלוחות היו כתובים יו\"ד הדברות כללות כל התו\"מ<sup data-n=\"8939\">1904</sup> שכלולים באנכי כו' שבא באותיות ממש שנק' כלים. אך עכ\"ז ה\"ז בא בבחי' העלם עדיין כי הלוחות הרי הי[ו] גנוזים בארון כס\"ת שגנוזה בהיכל (שע\"ז א' הכל תלוי במז\"ל אפי' ס\"ת בהיכל שזהו בחי' מז\"ל ונוצ\"ר מקור החכמה דתורה אור שנק' חכמה שבכת\"ר), וגם האותיו' דתושב\"כ הן בבחי' העלם וסתימות דח\"ע הגנוז בהן ולכך הן במספר קצוב ובדקדוק חסר ויתי\"ר קר\"י וכתיב כו', שהרי א\"א לידע כל דיני המצוה בפרטי' איך ומה לעשות מאותיות הללו, כמו במצות ציצית מ\"ש ועשו לכם ציצית<sup data-n=\"8940\">1905</sup> כו' לא נתפרש איך ומה בפרט כל דיני הלכ[ות] ציצית למעשה רק בהל' ציצית בתושבע\"פ מפרש כל דין והלכה להביא לידי מעשה בפרט. וכן במצות סוכה א' בסוכות תשבו כו' נתפרש<sup data-n=\"8941\">1906</sup> כל דיני סוכה איך לעשות בפרט בכל אופנים המוכשר למצוה, והעיקר הוא במה שמפרש באופני המנגד להכשר המעשה שאם לא תהיה בהכשירה פסולה, והיינו כמ\"ש סוכה שלמעלה מכ' אמה פסולה<sup data-n=\"8942\">1907</sup> וכה\"ג כל דיני הסוכה שפוסלים הסוכה כחמתה מרובה מצילתה<sup data-n=\"8943\">1908</sup> וכה\"ג, וכן בציצית ותפילין [ו]שבת ויו\"ט שזהו ענין המדות דחכ' דתו' שהוא בכלל בענין כשר ופסול ואסור ומותר וטו\"ט וחייב וזכאי בד\"מ<sup data-n=\"8944\">1909</sup>, דאעפ\"י שגם בתושב\"כ העיקר הוא במדות דחכמה כמ\"ש להבדיל בין טל\"ט<sup data-n=\"8945\">1910</sup> בעופות טהורים וטמאים וכן בהמות וכך בקרבנות כשר ופסול, אבל לא נתפרש כלל כל פרטי ההוראה שיש בזה כמ[ו] בכל דינין והלכות שבמשנה שבו' הסדרים בסדר זרעים ומועד ונשים וקדשים וטהרות שכוללים רק הוראות או\"ה כו\"פ טו\"ט ובד\"מ דנזיקין<sup data-n=\"8946\">1911</sup> חייב זכאי שזהו עיקר ענין המדות דחכ', כמו החכ' שלמד כל החכ' העצמי' אם אינו יודע להורות ולדון במדות דחכמה זו כך ולא כך בכל פרטי' הרי כל החכ' נשאר בהעלם לא נודע דבר ממנה למקבלים כו'. ובכך<sup data-n=\"8947\">1912</sup> בחכ' באותיות דתושב\"כ אעפ\"י שנק' תו' או\"ר שבאה ח\"ע מן ההעלם לגלוי כנ\"ל אך זהו בכללות ובהעלם וקיצור עדיין ועיקר ההתגלות הוא במדות דו\"ס משנה דתושבע\"פ שמגלים כל פרט בב' אופנים דחו\"ג שזהו או\"ה כו\"פ טו\"ט כו'. ונמצא דעיקר בחי' הכלים לאור דח\"ע שבתושב\"כ זהו ו\"ס משנה דוקא שהן ו' מדות<sup data-n=\"8948\">*1913</sup> שמקבלים מחכמה דתושב\"כ כמו ס' זרעים הוא בחינת כלי החסד<sup data-n=\"8949\">1913</sup> דאור החכמה כו' וסדר מועד כלי הגבו'<sup data-n=\"8950\">1914</sup> כו' וסדר נשים ת\"ת<sup data-n=\"8951\">*1915</sup> כו' וד\"ל.",[["8939","1904","<b>יו\"ד הדברות כללות כל התו\"מ</b>: ראה רש\"י משפטים כד, יב. לעיל פ' שמות יא, ג. וש\"נ."],["8940","1905","<b>ועשו לכם </b>[טזיט: להם. יז: כבפנים]<b> ציצית</b>: שלח טו, לח."],["8941","1906","<b>נתפרש</b>: טז: לא נתפרש. יז: דילג שורה. יט: כבפנים. וכנראה שתיבת נתפרש קאי על מ\"ש בשורה לפנ\"ז: בתושבע\"פ."],["8942","1907","<b>סוכה שלמעלה מכ' אמה פסולה</b>: סוכה בתחלתה."],["8943","1908","<b>כחמתה מרובה מצילתה</b>: סוכה שם."],["8944","1909","<b>בד\"מ</b>: בדיני ממונות."],["8945","1910","<b>להבדיל בין טל\"ט</b>: שמיני יא, מז [ושם: להבדיל בין הטמא ובין הטהור]."],["8946","1911","<b>זרעים. . וטהרות. . דנזיקין</b>: ראה לקו\"ש בשלח (כרך יא) ע' 56 הערה 13."],["8947","1912","<b>ובכך</b>: טזיזיט: וכך (וכן)."],["8948","*1913","<b>ו\"ס משנה. . ו' מדות</b>: ראה הנסמן לעיל בפ' תצוה שסב, ד הערה 70."],["8949","1913","<b>ס' זרעים. . החסד</b>: ראה ת\"ז בהקדמה (ה, א). משנת חסידים מסכת תלמוד תורה פ\"א, ה\"ו. מאמרי אדה\"ז תקס\"ה ח\"א ע' עג ו[כאן] ע' שמב. מאמרי אדה\"א בראשית ע' לא. וש\"נ. קונטרסים ע' רב. וש\"נ. תו\"ח לך פז, ב ובהערה 9. לקמן פ' פקודי תמו, ב. תמט, ב. תנה, ג."],["8950","1914","<b>וסדר מועד כלי הגבו'</b>: ראה גם פיה\"מ לה, סע\"ג ואילך. ולהעיר מלעיל שצ, ב."],["8951","*1915","<b>וסדר נשים ת\"ת</b>: ראה גם פיה\"מ לה, רע\"ד."]]],[2300550892,"<b>וזהו</b> כללות ענין הכלים שהיה במשכן שהוא בבחי' אור הנגלה בכלי[ם] דהיינו באור דתורה בכלל כנ\"ל שגם בתושב\"כ נתלבשה באותיות שהן בחי' כלי' אבל עדיין הן בהעלם [ו]בקיצור (שהן מדות דח\"ע עצמ[ה] הכלולים בה כו' והוא כמו כלי הארון ולוחות שבו כנ\"ל, ודרך כלל נחלקה התורה לז' מדריגות כמו ז' נרות המנורה (כמשי\"ת), דהיינו תושב\"כ וס' [מסכתות] שכלולים בו\"ס משנה<sup data-n=\"8952\">1915</sup> שהן ו' מדות שמקבלים מחכ' שהרי במשנה מפורש כל דין ודין כך ולא כך כמו כו\"פ כו' כנ\"ל), וכל דין והלכה נלמד מן המקרא שבתושב\"כ דוקא כמו מנלן א\"ק<sup data-n=\"8953\">1916</sup> כו', והן הכלים דמנורה ושולחן ומזבח הזהב כו' שמקבלים מהעלם דח\"ע דתו' שבארון ולוחות, ומנורה בדרום זהו בבחינת כלי החסד דחכ' כו' כמו סדר זרעים במשנה, ושולחן בצפון זהו בחינת כלי הגבו' כסדר מועד כו' (ומזבח הזהב בבחינת ת\"ת<sup data-n=\"8954\">1917</sup> ומזבח החיצון בנו\"ה<sup data-n=\"8955\">*1918</sup> שמבררים הטוב מן הרע וקדש מחול (והוא ס' קדשים) והכיור וכנו ס' טהרות ביסוד ומל'<sup data-n=\"8956\">1918</sup> ) (ובבנין בהמ\"ק דשלמה הי' נוסף בים שעשה על י\"ב בקר<sup data-n=\"8957\">1919</sup> כו'). ובאמת הן רק ה' כלים<sup data-n=\"8958\">1920</sup> ארון<sup data-n=\"8959\">1921</sup> ושולחן ומנורה ומזבח הזהב ומזבח החיצון והכיור ובהם כלולים ו\"ס משנה<sup data-n=\"8960\">1922</sup>, שהמשכן במל'<sup data-n=\"8961\">1923</sup> שהשכינה הי' במערב<sup data-n=\"8962\">1924</sup>, ולכך הארון במערב<sup data-n=\"8963\">1925</sup> ומנורה בדרום העולם שהוא צפון הארון ושולחן בצפון העולם שהוא דרום הארון אעפ\"י שמשתחווים למערב כו', אבל כמו שבמשפיע שהוא בחי' ז\"א חסד שלו בדרום לנגד צפון דמל' כידוע (ולכך הזכיר שולחן לצפון קודם הארון ומנורה<sup data-n=\"8964\">1926</sup> וד\"ל (והן ה' חומשי תורה שהן ה\"ח<sup data-n=\"8965\">1927</sup> דמשפיע כו').\n<b>והנה</b> ידוע שבדרך כלל נק' התורה בשם אור וזהו שנמשלה התורה למנורה<sup data-n=\"8966\">1928</sup> שיאיר אור דתורה בנרות שלה [מ]אור דח\"ע הגנוז באותיות דתושב\"כ שבלוחות וארון וכו'). ולפעמים נק' התורה בשם מזון כלחם כמו לכו לחמו בלחמי וכתיב ותור[תך] בתוך מעי כו' וזהו ענין השולחן שהי' עליו לחה\"פ דתורה (כמשי\"ת). ותחלה י\"ל במה שהתו' נק' אור המאיר בנרות המנורה דוקא, דהנה ידוע שנרות המנורה הן בחי' נש\"י<sup data-n=\"8967\">1929</sup> שנק' נר הוי' כו' וצריך שיעלו נש\"י לשרשם ע\"י",[["8952","1915","<b>וס' [מסכתות] שכלולים בו\"ס משנה</b>: ראה גם לעיל שצ, ב. פ' שמות ג, א."],["8953","1916","<b>מנלן א\"ק</b>: ראה פסחים סא, סע\"א. סה רע\"א. ועוד."],["8954","1917","<b>ומזבח הזהב. . ת\"ת</b>: לא הוזכר כאן סדר נשים [ראה לעיל בסוף פסקא הקודמת]. וכן סדר נזיקין."],["8955","*1918","<b>ומזבח החיצון בנו\"ה</b>: ראה גם לקמן על יד הערה 1990."],["8956","1918","<b>והכיור וכנו. . ביסוד ומל'</b>: ראה מאורי אור (מערכת כיור) אות כ סעיף לב. אוה\"ת תשא ע' א'תתקלא ואילך. ס\"ע א'תתקלד ואילך."],["8957","1919","<b>דשלמה. . בים. . י\"ב בקר</b>: מל\"א ז, כה. מד. דהי\"ב ד, טו."],["8958","1920","<b>ה' כלים</b>: ראה גם בסמוך ה' חומשי תורה."],["8959","1921","<b>ארון</b>: אולי אינו נמנה בין הכלים — ראה לעיל שו\"ה מהעלם."],["8960","1922","<b>ה' כלים. . ו\"ס משנה</b>: ראה עד\"ז מאמרי אדה\"ז תקס\"ה ח\"ב ס\"ע תרמו ואילך. מאמרי אדה\"א במדבר ח\"ב ע' תתכג ואילך."],["8961","1923","<b>במל'</b>: טזיט: במערב. יז: כבפנים. — משכן במערב — ראה ערובין כג, ב וברש\"י שם. רש\"י תרומה כז, יח."],["8962","1924","<b>שהשכינה. . במערב</b>: ב\"ב כה, א. ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרכו."],["8963","1925","<b>הארון במערב</b>: ראה פקודי מ, כא ואילך."],["8964","1926","<b>לצפון. . ומנורה</b>: טזיט: לימין הארון קודם למנורה."],["8965","1927","<b>ה' חומשי תורה שהן ה\"ח</b>: ראה גם מאמרי אדה\"א במדבר ח\"ב ע' תתכב."],["8966","1928","<b>שנמשלה התורה </b>[טזיט: ליתא]<b> למנורה</b>: ראה תורת העולה ח\"א פט\"ז. ערכי הכנויים לבעל סדר הדורות מערכת מנורה. מאמרי אדה\"ז תקס\"ה כאן ע' שמב."],["8967","1929","<b>שנרות המנורה. . נש\"י</b>: נסמן לעיל פ' תצוה שלו, ג הערה 676."]]],[2300550893,"הדלקת הנרות דמנורה שיאירו אל מול פני כו' שהוא נר האמצעי<sup data-n=\"8968\">1930</sup>. והענין הוא כידוע דג' קשרין הן נש\"י מתקשראן באורייתא ואורייתא בקוב\"ה בב' מדריגות דסתים וגלייא דקוב\"ה ס[תים] וג[ליא] וכן אורייתא סתים וגליא ונש\"י שעבמ\"ח כו' וצריך לחבר את האהל שיהי' מאיר מאור א\"ס בנש\"י ע\"י אור דתו', והיינו כללות ענין המנורה שו' נרות הן ת\"ר אלף נש\"י<sup data-n=\"8969\">1931</sup> ומקבלים מנר האמצעי שהוא אל מול פני כו' דהיינו מא[ו]ר דתושב\"כ שמאיר בו' מדות דחכ' שהן ו\"ס משנה שפרטיהם ס' מסכתות לנגד ס\"ר נש\"י ששרשם בס\"ר אותיות דתושב\"כ ו[מ]טעם המבואר למעלה דבו\"ס [משנה] שם עיקר התגלות האור בכלי והן ו' קני המנורה<sup data-n=\"8970\">1932</sup> שמקבלים מנר האמצעי שהוא תו' שבכתב שמאיר בה [מ]בחי' עצמיות אור א\"ס שנקרא מאור מקור האור דתורה (כענין שא' מאור שבה<sup data-n=\"8971\">1933</sup> כו' (כמ\"ש במ\"א). ולפ\"ז הרי במצות ת\"ת בגירסא בו\"ס משנה דוקא תקבל הנשמה אור דא\"ס באמצעות אור דח\"ע דתושב\"כ כמו שמלמדים הכל ממקרא, ולכך כל הו\"ס משנה הן בחי' כלי לקבל האור העליון דח\"ע שמדליק אותן הכה\"ג להעלות לנש\"י כמ\"ש בהעלותך את הנרות אל מול פני [המנורה] כו' שהוא עצמיות אור א\"ס שבנר האמצעי יאירו כו' (ולפי שו\"ס משנה הן עיקר הכלים להכיל האור להאיר בנש\"י ע\"כ אין<sup data-n=\"8972\">1934</sup> קיבוץ גליות רק ע\"י המשניות<sup data-n=\"8973\">1935</sup> כידוע רק אל מול כו' שזהו כשמקבל מתושב\"כ כו').\n<b>וזהו</b> כללות מעשה המנורה מקשה א'<sup data-n=\"8974\">1936</sup> כו' והכל מזהב<sup data-n=\"8975\">1937</sup> שהוא בחי' הגבו'<sup data-n=\"8976\">1938</sup> דעיקר בנין המל' שהן נש\"י מגבי'<sup data-n=\"8977\">1940</sup> הגבו'<sup data-n=\"8978\">1939</sup> שהוא בחינת התלהבות האלקי' באתעדל\"ת בכל ניצוץ כמו בק\"ש במס\"נ, אך צ\"ל אתעדל\"ע להדליק הנרות בשלהבת י\"ה (לעשות אתעדל\"ת וזה היה ע\"י אה\"ר דכה\"ג בהעלותך את כו' לעורר את האהבה<sup data-n=\"8979\">1941</sup> כמ\"ש במ\"א, ואז ע\"י אתעדל\"ת יאיר אור השפע מלמעלה מבחי' מול פני המנורה כו' כנ\"ל שממנו יאירו כו' (וזהו וכפתור תחת ב' הקנים ממנה<sup data-n=\"8980\">1943</sup> כו'<sup data-n=\"8981\">1942</sup> כי אתעדל\"ע גורם ועושה אתעדל\"ת בנש\"י שכלולים בתושבע\"פ מתנית' מלכתא<sup data-n=\"8982\">1944</sup> כו' כששונים הלכות שהן קני המנורה בכלל כו', ואתעדל\"ת עושה<sup data-n=\"8983\">1945</sup> ומעורר אח\"כ",[["8968","1930","<b>אל מול פני. . נר האמצעי</b>: בהעלותך ח, ב וברש\"י שם ממנחות צח, ב."],["8969","1931","<b>שו'. . ת\"ר אלף נש\"י</b>: ראה עד\"ז לעיל פ' בשלח רמז, ב."],["8970","1932","<b>דבו\"ס [משנה]. . ו' קני המנורה</b>: ראה גם לעיל פ' שמות ג, ג. וש\"נ."],["8971","1933","<b>כענין שא' מאור שבה</b>: ראה גם לעיל פ' שמות טז, ג. וש\"נ."],["8972","1934","<b>אין</b>: טזיט: ליתא."],["8973","1935","<b>קיבוץ גליות. . המשניות</b>: ראה ויק\"ר פ\"ז, ג. לעיל פ' שמות יג, ג. וש\"נ."],["8974","1936","<b>מקשה א'</b>: תרומה כה, לו. ויקהל לז, כב."],["8975","1937","<b>והכל מזהב</b>: תרומה שם, לא. לו. לח. לט."],["8976","1938","<b>מזהב. . הגבו'</b>: נסמן לעיל פ' תצוה שעא, ד."],["8977","1940","<b>מגבי'</b>: טזיזיט: מבחי'."],["8978","1939","<b>בנין המל'. . הגבו'</b>: ראה גם לעיל פ' בשלח רמד, א. וש\"נ."],["8979","1941","<b>דכה\"ג. . לעורר את האהבה</b>: ראה לעיל פ' יתרו רסט, ב ואילך. וש\"נ."],["8980","1943","<b>וכפתור תחת ב' הקנים ממנה</b>: תרומה כה, לה."],["8981","1942","<b>(וזהו. . כו'</b>: טזיט: וזהו. . כו')."],["8982","1944","<b>מתנית' מלכתא</b>: טזיט: מתניתין מלכתא — ביצה כח, ב. יז: מתניתא מלכתא — כתובות סא, ב."],["8983","1945","<b>עושה</b>: שם: עולה."]]],[2300550894,"אתעדל\"ע להתמשך מאור דח\"ע וזהו חיבור דאו\"מ ואו\"פ שהוא או\"י ואו\"ח דאתעדל\"ע ואתעדל\"ת יחד), כמו המקום שמתחברים המשפיע עם המקבל יחד [ש]מתכללים ז[מ]\"ז כשמי' וארעא דנשקי אהדדי<sup data-n=\"8984\">1946</sup> כו' כמ\"ש כי כל דאחיד<sup data-n=\"8985\">1947</sup> כו' שם נעשה אור כפול, והוא הכפתור כמו עד\"מ ב' קשרים זעג\"ז שקושרין ב' חוטין נק' קשר כפול שנקרא קשר של קיימא<sup data-n=\"8986\">1948</sup> כו', ולכך דוקא תחת ב' הקנים יש כפתור שהוא עב כמו כפול דכל ב' קנים הן ב' מדות דחו\"ג שהן כמו ששה כפולות לפי שכל מדה כלולה מהיפוכה כו', ולכך במקום שמתחברים אתעדל\"ע ואתעדל\"ת יחד יש שם אור כפול כו' וד\"ל.\n<b>אך</b> הנה כללות ענין התו' שהוא<sup data-n=\"8987\">1949</sup> להאיר אור הארת פנים העליונים ממול פני המנורה שמשם דוקא יאירו הנרות, וזה היה עיקר הדלקת הנרות המנורה כנ\"ל שזהו לעשות אתעדל\"ע להיות המשכות אור פנים העליונים כמו יאיר<sup data-n=\"8988\">1950</sup> הוי' פניו אליך<sup data-n=\"8989\">1951</sup> פניו דוקא ואליך דוקא. וזה הי' ע\"י בחי' אור דתורה דוקא שע\"י אור דחכ' דתו' כמ\"ש ותורה אור מאיר מפנימיות ועצמיות דא\"ס ממש שנק' פני הוי' ממש, והוא משום דאורייתא מתקשרא בקוב\"ה ממש ואורייתא וקוב\"ה כולא חד<sup data-n=\"8990\">1952</sup> ממש בין בבחי' סתים [ד]תוה\"ק שא' ואהיה אצלו ממש שעשועים<sup data-n=\"8991\">1953</sup> עצמי' כו' בין באור דתו' הנגלית במ\"ת בא' אנכי כו' דע\"ז א' חכ' אדם תאיר פניו, דהיינו בחי' חכ' דתורה שנק' חכ' אדם העליון כו' שתאיר פניו בבחי' אור הפנימיות ועצמיות שלו ממש כמו במ\"ת שבאור פניו נתת ל[נ]ו בפב\"פ. והוא כמו שרואים בחכ[ם] שמחדש שכל וחכמה חדשה דוקא שיצהבו ויאירו פניו ביותר כמ\"ש בר\"א שמצא תוספתא חדתא וצהבו פניו<sup data-n=\"8992\">1954</sup> כו', כמו\"כ ע\"י אור דחכ' דתורה נמשך בחי' הארת פנים העליונים וזהו ותורה אור כו' (שמפני זה נק' אמת<sup data-n=\"8993\">1955</sup> שזהו תיקון הז' ואמת<sup data-n=\"8994\">1956</sup> שהוא הארת תרין תפוחין כו'), וזהו אל מול פני המנורה דוקא יאירו כו' ולכך הי' המנורה בדרום בימין שהוא בחי' החסד דחכ' שנקרא אור המאיר לנש\"י מטעם הנ\"ל וד\"ל.\n<b>והנה</b> ע\"ד הנ\"ל במנורה שבדרום (משמאל לארון כשמשתחווים למערב כנ\"ל) כך הוא בחכ' שבתו' שנק' לחם ומזון שהוא השולחן, דמנורה ושולחן שניהם מקבלי' מאור החכמה דתו' כמו שהיא בבחי' הכתר שבהיכל ק\"ק בארון וכפורת שזהו בחי' אין דח\"ע שנמשך למדות בחו\"[ג] דחכמה, והן מנורה בדרום [ו]שולחן בצפון בבחי' אור להאיר בכלי שהן נרות דנש\"י כמו שהי' במ\"ת שקבלו פב\"פ מתו' אור הפנימיות",[["8984","1946","<b>כשמי' וארעא דנשקי אהדדי</b>: בבא בתרא עד, א."],["8985","1947","<b>כי כל דאחיד</b>: דהי\"א כט, יא. ראה זהר בראשית לא, א. מאמרי אדה\"א ויקרא ח\"ב ע' תשמב. וש\"נ."],["8986","1948","<b>ב' קשרים. . קשר של קיימא</b>: ראה שו\"ע אדה\"ז הל' שבת סשי\"ז, ס\"ב."],["8987","1949","<b>התו' שהוא</b>: טזיזיט: המנורה זהו."],["8988","1950","<b>יאיר</b>: שם: יאר."],["8989","1951","<b>יאר הוי' פניו אליך</b>: נשא ו, כה."],["8990","1952","<b>ואורייתא וקוב\"ה כולא חד</b>: נסמן לעיל פ' משפטים רצ, ג."],["8991","1953","<b>ואהי' אצלו. . שעשועים</b>: משלי ח, ל [בדילוג]."],["8992","1954","<b>בר\"א. . וצהבו פניו</b>: ראה ירושלמי שבת פ\"ח, ה\"א. לעיל פ' בשלח קעח, ב. וש\"נ."],["8993","1955","<b>ותורה. . אמת</b>: מלאכי ב, ו."],["8994","1956","<b>תיקון הז' ואמת</b>: ראה זהר (אד\"ר) נשא קלא, א. קלג, ב. ע\"ח (שער א\"א) שי\"ג, פ\"ט. לקו\"ת מסעי צג, א ואילך."]]],[2300550895,"דחכ' אדם העליון שהאיר ה' פניו אליהם עד שעכ\"ד [פ\"נ] כו' וכתיב בה מימינו אש דת למו כו' שנתנה באש לבנה<sup data-n=\"8995\">1957</sup> בקול ה' מדבר מתוך האש<sup data-n=\"8996\">*1958</sup> כו' וכלול גם מן החסד. וזהו אש<sup data-n=\"8997\">1958</sup> הדלקת הנרות דמנורה שהוא אש דתורה<sup data-n=\"8998\">1959</sup> כמ\"ש הלא דברי כאש<sup data-n=\"8999\">1960</sup> כו' והוא בימין (שנק' אשא חיורא כאור המאיר בנר כו' כידוע), וזהו שגם שמנורה היה בדרום העולם הי' זה לצפון הארון כשהשכינה במערב כנ\"ל) להיות[ה] בבחינת גבו' דאש כו' (וכמו שא' ב\"ע הי' שונה ואש מלהטת סביביו כו' ויונתן ב\"ע כל עוף הפורח עליו נשרף<sup data-n=\"9000\">1961</sup> להיות שזה האש למעלה מאש דשרפים כו'). ועד\"ז יובן ג\"כ בענין השולחן שעלי[ו] לחה\"פ שזהו ג\"כ המשכת דח[כ'] דתו' רק שהוא מתלבש להיות בבחינת מזון לנשמ' כמו לחם ממש, וענין המזון ידוע שהוא כח המחבר הצו[רה] בחומר כמו כשיאכל לחם לשובע נפשו יומשך כח החכמה להתחבר במוח והמדות בלב וחיות בדם כו' [עד] שעי\"ז מתחדש אור חיות הנפש באברי הגוף ומתקיים יותר, והיינו כאשר מתברר הלחם במעיו ונבחר ממנו הטוב למזון וחיות [ב]דם שבלב ועולה גם למוח ומשם חוזר ונמשך ע\"י גידי המוח החיות הרוחני לחזק כל הגוף כו' כידוע ומבואר במ\"א, ועד שנעשה לחם אפוי שראוי למאכל צריך בירור בזריעה וקצירה ודישה וטחינה כו' עד לישה ואפי' והיינו בלחם מן הארץ דוקא משא\"כ בלחם מן השמים כמו המן שא\"צ בירור כלל כי כבר היה<sup data-n=\"9001\">1962</sup> הוברר ונמשך לאור וחיות לנשמ' כמו שהוא כמ\"ש במן ויענך וירעיבך למען תדע כו' כי<sup data-n=\"9002\">1963</sup> על כל מוצא פי הוי' כו'.\n<b>וזהו</b> ב' מדריגות דתושב\"כ ותושבע\"פ, כידוע דאותיו'<sup data-n=\"9003\">1964</sup> דתושב\"כ נקרא לחם מן השמים כמו המן שאותיות הללו הן בבחינת קדש העליון דח\"ע כמו שהוא למעלה ונמשך לנש\"י להאיר אורם כנ\"ל במנורה שמאיר מאור ח\"ע דתורה אור בעצם כנ\"ל, אבל תושבע\"פ נק' לחם מן הארץ שצריך בירור ותיקון עד שנעשה לחם ומזון והן ג\"כ<sup data-n=\"9004\">1965</sup> משנה והתלמוד שמבררים פסולת מאוכל בכל דיני המצות בפרטי[ות] כלחם מן הארץ ממש עד שנעשה למזון לנשמ' האלקי' כששונה הלכה וגורס בשיניו שזהו כטוחן המאכל ונכנס במעיו כמ\"ש ותור[תך] בתוך מע\"י ממש שמתברר ועולה מעה\"ד טו\"ר כו' ונעשה מזון האלקי לנשמ' שיתחזק בכלי יותר עד שיחי' האדם ברוחניות ממזון דתו' כמו כי אמרתך חייתני בכל האברים ברוחניות האלקי' כמו באוי\"ר שכלי' וטבעי' שזהו בכל לבבך בשני יצריך, ואף בהילוך ברגל כל היום בדרכי ה' וכן בג\"ע ילכו מחיל כו' וכמו שמכריזים בג\"ע אשרי כו' שזהו מי",[["8995","1957","<b>שנתנה באש לבנה</b>: ראה רש\"י שה\"ש ה, טז [ד\"ה ד\"ה שחורות]. מאמרי אדה\"א ויקרא ח\"ב ע' תקעח. וש\"נ."],["8996","*1958","<b>בקול. . האש</b>: ואתחנן ד, לג."],["8997","1958","<b>אש</b>: טזיט: ליתא."],["8998","1959","<b>דתורה</b>: שם: דת."],["8999","1960","<b>הלא דברי כאש</b>: ירמי' כג, ט [בדילוג — נסמן לעיל פ' בשלח רלט, א הערה 1058]."],["9000","1961","<b>ויונתן ב\"ע. . נשרף</b>: סוכה כח, א. ראה גם לעיל פ' בשלח רלט, ג. וש\"נ."],["9001","1962","<b>היה</b>: טזיט: ליתא."],["9002","1963","<b>ויענך וירעיבך </b>[טזיט: כו']<b> למען </b>תדע כו' [טזיט: ליתא] כי: עקב ח, ג [ושם: וירעיבך. . למען הודיעך]."],["9003","1964","<b>דאותיו'</b>: טזיט: ליתא."],["9004","1965","<b>ג\"כ</b>: טזיזיט: ו\"ס."]]],[2300550896,"שמילא כריסו בתלמוד<sup data-n=\"9005\">1966</sup> כו', ועד\"ז נעשה בחי' מזון [כ]זה ממש לבחי' אדם העליון דאצי' מלחם דתושבע\"פ כנ\"ל בנש\"י. וזהו שנקרא רעייתי פרנסתי שמפרנסין לאביהם שבשמים בלחמה דתורה כמ\"ש לכו לחמו בלחמי כו' ופי' בלחמי דתושב\"כ שנקרא לחמי ממש שהן אותיות עצמי' דקד\"ש דח\"ע כמ\"ש ואתא מרבבות קד\"ש, וזהו שמתחבר לחם מן הארץ בלחם מן השמים והיו לאחדים כנ\"ל בהלכות שבתושבע\"פ שמלמדים הכל מן המקרא כו' שזהו פנים מאיר[ות] שמאיר לפנים מסבירות דמל' בתושבע\"פ כידוע.\n<b>וזהו</b> ג\"כ ענין השולחן שהוא בחי' המל'<sup data-n=\"9006\">1967</sup> שמקבל מזון דלחה\"פ ונק' שולחן שלפני הוי'<sup data-n=\"9007\">1968</sup> ממש, ולחה\"פ בשבת<sup data-n=\"9008\">1969</sup> זהו כמו לחם מן השמים באור הפנימיות דח\"ע שחכמת אדם תאיר פניו כנ\"ל, ולכך נקרא לחה\"פ שכ[ו]לו פנים כפני הוי' כמו שמלובש באותיות דתושב\"כ רק שבא ומתחבר בבירור[י'] דפת דלחם מן הארץ דתושבע\"פ דוקא והוא כמו שמפרנסין לאביהם [שבשמים] כו'. וזהו הלחם שנותן על השולחן שלפני ה' בצפון (שהוא מימין לארון כשהשכינה במערב כו') לבחי' מזון וחיות לנש\"י ברוחניות לחבר האוב\"כ ממש (נשמ' בגוף כמו בק\"ש בכל לבבך, וכן בקיום המצות בפ\"מ וכה\"ג) (והעיקר דמצות לחה\"פ הוא בשבת [ב]סעודת דשבת שהוא סעודתא דע\"י כו' לאחר הבירור[י'] דחול בעוה\"ב שבא אחר הבירור דחכמה דתושבע\"פ בעה\"ד כו') (וזהו ענין ב' לחמי' דשבת<sup data-n=\"9009\">1970</sup> יח\"ע ויח\"ת שמתייחדים יחד) (ודוגמא זו בר\"ה שא' כי חק לישראל<sup data-n=\"9010\">1971</sup> כו' שזהו חק דתו' שנקרא חק ומזון כמו לחם חוקי<sup data-n=\"9011\">1972</sup> כו' וכן ותתן טרף כו' וח\"ק<sup data-n=\"9012\">1973</sup> כו' וממנו נמשך גם המזונות הגשמי' לכל השנה משולחן שבצפון שנקרא שולחן המלך כמ\"ש בזוהר [ומבואר] במ\"א).\n<b>והנה</b> ע\"ד כ\"ז היה ענין שאר הכלים שבמשכן שאינו רק לחבר האורות בכלים דוקא דוקא<sup data-n=\"9013\">1974</sup> בו' מדות בכלל והשרש הראשון הוא בח\"ע דארון ונמשך לימין ושמאל ואמצע שהן מנורה ושולחן ומזבח הזהב. והענין הוא להיות מובן [מ]כל הנ\"ל דעיקר הענין הוא במשכן שיבא העלם המקיף דרצה\"ע שביריעות (שהוא שרש המצות למעלה) בכלי ממש, כמו להתגלות דאה\"ר שברצה\"ע הנ\"ל שיאיר בגלוי בבחינות רעותא דלבא בק\"ש בכל לבבך וכמו כלה שארי ולבבי כנ\"ל ועי\"ז",[["9005","1966","<b>שמילא כריסו בתלמוד</b>: ראה גם לעיל פ' בשלח רטז, ד. וש\"נ."],["9006","1967","<b>השולחן. . המל'</b>: ראה טור ברקת סתרע\"א, ס\"ה (קכו, ד) בשם זהר תרומה [ראה שם קנג, ב — קנה, א ובמפרשים]. פרדס (שער ערה\"כ) שכ\"ג מערכת שולחן."],["9007","1968","<b>שולחן שלפני ה'</b>: ראה אמור כד, ו."],["9008","1969","<b>ולחה\"פ בשבת</b>: אמור כד, ח. תו\"כ שם. מנחות ק, א."],["9009","1970","<b>ב' לחמי' דשבת</b>: שבת קיז, ב. ראה סידור שער בהמ\"ז קי, ג. לקו\"ת עקב טו, סע\"ד."],["9010","1971","<b>כי חק לישראל</b>: תהלים פא, ה. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שנו. וש\"נ."],["9011","1972","<b>חק ומזון כמו לחם חוקי</b>: משלי ל, ח. ראה גם מאמרי אדה\"א דברים שם ע' א'שנט. וש\"נ."],["9012","1973","<b>ותתן טרף כו' וח\"ק</b>: משלי לא, טו. ראה גם לעיל פ' יתרו רעג, א."],["9013","1974","<b>דוקא</b>: טזיזיט: ליתא."]]],[2300550897,"עולה רצה\"ת לרצה\"ע שלמעלה מן הטעם לגמרי כנ\"ל. והנה התורה הוא בחינת המשכ[ה] מעליון לתחתון בב' אופנים הנ\"ל באור במנורה ומזון בשולחן [אך] יש עוד בחינת ממוצע (שהוא בבחי' ת\"ת כלול מחו\"ג עלי' וירידה כו') והוא ענין מזבח הזהב שבו מקטיר קטורת מי\"א סממנים להפוך חשך לאור וארור לברוך כו' ע\"י ריח [ה]קטורת שעולה למעלה ביותר מחכ' דתורה אור הנ\"ל, והיינו בבחי' רדכ\"ר דפנימיות הכת\"ר שלמעלה ממשפט התורה במדות דחו\"ג כו' והוא ע\"י הרח\"ר שמעוררים למעלה ע\"י התשובה והתפילה דוקא ע\"י מרירות ושפלות ביותר כמו בש\"ע שמבקשים סלח לנו רפאינו ברך עלינו כו' אף שלא כדין דתורה<sup data-n=\"9014\">1975</sup>, לפי שע\"י מרירות ותשובה נהפך הרע עצמו לטוב ומעורר הר\"ר שלמעלה מן הרצון המורכב בחכ' והוא שנקרא רצה\"ע ממש.\n<b>וזהו</b> ענין התפילה שנק' סולם<sup data-n=\"9015\">1976</sup> שראשו מגיע<sup data-n=\"9016\">1977</sup> כו' כעולה בסולם למעלה מעלה וממקום שעלה חוזר ויורד וכמ\"ש ומל[א]כי אלקי' עולי' ויורדים בו<sup data-n=\"9017\">1978</sup> כו' והן ח\"י ברכות דש\"ע<sup data-n=\"9018\">1979</sup> שהן ח\"י המשכות משם הוי' דאצי' ביתר כפי המדה כו', וא\"כ הרי התפילה נק' בחי' ממוצע להעלות לתחתון לגבי העליון ולהביא לחבר העליון בתחתון (כמו הקטרת שעולה לריח חזק בעצמו' דמקיף דרצה\"ע ומשיב וממשיך ברצון טוב מרדכ\"ר כמו שהריח הטוב והחזק משיב לנפש כו', וזהו [י]שימו קטורה באפך<sup data-n=\"9019\">1980</sup> כו' (ע\"כ יש כח [ב]קטורת לעצור המגפה [ל]הפוך ממות לחיים כמו עיד\"ע<sup data-n=\"9020\">1981</sup> תשו\"ע כו'), והוא ענין התפילה שנק' סולם להעלות במס\"נ מלמטלמ\"ע דצלותא רחמי הוא<sup data-n=\"9021\">1982</sup> כתפילה דחנה<sup data-n=\"9022\">1983</sup> כו' שזהו עומק הרצון שבלב כמו שחזקי' התפלל מקירות לבו<sup data-n=\"9023\">1984</sup> שהוא בחי' עליה דרצון התחתון שבלב לרצון העליון [ועי\"ז אח\"כ יורד ונמשך בחי' רצה\"ע ו]רדכ\"ר באותה תפילה עצמה בח\"י ברכות דש\"ע לבא בחי' גילוי<sup data-n=\"9024\">1985</sup> ברצון התחתון ([ו]כמו כ[י] חפץ [בה] המלך<sup data-n=\"9025\">1986</sup> ונקרא[ה] בשם וכך כי רוצה ה' כו' וכ[ל] א' בפרט כמו זכאה ב\"נ דקוב\"ה אתרעי ביה כו' וע\"כ נשמעת תפלתו וכרחב\"ד<sup data-n=\"9026\">1987</sup> כו').\n<b>ואמנם</b> זהו בתפילה שבחול דווקא שמברר הטוב מן הרע כו' שזהו כתמידים דכל יום שמקריבים במזבח החיצון שהוא בשם ב\"ן דמל' לברר לבהמה ע\"י אדם המקריב כו',",[["9014","1975","<b>והתפילה. . שלא כדין דתורה</b>: ראה גם מאמרי אדה\"א נ\"ך ע' שיד. תו\"ח נח נג, א."],["9015","1976","<b>התפילה שנק' סולם</b>: ראה זח\"א (רע\"מ בהשמטות) רסו, ב. ח\"ג (תוספת) שו, ב. ת\"ז תמ\"ה (פג, א)."],["9016","1977","<b>שראשו מגיע</b>: נסמן בהערה הבאה."],["9017","1978","<b>ומל[א]כי אלקי' עולים ויורדים בו</b>: ויצא כח, יב."],["9018","1979","<b>ח\"י ברכות דש\"ע</b>: ברכות כח, ב."],["9019","1980","<b>[י]שימו קטורה באפך</b>: ברכה לג, י."],["9020","1981","<b>עיד\"ע</b>: טזיזיט: ע\"י."],["9021","1982","<b>דצלותא רחמי הוא</b>: ברכות כו, א. כ, ב."],["9022","1983","<b>כתפילה דחנה</b>: שמו\"א א, י ואילך."],["9023","1984","<b>שחזקי' התפלל מקירות לבו</b>: (מל\"ב כ, ב). ישעי' לח, ב. ברכות י, ב. ראה גם ביאוה\"ז שופטים קכא, סע\"ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתיג."],["9024","1985","<b>גילוי</b>: טזיט: כלי."],["9025","1986","<b>כ[י] חפץ [בה] המלך</b>: אסתר ב, יד [ושם: כי אם חפץ]."],["9026","1987","<b>וכרחב\"ד</b>: ראה ברכות לד, ב. תענית כד, ב ואילך."]]],[2300550898,"שהוא הקרבת חו\"ד דנה\"ב בתפילה דעכשיו בחול ע\"י מרירות כו'. אבל תפלה דשבת זהו בעלי' העונג העצמי דנשמה בהתקשרות פנימיות ועצמיות כמו אז תתענג על הוי' בצלותא דמע\"ש וכנ\"ל, הגם שנק' ממוצע ג\"כ להעלות התחתון לעליון בסולם אבל זהו עלי' דפנימיות דנשמה כמו בקטורת בשמים במזבח הזהב (שזהו מיכאל כה\"ג מקריב נשמות ע\"ג מזבח הפנימי דווקא לריח בעונג העצמי דא\"ס ממש לאשתאבא כו', ולא בהעלא[ת] קרבן דבהמה בחו\"ד ע\"ג מזבח החיצון שזהו ענין תפלות החול שנגד תמידים תקנום<sup data-n=\"9027\">1988</sup> כידוע (ורק גחלים לקחו ממזבח החיצון<sup data-n=\"9028\">1989</sup> למזבח הפנימי להקטיר קטורת), וזהו אכלתי יער\"י כו' במזב\"ח החיצו\"ן ארית\"י מור\"י בקרבן דנשמות בשבת דוקא [ב]תפלה דשבת [שזהו ענין עולת שבת על עולת התמיד] כו') (ועי\"ז נמשך מעליון לתחתון ג\"כ בבחי' הפנימיות ועצמיות דעונג העליון כמו בש\"ע בחול בחיצוניות השפע ברפאינו ברך עלינו כו', והיינו המשכות הפנימיות דרצה\"ע ועונג העצמי בשבת לבא למטה בתפילה דשבת (ובסעודת שבת כו') בשביל חידוש האור ושפע לימות החול שלאחריו כמ\"ש וקראת לשבת עונג כו' כנ\"ל. ודרך כלל תפילה דמע\"ש עלי' ותפילה דיום השבת בירידה כנ\"ל, וזהו בחי' מזבח הזהב שכולל עלי' וירידה בתפלה דשבת ומזבח החיצון הוא בתפילה דחול והוא בחי' נו\"ה שכלולים בת\"ת<sup data-n=\"9029\">1990</sup> (וגם בחול זהו בחי' היכל הרצון שבאמ\"ת ויצי\"ב שבווי\"ן תתקט\"ר<sup data-n=\"9030\">1991</sup> בקשורא דנשמתא<sup data-n=\"9031\">1992</sup> כמו בריח הקטורת ואח\"כ יכול להקריב לנה\"ב בש\"ע כו' וד\"ל).\n<b>ואחר</b> כל הנ\"ל יובן ג\"כ מה שיש להפלי' על שנוי הסדר ששינה משה מן הקל\"ק<sup data-n=\"9032\">1993</sup> בג' דברים האלה ביריעות וכלים ושבת, שבפ' תרומה נצטווה על הכלים תחלה ואח\"כ [יריעות ה]משכן ואח\"כ שבת כנ\"ל ובכאן הקדים מצות שבת ואח\"כ משכן ואח\"כ כלים כו'. דהנה כל ענין הנ\"ל בענין סמיכות פ' שבת למשכן, שצ\"ל בחי' שבת תחלה ואח\"כ משכן ביריעות שהן המצות ואח\"כ כלים באור ומזון דתורה בכלים זהו הכל בבחי' ההעלאה דמקבל למשפיע שנקרא אתעדל\"ת מלמטה למעלה, אבל בבחי' ההמשכה וירידה דמשפיע למקבל הבאה מלמעלה למטה שנק' אתעדל\"ע שמצ\"ע המשפיע אז נהפוך הוא, שצ\"ל בחי' הכלים תחלה ואח\"כ היריעות דמשכן ואח\"כ מצות שבת והוא [מה] שנצטווה משה בפ' תרומה תחלה על הכלים ואח\"כ משכן ואח\"כ שבת לפי שזה היה בחי' אתעדל\"ע שמצד עצמו כו' (שאו\"פ קודם למקיפים ושבת בא בגמר ההשפעה ומלאכה וד\"ל). וביאור הענין הנה בדוגמא זאת יש מחלוקת בגמ' דח\"א שמים קדמו לארץ כמ\"ש בראשית כו' השמים ואח\"כ הארץ וח\"א ארץ קדמ[ה]<sup data-n=\"9033\">1994</sup> לשמים כמ\"ש ביום עשות ארץ ושמים<sup data-n=\"9034\">1995</sup> כו', דזהו ג\"כ כענין המחלוקת דבצלאל עם משה, דמשה נצטווה על הכלים תחלה שזהו כמ\"ד ארץ קדמה",[["9027","1988","<b>תפלות. . שנגד תמידים תקנום</b>: ברכות כו, ב."],["9028","1989","<b>גחלים לקחו ממזבח החיצון</b>: ראה גם לעיל פ' תרומה שה, ד. וש\"נ."],["9029","1990","<b>ומזבח. . נו\"ה שכלולים בת\"ת </b>[טזיט: הניחו מקום פנוי]: ראה גם לעיל תמ, א על יד הערה *1918."],["9030","1991","<b>שבווי\"ן תתקט\"ר</b>: זמירות ליל שבת — אזמר בשבחין."],["9031","1992","<b>בקשורא </b>[טזיט: בקטורא]<b> דנשמתא</b>: ראה גם לעיל פ' וארא סג, ב. וש\"נ."],["9032","1993","<b>הקל\"ק</b>: טזיט: הקצה לקצה."],["9033","1994","<b>שמים קדמו. . ארץ קדמ[ה]</b>: חגיגה יב, א."],["9034","1995","<b>ביום עשות ארץ ושמים</b>: בראשית ב, ד [בדילוג השמות]."]]],[2300550899,"לשמים ובצלאל א' מנהג העולם לעשות אהל כו' כמ\"ד שמים קדמו לארץ וכמו נוטה שמים כיריעה בבחי' מקיף לארץ כו' ושניהם אמת הוא כפי ענין הנ\"ל כו' וד\"ל.\n<b>ולהבין</b> כ\"ז הנה כל מה שמבואר למעלה בסדר פ' זו במצות שבת תחלה ואח\"כ משכן כו' זהו לפי שבשבת הוא ההעלאה דאו\"ח שיעלה רצה\"ת שבחכ' ומדות דמע\"ב מימות החול למעלה בבחי' רצה\"ע כו', והוא ע\"י ק\"ש ותפילה דכל ימות החול במס\"נ בא[חד] באה\"ר ד[ב]כל לבבך כו' כדי להמשיך ולחבר לרצה\"ע מלמעלה למטה שזהו בהמשכות המקיפים דאה\"ר העליונה שנקרא אה\"ר בתענוגים כו' כנ\"ל שזהו המשכות העונג העליון בשבת כמו העדן דעוה\"ב כו'. וידוע דבלתי העלא' מ\"נ באו\"ח מלמטה למעלה כמו בק\"ש ותפלה דחול (שעולה בליל שבת בכלות הנפש בעונג האלקי כו') לא יוכל להיות התעוררות המשכות דפנימי' רצה\"ע בשבת להמשיך אה\"ר העליונה למטה, וגם כאשר נמשך [בחי'] אה\"ר בתענוגים מן המשפיע למקבל מפנימיות העונג ורצה\"ע אינו בא למקבלים רק בבחי' מקיף מלמעלה בהעלם מרחוק עדיין לא יוכל לבא בגלוי או\"ס<sup data-n=\"9035\">1996</sup> בכלי עדיין. וזהו ענין המשכן ביריעות שהן המקיפים דלבושים [ד]מצות העליונ[ו'] שבהם מלובש האה\"ר העצמית בהעלם ומקיף עדיין, שהוא שא' בפ' [זו] אלה הדברים כו' ו' ימים תעשה מלאכה בהעלאה וביום הז' כו' שבת שבתון בירידה והמשכה להמשיך המקיפים. וזהו מה שצוה כאן על יריעות המשכן אחר מצות שבת שזהו המשכות המקיפים דאה\"ר ורצה\"ע שבמצות כו' כנ\"ל, ואח\"כ צוה על הכלים שזהו מה שנמשך מבחי' ההעלם דמקיפים דיריעות שהן המצות לגלוי בתו' אור להיות המשכה דאורות בכלים ממש, והוא בחי' ח\"ע דלוחות שבארון שמאיר באו\"פ בכלים כמו במנורה ושולחן בבחי' אור וחיות ומזון כו' לחבר האור האלקי בנש\"י בגופים כו' כנ\"ל וד\"ל.\n<b>אך</b> כ\"ז הסדר אינו אלא באתעדל\"ת מלמטלמ\"ע דוקא כנ\"ל, אבל בבחי' אתעדל\"ע שבאה מאליה מכח עצמות א\"ס ממש מלמעלמ\"ט עדיין כמו שצוה ה' אל משה בפ' תרומה ועשו לי מקדש כו', שבאתעדל\"ע זו שמצד עצמו ממש א\"א לומר שיהי' העלאה דאו\"ח בתחלה שיעלה ויעורר התעוררות למעלה מאחר שאין עוד מלבדו ממש ואין דבר חוץ מעצמותו שיעלה בהעלאה באו\"ח כענין השבת (וכמו כשעלה ברצה\"פ להאציל ע\"ס ולברוא מאין ליש ג' עולמות בי\"ע כו', שלא היה זה ע\"י",[["9035","1996","<b>או\"ס</b>: טזיטיט: או\"פ."]]],[2300550900,"העלאת מ\"ן מלמטה אחר שאין עוד מלבדו דגם שמו הגדול כלול בעצמות והוא מדת מל' העצמית כמא' שהי' הוא ושמו בלבד כו', ולא היה זה רק מצד שחפץ חסד בעצמו שמטבע הטוב להטיב כו' כמ\"ש בע\"ח). ומאחר שהאור ושפע להיות לו רצון להשתל' העולמות הי' רק באתעדל\"ע מאלי' ומעצמו, ע\"כ הוצרך להיות תחלה בחי' הצמצום כדי להיות או\"פ שהוא צמצום הראשון הנק' מק\"פ וחלל ריקן כדי שיומשך בבחי' אור בגלוי שהוא הקו\"ח) וכידוע<sup data-n=\"9036\">1997</sup> בענין נקודה קו שטח<sup data-n=\"9037\">1998</sup> דזהו מצמצום הראשון דיש\"ת חש\"ך סתר\"ו וא' יהי אור בקו\"ח והקו הזה מקור כל האוב\"כ<sup data-n=\"9038\">1999</sup> כו') וכמו מאצי' לבריאה דברישא חשוכא והדר נהורא בערב ובקר אור כו') ואח\"כ נמשך מן האור דקו\"ח גם בבחי' מקיפים כידוע בע\"ח שהקו הזה הוא מתעגל וחוזר ונמשך וחוזר ומתעגל<sup data-n=\"9039\">2000</sup> כמו בעגולים ויושר דתוהו ותיקון<sup data-n=\"9040\">2001</sup> כו'.\n<b>וזהו</b> שצוה בפ' תרומה לעשות הכלים תחלה ארון ושולחן ומנורה ואח\"כ המשכן (שהיריעות הן כשמים ושה\"ש כו') ואעפ\"י שהמקיף למעלה מן הפנימיות כשבא בהשתל' בפ\"מ (דשמים קדמו לארץ כנ\"ל), אבל לפני ההשתל' שזהו רק באתדל\"ע ברצה\"פ עדיין כו' שם סוף מעשה קודם (כמו בהתחלת הרצון [לרצון] לבנות בנין שעולה בתחלה מה שיהיה בסוף שהוא הכלים שבבית שזה הי' עיקר הכוונה בתפארת אדם לשבת כו'), ואחר כלות השפע בירידתו עד למטה מטה כמו בוימ\"ב בגמר מלאכה אז הוא זמן השביתה והמנוחה דשבת להיות בבחי' או\"ח מכל מה שירד ונמשך למטה מטה מבחי' הרצה\"ע כמו ויכולו השמים כו' וישבות כו'. וידוע שזהו כמשל מי שעוסק ועושה מלאכה שמתפשטת כח הפועל בפעולה ומלאכה זו וגם מדותיו שבלבו טרודים ונמשכים לכח הפעולה הזאת וכן במחשבתו ושכלו ורצונו הכל נמשך לפעולה זו בבת א' כידוע, ואמנם כאשר יניח ידיו מן העסק והמלאכה הזאת אז יש כמה מיני שביתה ומנוחה מתחתון לעליון והכל",[["9036","1997","<b>הקו\"ח) וכידוע</b>: שם: הקו\"ח (כידוע."],["9037","1998","<b>נקודה קו שטח</b>: ראה גם לעיל פ' תצוה שסז, ד ואילך. בשלח קפה, א. וש\"נ."],["9038","1999","<b>האוב\"כ</b>: טזיט: האו\"פ בכלים. יז: כבפנים."],["9039","2000","<b>שהקו. . מתעגל וחוזר ונמשך וחוזר ומתעגל</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א, ענף ב. שעה\"י קכא, א ואילך, ובהנסמן במ\"מ לשם."],["9040","2001","<b>בעגולים ויושר דתוהו ותיקון</b>: ראה גם לעיל פ' שמות מד, ג. וש\"נ."]]],[2300550901,"כא' והוא מיד שמניח ידיו מפעולתו ששובת ונח הכח שירד בתנועה זו שחוזר זה הכח המעשה הפנימי' (עם הרצון ושכל ומדות שבו) למעלה במקורו בנפש, וכן מדות שבלב חוזרים מהתפשטותם במעשה זו וכן המח' והחכ' והרצון למקור הרצון והשכל כו'. אך כ\"ז אינו אלא לאחר גמר המלאכה אבל בהיותו מתחיל עדיין במלאכה זו ולא גמרה היתכן לומר שישבות ויחזור למקורו וכן במדות ושכל ורצון שמתעוררים עדיין למלאכה ולא שלמו עדיין איך יתכן [מיד] ענין שביתה וחזרה למקורם מאחר שעדיין לא נתפשט כלום רק שהוא בכח ובהעלם עדיין כמו שרצונו להיות לו בנין כו', אלא בגמר מלאכתו דוקא שנתפשט החיות ובשכל ורצון במלאכה אז יתכן השביתה בכולם שנק' או\"ח למקורו הראשון וד\"ל. וכמו\"כ יובן הנמשל למעלה בענין השבת שאינו שייך רק אחר ירידה והתפשטות האור והשפע מעצמות אור א\"ס בקו\"ח באו\"כ ומקיפים ופנימי' עד סוף עולם העשיה שאז שייך מצות השבת דהיינו בבחי' או\"ח בהעלאה למעלה כנ\"ל וכמ\"ש ויכולו השמים כו' וישבות כו', אבל כאשר עדיין עלה ברצה\"פ להיות מקור להשתל' העולמות איך יתכן לומר ענין שביתה ומנוחה (אלא זהו בבחי' מנוחה העצמי' שלא ע\"י יגיעה מן המלאכה כיום שכולו שבת כו'). ובכ\"ז יתורץ הקושי' דלעיל במה ששינה משה הסדר בכאן דמצו[ה] על שבת תחלה שזהו באתעדל\"ת שעולה באו\"ח תחלה ואח\"כ משכן וכלים שהן מקיפים ופנימי' כיריעות וארון כו' מטעם הנ\"ל, אבל בפ' תרומה מדבר באתעדל\"ע כו' כשעלה ברצונו הנעלם עדיין כנ\"ל הנק' אתעדל\"ע מצד עצמו ע\"כ צוה על הכלים תחלה (משום דסומ\"ע עבמ\"ת כו' שהוא או\"כ דוקא כנ\"ל) ואח\"כ המשכן ואח\"כ שבת כו' והוא מ\"ש [ב]פ' תשא ואתה דבר כו' אך את שבתותי כו'. ומ\"ש משה לבצלאל כך שמעתי מפי ה'<sup data-n=\"9041\">2002</sup> כו' היינו שלענין מעשה באתעדל\"ת צריך לעשות המשכן תחלה וכמ\"ש ועשו לי מקדש ואח\"כ ושכנתי בתוכם כו' וז\"ש בצ\"ל א\"ל במקיף דחכ'<sup data-n=\"9042\">2003</sup> היית וידעת כו' וד\"ל.",[["9041","2002","<b>כך שמעתי מפי ה'</b>: אור החיים תרומה כה, ט (ראה לעיל תלא, ב שמציין לאוה\"ח). רש\"י פקודי לח, כב. (ראה לקו\"ש כרך טז ע' 459 הערה 19)."],["9042","2003","<b>בצ\"ל א\"ל במקיף דחכ'</b>: ראה גם מאמרי אדה\"א במדבר ח\"א ע' ריז."]]],[2300550068,"<b>בעזר\"ה שבת פ' ויקהל פקודי</b>\n<span data-k=\"pg\">1312</span> ּ<b>אלה</b> פקודי המשכן<sup data-n=\"9043\">1</sup> משכן העדות אשר פקד עפ\"י משה<sup data-n=\"9044\">2</sup> כו'. להבין ענין הכפל שכפל ב\"פ משכן פקודי המשכן משכן העדות כו'. וגם מה שאמר במשכן הראשון משכן סתם ובמשכן השני אמר משכן העדו\"ת כו'. הנה ענין המשכן בכלל ידוע שהוא ע\"ש הכתוב במשכן ושכנתי בתוכם<sup data-n=\"9045\">3</sup> שהוא בחי' מל' דאצי' שנק' שכינה<sup data-n=\"9046\">4</sup> ע\"ש ששוכן ומתלבש בתחתונים כו'. והנה עיקר ירידת הנשמה בגוף הוא כדי שיהא להקדב\"ה דירה בתחתונים ע\"י תורה ומצות שיעשה האדם כידוע מאמרם ז\"ל נתאוה הקדב\"ה להיות לו דירה בתחתונים<sup data-n=\"9047\">5</sup>, ואין הענין בבחי' מקום בתחתונים ממש שהרי הוא ית' אינו נתפס בגדר מקום כלל וכמ\"ש הנה מקו\"ם את\"י<sup data-n=\"9048\">6</sup> כו' וכתיב הלא את השמים ואת הארץ אני מלא<sup data-n=\"9049\">7</sup> דלית אתר פנוי מני'<sup data-n=\"9050\">8</sup> כו', והוא לפי שאין שינוי כלל לפניו בין קודם הבריאה לאחר הבריאה וכמ\"ש אני ה' לא שניתי<sup data-n=\"9051\">9</sup> כו' וע\"כ אנו או' אתה הוא קודם<sup data-n=\"9052\">10</sup> שנברא העולם ואתה הוא אחר שנברא העולם כו' דהיינו גם לאחר הבריאה הוא ממלא כל העולם הזה ממש כמו שהי' לפני הבריא' ואין העולם תופס מקום כו'. אלא ענין דירה בתחתונים הוא ענין תחתונים במדרגה ובמעלה, והיינו שהן תכלית וסוף כל המדרגו' שיש בהשתלשלו' מעילה לעילה כו' כמו עולם השפל הזה מקום הסט\"א שהחיצונים גוברים בו<sup data-n=\"9053\">11</sup> מאד כידוע<sup data-n=\"e1\">א</sup> ונתאוה להיו' לו דירה דוקא בתחתוני\"ם שבתכלית וסוף כל המדרגו'. וזהו ע\"י תורה ומצות שיעשה האדם בעולם השפל הזה שהוא יותר מעלה ומדרגה לנפש האלקי' גם ממה שהיתה נהנית מזיו השכינה<sup data-n=\"9054\">12</sup>",[["9043","1","<b>אלה פקודי המשכן</b>: מאמר זה הוא הנחת כ\"ק אדה\"א מדרוש אביו כ\"ק אדה\"ז משנת תקס\"ו. ראה לקו\"ת פקודי ג, א בשינויים. וראה גם הנסמן במ\"מ לשם. מאמר זה בארוכה מכ\"ק אדה\"א נדפס לקמן תנב, א. ראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י."],["9044","2","<b>אלה פקודי. . פקד עפ\"י משה</b>: פקודי לח, כא."],["9045","3","<b>ושכנתי בתוכם</b>: תרומה כה, ח."],["9046","4","<b>מל' דאצי' שנק' שכינה</b>: ראה תניא רפנ\"ב. הנסמן לעיל פ' שמות א, ד."],["9047","5","<b>נתאוה. . דירה בתחתונים</b>: ראה תניא רפל\"ו. לעיל פ' וארא ע, ג הערה 67."],["9048","6","<b>הנה מקו\"ם את\"י</b>: תשא לג, כא."],["9049","7","<b>הלא את השמים ואת הארץ אני מלא</b>: ירמי' כג, כד."],["9050","8","<b>דלית אתר פנוי מני'</b>: ראה ת\"ז תנ\"ז (צא, ב). ת\"ע (קכב, ב). שעה\"י קטז, א הערה 10."],["9051","9","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."],["9052","10","<b>אנו או' אתה הוא קודם</b>: ראה תפלת השחר. של\"ה ג, ב."],["9053","11","<b>עולם. . שהחיצונים גוברים בו</b>: ראה תניא פ\"ו (י, סע\"ב ואילך)."],["9054","12","<b>נהנית מזיו השכינה</b>: ראה ברכות יז, א.\n\n<b>א</b>  <b>מקום הסט\"א. . כידוע</b>: כ\"ז נמחק."]]],[2300550100,"בג\"ע העליון וכמארז\"ל יפה שעה א'<sup data-n=\"9055\">13</sup> בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב בעוה\"ז דוקא מטעם שנתאוה הקדב\"ה להיו' לו דירה בתחתונים דוקא וד\"ל<sup data-n=\"e2\">ב</sup>.\n<b>והנה</b> עיקר דירה זו הוא ע\"י דאתכפיא סט\"א דוקא משום דכד אתכפיא סט\"א אז אסתלק יקרא דקדב\"ה בכולהו עלמין כמ\"ש בזוהר<sup data-n=\"9056\">14</sup> ובתחלה צ\"ל אתכפיא ואח\"כ אתהפכא ממש להיו' בחי' כלי ממש לאור א\"ס בכל החושי' ראיה שמיעה דיבור ומחשבה<sup data-n=\"9057\">15</sup> כו', וזהו מ\"ש לע\"ל בנשמות הצדיקים היכל ה' המה<sup data-n=\"9058\">16</sup> ג\"פ נגד קדוש קדוש ג\"פ<sup data-n=\"9059\">17</sup> כו'. ויש להבין למה אסתלק יקרא דקדב\"ה דוקא מזה דאתכפיא סט\"א כו' והלא אין הסט\"א תופס מקום כלל וכלל בההשתלשלו' כידוע ע\"ד הכתוב שממית בידים תתפש<sup data-n=\"9060\">18</sup> כו' כמו שאין השממית תופסת מקום בהיכלי מלך כו'. אך הענין יובן בהקדים תחלה שרש ענין מצות עשה ומצות ל\"ת, דהנה ידוע מאמרם ז\"ל דרמ\"ח מ\"ע נרמז בזכרי עם ו\"ה<sup data-n=\"9061\">19</sup> ושס\"ה ל\"ת בשמי עם י\"ה וזהו זה שמי לעלם<sup data-n=\"9062\">20</sup> כו' וא\"כ לכאורה יפלא דידוע די\"ה נק' נסתר\"ו' וכמ\"ש הנסתרו' לה' אלקינו<sup data-n=\"9063\">22</sup> שהוא בחי' י\"ה כי בי\"ה צור עולמי'<sup data-n=\"9064\">23</sup> כו' והנגלות הן ו\"ה<sup data-n=\"9065\">21</sup> (והיינו פי' זה שמי שהוא י\"ה וזה זכרי ו\"ה וכמו שהשם עיקר והזכ\"ר של השם טפל לגבי עיקר השם כו' כך ו\"ה עם זכר\"י טפל לגבי שמי עם י\"ה כו'), ולפ\"ז שרש המל\"ת גבוה ממ\"ע וזהו שאמרו דעבר על מ\"ע<sup data-n=\"9066\">24</sup> ושב מוחלין לו מיד משא\"כ מל\"ת שצריך תשובה ויוה\"כ כו'<sup data-n=\"e3\">ג</sup>, והאיך יתכן שיהי' ל\"ת גבוה ממ\"ע אחרי אשר במ\"ע יש בחי' גילוי אלקו' כידוע דרמ\"ח פקודי' רמ\"ח איברי' דמלכא<sup data-n=\"9067\">26</sup> כו' ובמל\"ת לא יש שום גילוי אלקו' אלא הוא רק מניעת המעשה בשב ואל תעשה כמו לא תאכל חלב<sup data-n=\"9068\">27</sup> וכיוצא כו'.\n<b>אך</b> הענין הוא דאדרבה היא הנותנת דמשום דהל\"ת הוא בשב ואל תעשה לכך גבוהי' ממ\"ע כו' ויובן זה בהקדים <span data-k=\"pg\">תרנו</span> ּ תחלה",[["9055","13","<b>יפה שעה א'</b>: אבות פ\"ד, מי\"ז."],["9056","14","<b>דכד אתכפיא סט\"א. . בזוהר</b>: בלקו\"ת כאן: בזהר פ' תרומה דקכ\"ח [ב]. . וע' ג\"כ ר\"פ יתרו [סז, ב]. ראה גם הנסמן במאמרי אדה\"א שמות ח\"א ע' ה."],["9057","15","<b>בכל החושי'. . ומחשבה</b>: ראה גם לקו\"ת פקודי כאן (ג, א)."],["9058","16","<b>היכל ה' המה</b>: ירמי' ז, ד. ראה גם לעיל פ' בשלח רלז, א. וש\"נ."],["9059","17","<b>היכל. . ג\"פ. . קדוש ג\"פ</b>: ישעי' ו, ג. ראה גם לקמן תמז, ד. לקו\"ת שלח לח, ג."],["9060","18","<b>שממית בידים תתפש</b>: משלי ל, כח. ראה גם ש\"א מח, ב."],["9061","19","<b>דרמ\"ח מ\"ע נרמז בזכרי עם ו\"ה</b>: בלקו\"ת פקודי כאן (ג, ב) מציין: בת\"ז בהקדמה ד' ד' סע\"ב וד' ה' ע\"א ע\"פ זה שמי (וראה גם בהנסמן במ\"מ לשם). ראה גם לעיל פ' בא קיד, א הערה 152."],["9062","20","<b>זה שמי לעלם</b>: שמות ג, טו."],["9063","22","<b>הנסתרו' לה' אלקינו</b>: נצבים כט, כח."],["9064","23","<b>כי בי\"ה צור עולמי'</b>: ישעי' כו, ד [בדילוג]."],["9065","21","<b>די\"ה נק' נסתר\"ו'. . והנגלות הן ו\"ה</b>: ראה ת\"ז ת\"ע (קכט, א). הנסמן במ\"מ בלקו\"ת פקודי כאן (ג, ב)."],["9066","24","<b>דעבר על מ\"ע</b>: יומא פו, א."],["9067","26","<b>דרמ\"ח פקודי'. . דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). שע\"ת עב, ג הערה 17."],["9068","27","<b>לא תאכל חלב</b>: ראה ויקרא ג, יז.\n\n<b>ב</b>  <b>וד\"ל</b>: נמחק.\n<b>ג</b>  <b>וזהו שאמרו. . כו'</b>: כ\"ז נמחק."]]],[2300550132,"ענין רמ\"ח מ\"ע, דהנה ידוע פי' רמ\"ח איברי' דמלכא שהוא עד\"מ האבר שמלובש בו חיו' הנפש כמו כח השכל שבמוח הרי מתאחד השכל עם עצמו' הנפש והיו לאחדים שהרי א\"א להפריד השכל מן הנשמה, ואע\"פ שיש לשכל מקום וכלי מיוחד לשכון בו והוא המוח עכ\"ז לא נפרד עדיין מגוף ועצמו' הנשמה ועד\"ז שאר כל חיו' וכחות הנפש שמתפשטי' ומתלבשים באיברים כולם מתאחדים עם עצמו' הנפש כו', ועכ\"ז הם שוכנים בכלים מיוחדי' כאו\"א בפ\"ע כו'. וכך יובן הדוגמא למעלה בבחי' אורו' וכלים העליונים שהן הנק' רמ\"ח איברי' דמלכא הרי כולם מתאחדי' עם עצמו' אור המאציל המשפיע כו', וכמאמר הידוע דאיהו וחיוהי וגרמוהי<sup data-n=\"9069\">28</sup> חד בהון פי' חיוה\"י הן האורו' די\"ס דאצי' שנשפעות מעצמו' המאציל וגרמוה\"י הן בחי' הכלים שהן כמו האיברי' עד\"מ וכמ\"ש על הכסא דמות כמראה אד\"ם<sup data-n=\"9070\">29</sup> כו' וכידוע וכולא חד בתכלית היחוד וד\"ל<sup data-n=\"e4\">ד</sup>.\n<b>והנה</b> יש בזה ב' מדרגו' א' איברי' החיצונים והב' אברי' הפנימי' כמו עד\"מ באדם התחתון יש בו ב' מיני אברי' הללו ואיברים הפנימי' חיותם יותר פנימי עד שרוב איברי' הפנימי' נקובתן במשהו<sup data-n=\"9071\">30</sup> כידוע משא\"כ איברים החיצונים כו'. והנמשל יובן למעלה דאע\"פ שאין לו גוף<sup data-n=\"9072\">31</sup> ולא דמות הגוף כו' כמ\"ש כי לא אד\"ם הוא<sup data-n=\"9073\">32</sup> כו' עכ\"ז דברה תורה כלשון בנ\"א<sup data-n=\"9074\">33</sup> לשכך<sup data-n=\"9075\">35</sup> האזן<sup data-n=\"9076\">34</sup> כו', ויש גם למעלה באדם העליון דאצי' בחי' איברים פנימיי\"ם שבמשהו מסתלק אורם כו'<sup data-n=\"e5\">ה</sup> שהרי נאמר יאר ה' פניו אליך<sup data-n=\"9077\">36</sup> כו' משמע שיש בחי' פנימי' ובחי' חיצוניו' וכמו וראית את אחורי ופני לא יראו<sup data-n=\"9078\">37</sup> כו'<sup data-n=\"9079\">38</sup>. ודרך כלל ענין הפנימי' למעלה הוא מלובש בתורה דוקא משום דאוריי' מחכמה נפק'<sup data-n=\"9080\">39</sup> וכתיב בחכמה חכמת אדם תאי\"ר פני\"ו<sup data-n=\"9081\">40</sup> כו' שהחכמ\"ה תאיר אור הפנימי' וכענין צהבו פניו של רבי<sup data-n=\"9082\">41</sup> כו' שהוא מפני גילוי החכמה שתאיר את הפנימי' להיו' בגילוי. וכך למעלה חכמת אד\"ם העליון תאיר פניו להיו' יאר ה' פני\"ו אליך כו', והוא ע\"י מה שהקדב\"ה יושב ועוסק בתורה למעלה כשאדם התחתון יושב ועוסק בתורה למטה וכמארז\"ל דכל הקורא ושונה הקדב\"ה קורא",[["9069","28","<b>דאיהו וחיוהי וגרמוהי</b>: ראה ת\"ז בהקדמה (ג, ב)."],["9070","29","<b>על הכסא דמות כמראה אד\"ם</b>: יחזקאל א, כו [ושם: ועל דמות — ראה גם לעיל פ' שמות כח, ג הערה 60]."],["9071","30","<b>שרוב איברי' הפנימי' נקובתן במשהו</b>: ראה הנסמן בש\"ך סק\"ג ובאר היטב סק\"ב לשו\"ע יו\"ד הל' טריפות סכ\"ט."],["9072","31","<b>שאין לו גוף</b>: ע\"פ פיוט יגדל. רמב\"ם בפיה\"מ סנהדרין פ\"י היסוד הג'."],["9073","32","<b>כי לא אד\"ם הוא</b>: שמו\"א טו, כט."],["9074","33","<b>דברה תורה כלשון בנ\"א</b>: ברכות לא, ב."],["9075","35","<b>לשכך האזן</b>: מכילתא יתרו יט, יח. תנחומא שם יג."],["9076","34","<b>דברה תורה. . לשכך האזן</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ס\"ע תשלד."],["9077","36","<b>יאר ה' פניו אליך</b>: נשא ו, כה."],["9078","37","<b>וראית את אחורי ופני לא יראו</b>: תשא לג, כג."],["9079","38","<b>כו'</b>: כ\"ה בגוכתי\"ק."],["9080","39","<b>דאוריי' מחכמה נפק'</b>: נסמן לעיל פ' יתרו רסח, ד."],["9081","40","<b>חכמת אדם תאי\"ר פני\"ו</b>: קהלת ח, א."],["9082","41","<b>צהבו פניו של רבי</b>: חולין ז, ב.\n\n<b>ד</b>  <b>וד\"ל</b>: נמחק.\n<b>ה</b>  <b>שבמשהו. . כו'</b>: כ\"ז נמחק."]]],[2300550164,"ושונה כנגדו<sup data-n=\"9083\">42</sup> כו' וכשהקדב\"ה קורא ושונה למעלה הרי חכמת אדם תאיר פניו ויש בחי' הארת פנים למעלה מפני גילוי אור חכמתו ית' כי מצד עצמו הוא חכים ולא בחכמה ידיעה<sup data-n=\"9084\">43</sup> כו', אך בגילוי החכמה יאיר פניו אלינו כמו שאנו או' כי באור פניך<sup data-n=\"9085\">44</sup> נתת לנו תורת חיים כו' וזהו בעסק התורה, ואמנם בעסק מעשה המצות אור ההמשכה היא למעלה בבחי' חיצוניו' והן רמ\"ח מ\"ע בפרט ובכלל הוא ת\"ת שכנגד כולם<sup data-n=\"9086\">45</sup> להיותו בבחי' הפנימי' של כללות כולם כנ\"ל. וזהו והנגלו\"ת לנו ולבנינ\"ו הן תורה ומצות והם אותיו' ו\"ה שבשם הוי' הוי\"ו הוא בעסק התורה שיהא הקדב\"ה יושב ושונה כנגדו כנ\"ל והה\"א הוא במעשה המצות (וזהו זכר\"י עם ו\"ה שעולה רמ\"ח כו', כמו שהזכרון של השם אינו עיקר השם כך הקורא בתורה הגם שקורא בשמותי\"ו<sup data-n=\"9087\">46</sup> של הקדב\"ה אך אינו רק בחי' <span data-k=\"pg\">1314</span> ּ זכרון של שמותי\"ו העצמיים, שהרי צרופי אותיו' התורה אינו אלא בבחי' התלבשו' לבושי' בלבד כמ\"ש עוטה אור כשלמה<sup data-n=\"9088\">47</sup> כו'. וכן במעשה המצות אין בהם רק בחי' זכרו\"ן שמו\"ת בלבד, ויחודי' שנעשי' עי\"ז אינם באים רק בהתלבשו' כו'. וזהו לכו חזו מפעלו' אלקי'<sup data-n=\"9089\">48</sup> אשר שם שמו\"ת בארץ א\"ת שמו' אלא שמו\"ת<sup data-n=\"9090\">49</sup> אשר ש\"ם שמות ולא השמו\"ת כעצמו' אלא רק אשר שם אותם בלבושי' כו' וד\"ל).\n<b>אבל</b> הנסתרות לה' אלקינו כו' היינו שס\"ה ל\"ת שהם יותר גבוהי' בשרשם ממ\"ע ונק' נסתר\"ו' והוא באותיו' י\"ה שבשם הוי' שנק' נסתרו' כנ\"ל. וביאור טעם הדברים הנה תחלה יש להקדים ביאור ענין י\"ה כו', דהנה כתיב והחכמה מאין תמצא<sup data-n=\"9091\">50</sup> שהחכמה היא בחי' ראשית הגילוי בהשתלשלו'<sup data-n=\"9092\">51</sup> וכמ\"ש ראשית חכמה<sup data-n=\"9093\">52</sup> כו' והיינו מפני שהחכמה נק' כח מ\"ה<sup data-n=\"9094\">53</sup> כו' והוא היו\"ד דשם הוי'<sup data-n=\"9095\">54</sup> כמארז\"ל ביו\"ד נברא העוה\"ב פי' בחכמ\"ה<sup data-n=\"9096\">55</sup> נברא העוה\"ב שהוא בחי' בינה<sup data-n=\"9097\">56</sup> והשגה באלקו' להיו' נהנין מזיו כו' ונק' יש<sup data-n=\"9098\">57</sup> כמ\"ש להנחיל אוהבי יש<sup data-n=\"9099\">58</sup> כו' והיינו מאין ליש, ואמנם לפני התהוו' גם אור החכמה מאי\"ן כו' הוא עדיין לפני כל ההשתלשלו' דשם הוי' כו', ושם אמרו בס\"י לפני אחד מה אתה סופר<sup data-n=\"9100\">59</sup> מפני שהוא למעלה מחושבן י\"ס וכמאמר אנת הוא",[["9083","42","<b>דכל הקורא. . ושונה כנגדו</b>: ראה תדא\"ר רפי\"ח. לעיל פ' וארא נח, ג הערה 18."],["9084","43","<b>חכים ולא בחכמה ידיעה</b>: ז\"ח יתרו לד, ד. ת\"ז בהקדמה (יז, ב). ראה גם לעיל פ' יתרו רסו, סע\"ד ואילך."],["9085","44","<b>שאנו או' כי באור פניך</b>: בסיום תפלת העמידה."],["9086","45","<b>ת\"ת שכנגד כולם</b>: פאה רפ\"א."],["9087","46","<b>הקורא בתורה. . שקורא בשמותי\"ו</b>: ראה גם לעיל פ' תצוה שנט, ד. וש\"נ."],["9088","47","<b>עוטה אור כשלמה</b>: תהלים קד, ב."],["9089","48","<b>לכו חזו מפעלו' אלקי'</b>: נסמן לעיל פ' יתרו רנג, א."],["9090","49","<b>א\"ת שמו' אלא שמו\"ת</b>: ברכות ז, ב. ראה גם לעיל פ' וארא עה, ג."],["9091","50","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["9092","51","<b>שהחכמה. . ראשית הגילוי בהשתלשלו'</b>: ראה לקו\"ת שה\"ש כו, ד. וש\"נ. לקמן תנג, ד."],["9093","52","<b>ראשית חכמה</b>: תהלים קיא, יא. ראה גם לעיל רסד, ב הערה 29."],["9094","53","<b>שהחכמה נק' כח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א. ראה לעיל פ' שמות לג, א. וש\"נ."],["9095","54","<b>שהחכמה. . היו\"ד דשם הוי'</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."],["9096","55","<b>ביו\"ד נברא העוה\"ב פי' בחכמ\"ה</b>: ראה מנחות כט, ב. ראה גם לעיל פ' בשלח קנט, ד. תצוה שסז, א. לקמן תנג, ד. מאמרי אדה\"א בראשית ע' קנב. וש\"נ. ש\"א מא, א ובהערה 7."],["9097","56","<b>העוה\"ב. . בינה</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'רי. וש\"נ. שערי אורה עה, א ובהערה 13."],["9098","57","<b>העוה\"ב. . ונק' יש</b>: ראה גם לקמן תנג, ד. לעיל פ' שמות לד, סע\"א. וש\"נ."],["9099","58","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["9100","59","<b>לפני אחד מה אתה סופר</b>: נסמן לעיל פ' תרומה שיב, ד."]]],[2300550196,"חד ולא בחושבן<sup data-n=\"9101\">60</sup> כו' והוא בחי' אור הכתר הנק' עילת העילות<sup data-n=\"9102\">61</sup> כידוע<sup data-n=\"e6\">ו</sup> שאינו מושג כלל וכלל וכמאמר אפי' אור צח כו' אוכ\"ם הוא לגבי עילת העילו'<sup data-n=\"9103\">62</sup> כו' משום דלית מחשבה תפיס' בי' כלל<sup data-n=\"9104\">63</sup> כו' וד\"ל<sup data-n=\"e7\">ז</sup>.\n<b>והנה</b> ארז\"ל דברייתו של עולם ברישא חשוכא<sup data-n=\"9105\">64</sup> והדר נהורא כו' פי' לפי שבחי' עילת העילות<sup data-n=\"e8\">ח</sup> הוא אור פשוט וסתום ומופלא<sup data-n=\"e9\">ט</sup> א\"א שיבא ממנו אור וגילוי שפע בבחי' השתלשלו' מעילה לעילה כמו להיו' מציאו' החכמה ממנו נמצאת וכמ\"ש והחכמ\"ה מאי\"ן תמצ\"א כו', כ\"א כאשר יתעלם האור בבחי' צמצום והסתר תחלה ואח\"כ ישפיע האור ואזי יוכל להיו' מציאו' השתלשלו' ממנו כו'. וכמ\"ש ישת חוש\"ך סתר\"ו<sup data-n=\"9106\">65</sup> דהיינו ברישא חשוכ\"א והדר נהור\"א להיו' מציאו' אור החכמה להיו' נק' חכי\"ם כו' וכמ\"ש יהי או\"ר שהוא החכמה<sup data-n=\"9107\">66</sup> שנק' אור והוא אחר שקדם לו החושך שהוא ההעלם וכמ\"ש וחוש\"ך ע\"פ תהום<sup data-n=\"9108\">67</sup> כו'<sup data-n=\"e10\">י</sup>, וא\"כ הרי עיקר ההשפעה נשאר בבחי' ההעלם ולא נגלה רק אפס קצהו באור החכמה כו' וכמ\"ש ישת חוש\"ך סתר\"ו כו' ושם לית מחשבה דחכמ' תפיס' בי' כלל כנ\"ל. ואמנם קצת גילוי יש משם ולא שיהא מושג ממש אחר דלית תפיס' בי' כו' אלא מושג הוא בדרך השליל\"ה כו', והוא במ\"ה שבחכמ\"ה<sup data-n=\"9109\">68</sup> בבחי' הביטול כלומר מ\"ה פשפשת מה ידעת<sup data-n=\"9110\">69</sup> כו' וכמ\"ש משה ונחנו מ\"ה<sup data-n=\"9111\">70</sup>, כי מ\"מ משיג הוא איך שאינו מושג כו'. וזהו שרש ענין שס\"ה ל\"ת לא תאכל חלב וכיוצא ששרשם הוא למעלה מכל ההשתלשלו' שאין האור בא משם כ\"א בבחי' ביטול כו' וע\"כ א\"צ רק שלא יהא מסתיר ומנגד לבחי' הביטול דמ\"ה והוא שלא יאכל חלב המסתיר כו' ובשב ואל תעשה זה יוכל לשכון בחי' מ\"ה כו', והיינו מפני שמלמעלה למטה הלאו קודם להן<sup data-n=\"9112\">71</sup> כנ\"ל ואע\"פ שמלמטה למעלה הה\"ן קודם ללאו אבל מלמעלה מן ההשתלשלו' הלא\"ו קודם כו' וזהו בארץ ל\"א זרועה<sup data-n=\"9113\">72</sup> שנזרע בחי' לא\"ו דל\"ת והוא כברייתו של עולם מלמעלה למטה דברישא חשוכ\"א והדר נהורא כנ\"ל וד\"ל<sup data-n=\"e11\">יא</sup>.",[["9101","60","<b>אנת הוא חד ולא בחושבן</b>: ת\"ז בהקדמה (יז, א)."],["9102","61","<b>הכתר הנק' עילת העילות</b>: ראה פרדס (שער אם הא\"ס הוא הכתר) ש\"ג, ספ\"א."],["9103","62","<b>אפי' אור צח. . עילת העילו'</b>: ראה ת\"ז ת\"ע (קלה, ב). לעיל פ' שמות יב, ב הערה 548."],["9104","63","<b>דלית מחשבה תפיס' בי' כלל</b>: ראה ת\"ז בהקדמה (יז, א)."],["9105","64","<b>דברייתו של עולם ברישא חשוכא</b>: ראה שבת עז, ב."],["9106","65","<b>ישת חוש\"ך סתר\"ו</b>: תהלים יח, יב."],["9107","66","<b>יהי או\"ר שהוא החכמה</b>: נסמן לעיל בפ' תשא שפה, א."],["9108","67","<b>וחוש\"ך ע\"פ תהום</b>: בראשית א, ב."],["9109","68","<b>במ\"ה שבחכמ\"ה</b>: ראה גם לעיל פ' בשלח רי, א. שמות לג, א."],["9110","69","<b>מ\"ה פשפשת מה ידעת</b>: זהר בהקדמה ב, א."],["9111","70","<b>וכמ\"ש משה ונחנו מ\"ה</b>: בשלח טז, ז. ח."],["9112","71","<b>הלאו קודם להן</b>: ראה גם מאמרי אדה\"א נ\"ך ע' רלו. וש\"נ. שה\"א צ, ב ואילך. לעיל פ' בשלח קלז, ד. לקמן תמו, ב. תנב, ד. תנד, ד."],["9113","72","<b>בארץ ל\"א זרועה</b>: ירמי' ב, ב.\n\n<b>ו</b>  <b>והוא בחי'. . כידוע</b>: כ\"ז נמחק.\n<b>ז</b>  <b>כו' וד\"ל</b>: נמחק.\n<b>ח</b>  <b>שבחי' עילת העילות</b>: שאור א\"ס ב\"ה כשמו כן.\n<b>ט</b>  <b>אור פשוט וסתום ומופלא</b>: אין לו קץ ותכלית ולכן.\n<b>י</b>  <b>וכמ\"ש וחוש\"ך. . כו'</b>: כ\"ז נמחק.\n<b>יא</b>  <b>כנ\"ל וד\"ל</b>: נמחק."]]],[2300550228,"<b>וזהו</b> ששם עלו שבטים<sup data-n=\"9114\">73</sup> שבטי י\"ה עדו\"ת לישראל להודו' לשם הוי' פי' שבטי י\"ה הן <span data-k=\"pg\">תרנז</span> ּ שרשי חו\"ב<sup data-n=\"9115\">74</sup> מלמעלה מכל ההשתלשלו' ששם על\"ו שבטים כו' ע\"י מצות ל\"ת דוקא מטעם הנ\"ל בענין בארץ ל\"א זרועה כו', ונק' נסתרו' לה' אלקינו כו' למעלה מהנגלות לנו ע\"י תורה ומצות כי לא יוכל האור לשכון בבחי' כלי אלא רק בבחי' השלילה בלבד כו' והוא בלאו דל\"ת כו'. ואזי עדו\"ת לישראל להודו\"ת לשם הוי' פי' עי\"ז נמשך בחי' הודי' וביטול דמ\"ה כנ\"ל כשאין מסתיר ומנגד כו' וכמ\"ש לא תחללו<sup data-n=\"9116\">75</sup> לא תעשו חלל<sup data-n=\"9117\">76</sup> וחסרון ואז ממילא ישכון כו', ולזה צריך עדו\"ת דוקא כי<sup data-n=\"e12\">יב</sup> לנגלות לנו ולבנינו<sup data-n=\"e13\">יג</sup> א\"צ עדות אלא לנסתרו\"ת דוקא צריך עדו\"ת, וזהו עדו\"ת לישראל להודו' לשם הוי' והעדו\"ת הוא בא מבחי' ההעלם דעצמו' אור א\"ס ב\"ה הנק' עילת העילות כנ\"ל וד\"ל<sup data-n=\"e14\">יד</sup> (וזהו הטעם דשמ\"י עם י\"ה הן שס\"ה ל\"ת שהן בעיקר השם להיותם בשרשם מבחי' החושך וההעלם שקדם לאור והוא הלאו שקודם להן כנ\"ל וד\"ל) וזהו הטעם דכד אתכפיא סט\"א דוקא אסתלק יקר\"א דקדב\"ה כו' וד\"ל.\n<b>וזהו</b> אלה פקודי המשכן, משכן העדות כו'. הנה מה שכפל לומר ב\"פ משכן, משכן סתם ומשכן העדות כו', הענין של משכן סתם הוא בחי' תורה ומצות שהן באותיו' ו\"ה כמ\"ש למעלה. וזהו אלה פקודי המשכן פי' אל\"ה כמ\"ש שאו מרום עיניכם וראו מ\"י ברא אל\"ה<sup data-n=\"9118\">77</sup> פי' בחי' המדות שנולדו מן השכל וההתבוננו' היינו בחי' אל\"ה שנמשכו ממי היא בחי' בינ\"ה<sup data-n=\"9119\">78</sup> אם הבנים<sup data-n=\"9120\">79</sup>, וכידוע בפי' לך ה' הגדולה<sup data-n=\"9121\">80</sup> והגבורה כו' שהן ששה מדו' גדולה וגבור' ותפארת ונצח הוד יסוד וכולם המה בטילי' במקור המולידם והוא מ\"ש ל\"ך הוי' כו' אותיו' ל\"ך היינו חמשים שערי בינה<sup data-n=\"9122\">81</sup> כו', וגם פי' מי ברא אלה כך הוא הענין שששה המדות נק' אל\"ה לשון רבים ומ\"י הוא אשר בראם והולידם כו' וכמ\"ש לך ה' הגדולה כו' ועל מדה השביעי' בחי' מלכו' אמר במאמר בפ\"ע לך ה' הממלכה כו' וד\"ל<sup data-n=\"e15\">טו</sup>. והטעם שנק' אל\"ה כי כל מדה כלולה מן הששה חסד שבחסד גבורה שבחסד כו' עולה",[["9114","73","<b>ששם עלו שבטים</b>: תהלים קכב, ד."],["9115","74","<b>י\"ה. . חו\"ב</b>: נסמן לעיל בפ' משפטים רפז, א."],["9116","75","<b>לא תחללו</b>: נסמן לעיל פ' תצוה שנז, ב הערה 54."],["9117","76","<b>לא תחללו לא תעשו חלל</b>: ראה גם לעיל פ' תצוה שנז, ב. וש\"נ. לקמן תנו, ד."],["9118","77","<b>שאו מרום עיניכם. . אל\"ה</b>: ישעי' מ, כו."],["9119","78","<b>ממי. . בינ\"ה</b>: זהר משפטים קיז, א. פרד\"ס (שעה\"כ) שכ\"ג מערכת מי. ע\"ח שער הכללים פ\"ד. (שער המוחין) ש\"כ, פ\"ג. לקו\"ת להאריז\"ל ויצא (סוד יעקב עם ב' נשיו)."],["9120","79","<b>בינ\"ה אם הבנים</b>: נסמן לעיל בפ' משפטים רצו, ב."],["9121","80","<b>לך ה' הגדולה</b>: דהי\"א כט, יא."],["9122","81","<b>אותיו' ל\"ך היינו חמשים שערי בינה</b>: ראה גם לקמן תנה, ג. תו\"ח ויצא קעה, ד ובהערה 6.\n\n<b>יב</b>  <b>כי</b>: עד\"מ למטה.\n<b>יג</b>  <b>לנו ולבנינו</b>: נמחק.\n<b>יד</b>  <b>הנק'. . וד\"ל</b>: כ\"ז נמחק.\n<b>טו</b>  <b>וד\"ל</b>: נמחק."]]],[2300550259,"מספר ל\"ו שהוא בגי' אל\"ה<sup data-n=\"9123\">82</sup>, וגם אל\"ה אותיו' לא\"ה<sup data-n=\"9124\">83</sup> כמ\"ש בלא\"ה שילדה ששה בנים שהן ששה מדו'<sup data-n=\"9125\">84</sup> למעלה ואחר ילדה בת ושמה דינה<sup data-n=\"9126\">85</sup> פי' דינא<sup data-n=\"9127\">88</sup> דמלכות\"א<sup data-n=\"9128\">87</sup> דינא<sup data-n=\"9129\">86</sup> כו' וד\"ל<sup data-n=\"e16\">טז</sup>. וזהו אל\"ה פקודי המשכ\"ן פי' פקוד\"י הוא כמו ענין פקידה ליחוד זכר ונקבה כענין מארז\"ל חייב אדם לפקו\"ד את אשתו<sup data-n=\"9130\">89</sup> כו' והוא מענין התקשרות ויחוד כמ\"ש פקד פקדת\"י אתכם<sup data-n=\"9131\">90</sup> כו'. ופי' משכן הוא בחי' משכן דלתתא שהיא ה\"א אחרונה שבשם הוי' למעלה, ולמטה הן בחי' כנ\"י בכלל, והפקידה לפקוד אותם היינו בחי' יחוד ו\"ה הנ\"ל כענין לפקו\"ד את אשתו כו' והוא ע\"י מצות הנגלות לנו ולבנינו כנ\"ל, והעיקר הוא ע\"י התורה שהוא אות הוי\"ו כנ\"ל והן שיתא סדרי משנה זרעים מועד כו' שהן ששה<sup data-n=\"e17\">יז</sup> מדו'<sup data-n=\"9132\">91</sup> העליונו' למעלה ולמטה מלובשי' בשית סדרי משנה כו' וכל א' כלול מן הששה כי הרי סדר זרעים שהוא בחי' אור החסד הוא בלול גם ממשניו' דסדר מועד וכל השאר סדרים ועד\"ז גם סדר מועד בלול מסדר זרעים כי כאו\"א כלול מכולם <span data-k=\"pg\">1316</span> ּ כו', ועי\"ז עולה מספר אל\"ה בכלל וממספר אל\"ה שבשיתא סדרי משנה נעשה בחי' יחוד דתורה ומצו' בכנ\"י בכנ\"י<sup data-n=\"9133\">92</sup>, ולהיו' כי השכינה שורה בכנ\"י ונק' משכן סתם וחייב אדם לפקו\"ד את אשת\"ו כו' ע\"כ אמר אל\"ה פקודי המשכן פי' באל\"ה הוא פקוד\"י המשכן. ומה שאמר פקוד\"י לשון רבים כי רבי\"ם הם בחי' פרטי היחודי' שברמ\"ח מ\"ע שהרי על כל מצוה ומצוה בפרט אנו או' לשם יחוד<sup data-n=\"9134\">93</sup> קדב\"ה ושכינתי' כו' וד\"ל<sup data-n=\"e18\">יח</sup>.\n<b>וכל</b> זה בחי' משכן סתם והוא אותיו' ו\"ה הנגלו' לנו וזהו אל\"ה מענין ולשון התגלות כאומר לנוכח אל\"ה ה\"ם כו'<sup data-n=\"e19\">יט</sup>. אבל משכן העדות אינו בבחי' ההתגלות כלל כי הוא בחי' משכן דלעילא שבבחי' י\"ה שבשם הוי' שנק' נסתרו\"ת כנ\"ל, ולכך נק' משכן העדות כמ\"ש למעלה בענין הפסוק ששם עלו שבטי' שבטי י\"ה עדו\"ת לישראל כו', והוא בבחי' שרש המל\"ת שלא באו למטה בבחי' כלים מכלים שונים אלא רק בדרך השלילה מפני שהלא\"ו קודם להן משום שנא' ישת חוש\"ך סתר\"ו כו' וכנ\"ל וד\"ל<sup data-n=\"e20\">כ</sup>.",[["9123","82","<b>ל\"ו שהוא בגי' אל\"ה</b>: ראה לקמן תמח, ג. הנסמן לעיל בפ' משפטים רצא, ד."],["9124","83","<b>אל\"ה אותיו' לא\"ה</b>: ראה גם לקמן תמז, א. תנה, ג. תו\"ח ויצא קע, ב ובהערה 21."],["9125","84","<b>בלא\"ה שילדה ששה בנים שהן ששה מדו'</b>: ויצא ל, כ. ראה גם לעיל פ' שמות יח, א. וש\"נ."],["9126","85","<b>ואחר ילדה בת ושמה דינה</b>: נסמן לעיל פ' משפטים רצו, ד."],["9127","88","<b>דינא דמלכות\"א דינא</b>: נדרים כח, א."],["9128","87","<b>דינה. . דמלכות\"א</b>: ראה לקו\"ת להאריז\"ל פ' ויצא (ענין בני לאה — צא, ב בשם הזהר)."],["9129","86","<b>דינה פי' דינא דמלכות\"א דינא</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ס\"ע תשפח ואילך (בשם הזהר). ע' תתח. לקו\"ת ראה כא, ג. ש\"א ל, ב. מאמרי אדה\"א דברים ח\"ג ס\"ע א'ט ואילך."],["9130","89","<b>חייב אדם לפקו\"ד את אשתו</b>: יבמות סב, ב. ראה גם לקו\"ש פקודי (כרך כו) ע' 286."],["9131","90","<b>פקד פקדת\"י אתכם</b>: שמות ג, טז."],["9132","91","<b>שיתא סדרי משנה. . ששה מדו'</b>: נסמן לעיל בפ' תצוה שסב, ד הערה 70."],["9133","92","<b>בכנ\"י בכנ\"י</b>: כ\"ה בגוכתי\"ק."],["9134","93","<b>על כל מצוה ומצוה בפרט אנו או' לשם יחוד</b>: נסמן לעיל פ' תצוה שלט, ב הערה 747.\n\n<b>טז</b>  <b>כו' וד\"ל</b>: נמחק.\n<b>יז</b>  <b>ששה</b>: בחי' ששה.\n<b>יח</b>  <b>וד\"ל</b>: נמחק.\n<b>יט</b>  <b>כאומר. . כו'</b>: נמחק.\n<b>כ</b>  <b>וד\"ל</b>: נמחק."]]],[2300550289,"<b>אך</b> הנה הטעם שקורא למשכן זה בשם משכן העדו\"ת דוקא הנה מלבד שצריך עדות לפי שהן בבחי' הנסתרות כו' יש עוד טעם למה שנק' עדו\"ת, ויובן בהקדים תחלה ענין הפסוק רבבה כצמח השדה כו' ותרבי כו' ותבואי בעד\"י עדיי\"ם<sup data-n=\"9135\">94</sup> כו'. פי' כצמח השדה עד\"מ צמח השדה שלא יצמח כ\"א בבחי' הביטול וההתכללות שלו בתחלה בכח הצומח שממנו לוקח בתחלתו והוא רקבון הגרעין<sup data-n=\"9136\">95</sup> ואח\"כ יצמיח בו כח הצומח, והוא לפי שלא יוכל להיות התהוות יש מיש כו' כ\"א כאשר יבא בחי' היש לבחי' הביטול באי\"ן תחלה כו' וכמ\"ש במ\"א. וכך יובן בכנ\"י בגלות מצרים שהיו משועבדי' שם בתכלית שזהו כמשל רקבון הגרעין כו' והיינו בבחי' לב נשבר ונדכא כו' עד שנעשו בחי' אי\"ן ואח\"כ צמחו וגדלו וכמ\"ש ויפרו וירבו מאד<sup data-n=\"9137\">96</sup> כו' וזכו אח\"כ לקבל התורה בבחי' יחוד עליון פב\"פ כו', וזהו רבבה כצמח השדה כו' וע\"כ ותרב\"י ותגדל\"י כו' וד\"ל<sup data-n=\"e21\">כא</sup>. ואח\"כ ותבואי בעד\"י עדיי\"ם פי' עדי זה ע\"ד הפשוט הוא ענין הקישוט<sup data-n=\"9138\">97</sup> שנק' עדי כידוע, והענין הוא כמ\"ש בעטר\"ה שעטר\"ה לו אמ\"ו כו' והיינו ביום חתונת\"ו בשעת מ\"ת<sup data-n=\"9139\">98</sup> כשאמרו נעשה ונשמע שאז נתעטר כאו\"א מישראל בבחי' עטרה מעד\"י וקישוט ע\"י המלאכים<sup data-n=\"9140\">99</sup> כמ\"ש ויתנצלו בנ\"י את עדיי\"ם<sup data-n=\"9141\">100</sup> מהר חורב כו'. וביאור ענין עטרה זאת מבחי' קישוטין הרבה היינו בחי' אור הכת\"ר שנק' עטרה עד\"מ עטרה המקפת על הראש מלמעלה כו', כך נמשך אור א\"ס שבבחי' כת\"ר עליון בבחי' מקיף והעלם על כאו\"א מישראל והיינו בעטר\"ה שעטר\"ה לו אמו<sup data-n=\"e22\">כב</sup>, והוא הארת בחי' רעוא דכל רעוין<sup data-n=\"9142\">101</sup> שמתגלה בעטרה וכתר זה וכמ\"ש אנכי ה' אלקיך<sup data-n=\"9143\">102</sup> אשר הוצאתיך אנכ\"י מי שאנכי<sup data-n=\"9144\">103</sup> דלא ידע לי' בר איהו<sup data-n=\"9145\">104</sup> כו' ונק' ג\"כ בשם סתימו דכל סתימין<sup data-n=\"9146\">105</sup> והוא רעוא דכל רעוין הנק' רצון פשוט<sup data-n=\"e23\">כג</sup> כו'. אך בחי' הכלי לזה האור הפשוט אינו אלא בבחי' ההעלם ולא יוכל לבא בכלי ממש, וזהו הענין של הקישוטין של העד\"י כו', וזהו הנק' ג\"כ כת\"ר תור\"ה פי' בחי' הכת\"ר והעטרה בחי' אור המקיף שגנוז ומלובש בלבוש <span data-k=\"pg\">תרנח</span> ּ עטרה כעטרה על הראש והוא למעלה מבחי' גילוי אור החכמה שבתורה כו' וד\"ל. וזהו ותבואי בעד\"י עדיים והיינו ע\"י",[["9135","94","<b>רבבה כצמח השדה. . בעד\"י עדיי\"ם</b>: יחזקאל טז, ז."],["9136","95","<b>רקבון הגרעין</b>: בלקו\"ת כאן מציין לתו\"א ויקהל פט, ג. וראה גם לעיל בפ' שמות ב, ג ובהערה 94."],["9137","96","<b>ויפרו וירבו מאד</b>: ויגש מז, כז. וראה לקמן תנו, ב הערה 234."],["9138","97","<b>עדי. . הקישוט</b>: ראה רש\"י יחזקאל שם (בשם דונש). אוה\"ת יחזקאל ע' תח."],["9139","98","<b>בעטר\"ה. . ביום חתונת\"ו בשעת מ\"ת</b>: שה\"ש ג, יא. תענית כו, ב. ראה מאמרי אדה\"א דברים ח\"ג ע' תתמז בהערה."],["9140","99","<b>כשאמרו נעשה ונשמע. . עטרה. . ע\"י המלאכים</b>: ראה שבת פח, א."],["9141","100","<b>ויתנצלו בנ\"י את עדיי\"ם</b>: תשא לג, ו."],["9142","101","<b>רעוא דכל רעוין</b>: נסמן לעיל פ' תצוה שנח, ב."],["9143","102","<b>אנכי ה' אלקיך</b>: יתרו כ, ב."],["9144","103","<b>אנכ\"י מי שאנכי</b>: נסמן לעיל בפ' יתרו רנד, ג."],["9145","104","<b>דלא ידע לי' בר איהו</b>: נסמן לעיל פ' ויקהל שפח, א."],["9146","105","<b>סתימו דכל סתימין</b>: ראה זהר בהקדמה ב, א. ועוד.\n\n<b>כא</b>  <b>וד\"ל</b>: נמחק.\n<b>כב</b>  <b>והיינו. . אמו</b>: נמחק.\n<b>כג</b>  <b>והוא רעוא. . פשוט</b>: נמחק."]]],[2300550316,"מל\"ת דוקא ששרשם בבחי' ההעלם שבכת\"ר שלאו קודם להן וכמ\"ש ישת חושך סתרו והן הלאוין שבי' הדברו' לא תרצח<sup data-n=\"9147\">106</sup> כו' וד\"ל<sup data-n=\"e24\">כד</sup>.\n<b>והנה</b> יש עוד פי' שני בלשון עד\"י והוא ענין ולשון נצחיות כמו עד\"י ע\"ד<sup data-n=\"9148\">107</sup> והוא ג\"כ ע\"ד הנ\"ל לפי שענין הנצחיו' עדי עד הוא בבחי' ההעלם שבכתר זה כו', וכענין מלך משובח ומפואר עד עד<sup data-n=\"9149\">108</sup> שמו הגדול כו' שאין לו הפסק גם בתשבחו' שכל מה שאתה משבח יותר עדיין אין לו הפסק<sup data-n=\"e25\">כה</sup>, וכן ענין הכל ירוממו\"ך סלה<sup data-n=\"9150\">109</sup> שירוממו עד אין שיעור למעלה כי כל מקום שאמר נצח סלה ועד אין לו הפסק<sup data-n=\"9151\">110</sup> כו' מפני שאור א\"ס אין לו שיעור למעלה בעילוי אחר עילוי כו' וכמ\"ש במ\"א וד\"ל<sup data-n=\"e26\">כו</sup>. ועוד יש פי' שלישי בפי' עד\"י והוא מלשון הפסק<sup data-n=\"9152\">111</sup> דוקא כמו עד כאן תחום שבת<sup data-n=\"9153\">112</sup> וכן עד ולא עד בכלל<sup data-n=\"9154\">113</sup> כו' ומ\"מ ענין א' הוא עם בחי' הנצחיו'<sup data-n=\"e27\">כז</sup> הנ\"ל וטעם א' להם, כי ענין ההפסק הזה רצונו לומר שכל מה שתוכל להלל ולהודות עדיין לא תגיע גם לחצי שבחו, וה\"ז כענין הפסק עד כאן ולא יותר וה\"ז מפני שאין לו שיעור למעלה בעילוי אחר עילוי כו'. וזהו פי' משובח ומפואר עד\"י ע\"ד בבחי' נצחיו' וגם בבחי' ההפסק דהיינו שגם אם תגיע לעילוי היותר גדול עדיין עד ולא עד בכלל מפני שלא תגיע לעולם לאורו האמיתי כו' וא\"כ הכל ענין א' וטעם א' וד\"ל<sup data-n=\"e28\">כח</sup>. וכל ג' הפרושי' הללו הכל ענין וטעם א' שהוא מפני שנק' סתימו דכל סתימין כו' וזהו ותבואי בעד\"י עדיים כו' (אך מה שאמר בעדי עדיים לשון רבים וגם לשון יחיד דהיינו שיש עדיים רבים ויש עדי אחד שהוא מקור כל העדיים ונק' עד\"י עדיי\"ם כו', הענין הוא לפי שהרבה כתרי\"ם יש כמו ג' כתרים<sup data-n=\"9155\">114</sup> כת\"ר תורה וכת\"ר כהונה וכת\"ר מלכו' כו' אך כת\"ר שם טוב עולה על גביהן כו' והוא נק' מקור כל הכתרי\"ם ומקור כל העדיי\"ם הנ\"ל והוא בחי' רעוא דכל רעוין הנ\"ל שהוא מקור כל הכתרי\"ם כו' וד\"ל. ובאמת פי' עד\"י עדיי\"ם רצונו לומר על ענין שאין שיעור כלל לעדיים וכתרי' עד רום המעלות בעילוי אחר עילוי זו למעלה מזו והיינו בעדי עדיו' הרבה עד אין שיעור ומטעם הנ\"ל ולא שיקצוב המדה לומר בחי' מקור לעדיים כו' וזהו פי' יותר אמיתי בפשט הכתוב וד\"ל). ובכל זה יובן ג\"כ מה שקורא למשכן העליון",[["9147","106","<b>לא תרצח</b>: יתרו כ, יג."],["9148","107","<b>עד\"י. . עד\"י ע\"ד</b>: ישעי' כו, ד. ראה רש\"י יחזקאל שם (בשם מנחם). לעיל פ' שמות ה, ג הערה 255."],["9149","108","<b>מלך משובח ומפואר עדי עד</b>: ברכת ברוך שאמר."],["9150","109","<b>הכל ירוממו\"ך סלה</b>: ברכת יוצר לשבת. ראה גם לקמן תנו, ד. מאמרי אדה\"א בראשית ע' ס. וש\"נ."],["9151","110","<b>כל מקום שאמר. . אין לו הפסק</b>: ערובין נד, א."],["9152","111","<b>עד\"י והוא מלשון הפסק</b>: ראה גם לקמן תמז, ג. תנז, א. לקו\"ת כאן ה, א. אוה\"ת ישעי' ע' רי."],["9153","112","<b>עד כאן תחום שבת</b>: ערובין נח, סע\"ב (במשנה)."],["9154","113","<b>עד ולא עד בכלל</b>: ברכות כו, ב."],["9155","114","<b>ג' כתרים</b>: ראה אבות פ\"ד, מי\"ג.\n\n<b>כד</b>  <b>וד\"ל</b>: נמחק.\n<b>כה</b>  <b>שאין לו. . הפסק</b>: כ\"ז נמחק.\n<b>כו</b>  <b>וכמ\"ש במ\"א וד\"ל</b>: נמחק.\n<b>כז</b>  <b>הנצחיו'</b>: נמחק.\n<b>כח</b>  <b>שכל מה שתוכל. . וד\"ל</b>: עד כאן יש איזו השגה ולא עד בכלל כי הכתר אינו מושג כלל ונק' ישת חשך סתרו."]]],[2300550341,"די\"ה כו' בשם משכן העדו\"ת דוקא שהוא לפי ששרש יחוד זה די\"ה ע\"י מל\"ת מגיע בבחי' הכתרים והעדיי\"ם הנ\"ל וכמ\"ש ותבואי בעד\"י עדיי\"ם כו' לכך נק' משכן העדו\"ת ויתפרש בעדו\"ת זה כל הג' פרושי' הנ\"ל וכן במ\"ש ששם עלו שבטי' כו' עדו\"ת לישראל כו' ענין עדו\"ת זה הוא ג\"כ ע\"ד הנ\"ל בפי' ותבואי בעד\"י עדיי\"ם כו' וד\"ל<sup data-n=\"e29\">כט</sup>.\n<b>אשר</b> פק\"ד על פי משה כו'. הנה הכוונה בזה הוא שמשכן העדות דוקא פקד על פי משה ואדסמיך לי' דוקא קאי ולא אפקידה דאל\"ה פקודי כו', שהרי שם מזכיר לשון רבים אל\"ה פקוד\"י כו' ובמשכן העדות שהבדיל והפסיק הענין להכפיל ולומר<sup data-n=\"e30\">ל</sup> משכן העדו' הרי עליו דוקא הוא אומר אשר פק\"ד על פי משה כו'. <span data-k=\"pg\">1318</span> ּ וביאור הדבר הנה ידוע דבחי' משה הוא בחי' מ\"ה וכמ\"ש ונחנו מ\"ה<sup data-n=\"9156\">115</sup>, והרי מבואר למעלה שזכו לבא בעד\"י עדיי\"ם דהיינו בבחי' אור הכתר שמשם נמשך יחודא עילאה די\"ה שע\"י מל\"ת שהלאו קודם להן מפני שאינו מושג כו' וע\"כ א\"א להשיגו בהשגה אלא רק בבחי' מ\"ה והוא רק בבחי' הביטול כמו ההשתחואה וכיוצא (כענין שמצינו בר' עקיבא שהי' כורע ומשתחווה בש\"ע עד שאדם מוצא בזוית זו<sup data-n=\"9157\">116</sup> כו' לפי שא\"א לאור ההשגה בבחי' כת\"ר עליון לבא בגילוי בשכל ודעת או כלי המדו' אלא רק בבחי' הביטול כמו ההשתחווא' בלבד והוא בהעדר הכלי כו' וד\"ל<sup data-n=\"e31\">לא</sup>). וזהו אשר פק\"ד על פי מש\"ה שהוא בחי' מ\"ה על ידו דוקא נפק\"ד פקידה ויחוד העליון די\"ה הנק' משכן העדו\"ת דוקא מטעם הנ\"ל וד\"ל<sup data-n=\"e32\">לב</sup>.\n<b>והנה</b> בשעה שיצאו ישראל ממצרים נא' רבבה כצמח השדה נתתי\"ך כנ\"ל ואח\"כ ותרב\"י ותגדל\"י כנ\"ל והי' תחלת ההגדלה בז' ימי הפסח במה שצווה לאכול מצה וכמ\"ש מצות יאכל את ז' הימים<sup data-n=\"9158\">117</sup> פי' ז' הימים הן ז' המדות חו\"ג כו', והיו תחלה בבחי' קטנות המוחי' בלבד והוא אשר נולד בהם האהבה מצד השכל וההתבוננו' בלבד אבל שתהא האהבה והדביקו' מצד עצמו' אור א\"ס שלמעלה מן ההשגה כו' לא היו יכולי' עדיין להגיע למדרגה זו משום שזהו מבחי' יחוד העליון די\"ה שאור א\"ס שורה שם כנ\"ל. ולכך נצטוו לאכול מצה שענין המצה הוא",[["9156","115","<b>מש\"ה. . מ\"ה. . ונחנו מה</b>: בשלח טז, ז. ח. ראה גם לעיל פ' שמות מג, א. וש\"נ."],["9157","116","<b>בר' עקיבא שהי' כורע ומשתחווה. . שאדם מוצא בזוית זו</b>: ברכות לא, א."],["9158","117","<b>מצות יאכל את ז' הימים</b>: בא יג, ז. ראה גם לעיל פ' בא קכא, א.\n\n<b>כט</b>  <b>וד\"ל</b>: נמחק.\n<b>ל</b>  <b>ולומר</b>: ולומר עליו.\n<b>לא</b>  <b>והוא בהעדר. . וד\"ל</b>: נמחק.\n<b>לב</b>  <b>וד\"ל</b>: נמחק."]]],[2300550365,"המשכת בחי' מ\"ה והוא בחי' הביטול כמו שנראה לעין שאין במצה התנשאו' כמו בחמץ ושאור כו', ובחי' הביטול הזה שבמצה יביאם לקבל מדרגת קבלת התורה פב\"פ להיו' באים בעד\"י עדיי\"ם, ולכך הי' מצות מצה ענין הכנה לקבלת התורה בכל הכתרי\"ם הנ\"ל עד מקור כל הכתרי\"ם הנק' רעוא דכל רעוין וסתימו דכל סתימין כנ\"ל. וזהו מצות יאכל את ז' הימי' פי' יאכל זה היינו לשון מפעיל הוא כמו מאכיל דהיינו שיאכילו את ז' הימים ממצה<sup data-n=\"9159\">118</sup>, והענין הוא להמשיך בחי' מ\"ה שבמצה בכל ז' המדו' דקטנו' ולהיו' נמשך בהם מבחי' הביטול דמ\"ה ואזי יוכלו כנ\"י לקבל בחי' יחוד העליון הנ\"ל בענין משכן העדו' אשר פק\"ד עפ\"י משה כו' וזהו ותרבי ותגדל\"י במצה שאכלו ז' הימי' ואח\"כ ותבוא\"י בעד\"י עדיי\"ם כו' וד\"ל<sup data-n=\"e33\">לג</sup>.\n<b>והנה</b> בסדר התפלה אנו מוצאי' ככל ענין הנ\"ל בפי' אלה פקודי המשכן משכן העדו\"ת כו'. דהנה ידוע שבפסוק ראשון דק\"ש שמע ישראל ה' אלקינו כו' הוא בחי' יחודא עילא'<sup data-n=\"9160\">119</sup> די\"ה הנ\"ל הנק' נסתרות לה' אלקינ\"ו כו' והוא ענין משכן העדו\"ת אשר פקד עפ\"י מש\"ה כו' ובפסוק ואהבת בכל לבבך כו' הענין הוא בבחי' אהבה הנמשכת מן השכל והטעם<sup data-n=\"9161\">120</sup> כו', והוא ענין<sup data-n=\"e34\">לד</sup> יחודא תתאה כמו שאמר אל\"ה פקודי המשכ\"ן כו' וכנ\"ל בענין שאו מרום כו' וראו מ\"י ברא אל\"ה כו' וד\"ל<sup data-n=\"e35\">לה</sup>. אך הנה קודם ק\"ש תיקנו אנשי כה\"ג פסוקי דזמרה<sup data-n=\"9162\">122</sup> והענין של פסוקי דזמרה הוא כדי שיוכלו להגיע בפסוק ראשון דק\"ש ליחוד העליון דה' אלקינו הנק' נסתרו' כנ\"ל, ואם לא השיר והזמרה בפסוקי דזמרה א\"א לבא למדרגת היחוד הזה כו', וזה הי' עבודת הלוים בשיר וזמרה<sup data-n=\"9163\">123</sup> כו' והיו נושאים את המשכן וכמ\"ש ונשאו הלוים<sup data-n=\"9164\">124</sup> כו' והקימו המשכן<sup data-n=\"9165\">125</sup> כו'.\n<span data-k=\"pg\">תרנט</span> ּ<b>אך</b> הטעם איך שע\"י פסוקי דזמרה בשיר ורננה דוקא יגיעו לבחי' היחוד העליון הזה יובן בהקדים תחלה ענין שיר הלוים כו', דהנה כתיב והחיות רצוא ושוב כמראה הבזק<sup data-n=\"9166\">126</sup> פי' כמו הלהב שמן הבזק שעולה ויורד וחוזר ועולה וחוזר ויורד וכך הוא",[["9159","118","<b>יאכל. . שיאכילו את ז' הימים ממצה</b>: ראה גם לעיל שם. שער האמונה כג, א ובהערה 1."],["9160","119","<b>שמע ישראל. . יחודא עילא'</b>: ואתחנן ו, ד. זהר בראשית יח, ב."],["9161","120","<b>ואהבת. . אהבה הנמשכת מן השכל והטעם</b>: ואתחנן ו, ה [בדילוג]. בלקו\"ת כאן מציין לתו\"א כט, ב."],["9162","122","<b>תיקנו אנשי כה\"ג פסוקי דזמרה</b>: ראה שו\"ע אדה\"ז חאו\"ח סנ\"א, ס\"א-ב. וראה גם לקמן תמח, א. הנסמן במאמרי אדה\"א שמות ח\"א ע' רפט־ ח\"ב ע' שפא־ תו\"ח בראשית לה, ד הערה 66. מכתב להרי\"ף, י\"ט אייר, צ\"ט (נדפס ברשימות חוברת קנח הערה א]."],["9163","123","<b>עבודת הלוים בשיר וזמרה</b>: ראה בסמוך בפנים."],["9164","124","<b>ונשאו הלוים</b>: וכ\"ה לקמן תמז, ד. תנח, ג. בלקו\"ת פקודי כאן (ה, ג): ”בני גרשון ובני מררי נושאי המשכן (בפ' בהעלותך יו\"ד י\"ז) בני קהת נושאי המקדש\" — שם כא [ושם: ונסעו הקהתים]."],["9165","125","<b>והקימו המשכן</b>: בהעלותך י, כא [בהשמטת תיבת: את. וכ\"ה בגור ארי' שם. לקמן תמח, א על יד הערה 100. ראה בסמוך בפנים על יד הערה 134]. ובלקו\"ת כאן: ”ובחנות המשכן יקימו אותו הלוים (במדבר א' נ\"א)\"."],["9166","126","<b>והחיות רצוא ושוב כמראה הבזק</b>: יחזקאל א, יד. ראה רש\"י שם. מאמרי אדה\"א קונטרסים ס\"ע תלט ואילך ובהנסמן לשם.\n\n<b>לג</b>  <b>וד\"ל</b>: נמחק.\n<b>לד</b>  <b>אהבה. . ענין</b>: כ\"ז נמחק.\n<b>לה</b>  <b>וד\"ל</b>: נמחק."]]],[2300550385,"בתמידות וכמו כשלהבת הנר שמתנענע תמיד בבחי' אור חוזר ואור ישר, כך נפש האלקי' שבאדם שנק' נר ה' וכמ\"ש נר ה' נשמת אדם<sup data-n=\"9167\">127</sup> צ\"ל עולה ויורד בבחי' רצוא ושוב בתמידות בלתי הפסק, והוא ב' מיני התפעלו'<sup data-n=\"9168\">128</sup> שבאהבה בבחי' אור חוזר כמו כלה שאירי לבבי<sup data-n=\"9169\">129</sup> כו' ובבחי' אור ישר כמ\"ש אהבת עולם אהבתיך<sup data-n=\"9170\">130</sup> ע\"כ משכתיך חסד כי רוח אייתי רוח<sup data-n=\"9171\">131</sup> ואמשיך רוח כידוע. אך צ\"ל ב' מיני התפעלו' הללו זא\"ז בתמידו' וכמ\"ש והחיות רצוא ושוב פי' אחר הרצוא שוב ואחר השוב רצוא וכן חוזר חלילה כו' ועי\"ז עולה נפש האלקי' ממדרגה למדרגה עד רום המעלות כו', וזהו ענין שיר הלוים על הקרבן<sup data-n=\"9172\">132</sup>. וזהו ג\"כ הענין שנשא\"ו את המשכן כו' מפני שע\"י השיר ברצוא ושוב מגביהי' ומרוממי' למשכן עד שנעשה גם בחי' יחוד העליון בבחי' משכן העדו\"ת הנ\"ל, וכך הוא ענין פסוקי דזמרה לפני ק\"ש ענין הכנה לרומם הנפש עד שתוכל לייחד יחוד העליון בפסוק ראשון דק\"ש באמרו ה' אלקינ\"ו כו' וד\"ל<sup data-n=\"e36\">לו</sup>. וזהו ששם עלו שבטים כו' להודות לשם הוי' פי' להודות בבחי' הודי' מלמטה למעלה וגם מלמעלה למטה כי במה שאמר להודו' לשם הוי' יתכן ב' הפרושי' מלמטה למעלה ומלמעלה למטה והוא בחי' אור ישר וא\"ח רצוא ושוב כמראה הבזק כנ\"ל כמשל האור של הנר שמתנענע כו' וד\"ל.\n<b>וזהו</b> אשר פקד ע\"פ משה עבודת הלוים ביד איתמר בן אהרן הכהן. (דהנה עבודת הלוים הוא לשאת המשכן ולרוממו כו' וכמ\"ש ונשאו את המשכן<sup data-n=\"9173\">133</sup> כו' והקימו את המשכן<sup data-n=\"9174\">134</sup> כו' וזהו עיקר עבודת הלוים כידוע. והנה פשט הכתוב משמעו שעפ\"י משה פקד גם עבודת הלוים, כי מה שאמר אשר פקד עפ\"י משה עבודת הלוים ביד איתמר כו' קאי אשר פקד גם על מה שלאחריו דהיינו עבודת הלוים וגם על מה שלפניו והוא משכן העדות, וכך רצונו לומר אלה פקודי כו' משכן העדו' אשר פקד המשכן עפ\"י משה עבודת הלוים לשאת המשכן ועל שניהם או' אשר פקד כו', ומה שאמר ביד איתמר ענין שלישי הוא שביד איתמר כל העבודה הזאת כו', וביאור ענין אשר פקד עפ\"י משה גם עבודת הלוים לנשאת המשכן כו'). הנה אותיו' פקד הם אותיו' דפ\"ק<sup data-n=\"9175\">135</sup>",[["9167","127","<b>נר ה' נשמת אדם</b>: משלי כ, כז."],["9168","128","<b>רצוא ושוב. . ב' מיני התפעלו'</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרל ואילך."],["9169","129","<b>כלה שאירי לבבי</b>: תהלים עג, כו [ושם: שארי ולבבי]."],["9170","130","<b>אהבת עולם אהבתיך</b>: ירמי' לא, ב [ושם: ואהבת — נסמן לעיל בפ' וארא סב, ג הערה 131]."],["9171","131","<b>רוח אייתי רוח</b>: נסמן לעיל בפ' יתרו רנא, א."],["9172","132","<b>שיר הלוים על הקרבן</b>: ראה ר\"ה ל, ב ואילך. לעיל פ' בא קו, ד ואילך. וש\"נ."],["9173","133","<b>ונשאו את המשכן</b>: נשא ד, כה [ושם: את יריעות המשכן — וראה גם לקמן תנט, א. לקו\"ת פקודי ח, א]."],["9174","134","<b>והקימו את המשכן</b>: בהעלותך י, כא. וראה לעיל הערה 125."],["9175","135","<b>פקד הם אותיו' דפ\"ק</b>: ראה שער מאמרי רשב\"י (ז, א) לת\"ז תס\"ט (קז, א) הובא בכסא מלך שם (קמח, ב) אות פ: קפ\"ד כמנין דפ\"ק וזהו סוד פקד.\n\n<b>לו</b>  <b>וד\"ל</b>: נמחק."]]],[2300550402,"וכמבואר בספרי הקבלה שהדפק שרשו מבחי' אחוריי' דחכמה (והוא שם קפ\"ד אחוריי' דאבא<sup data-n=\"9176\">136</sup> כו') וכמ\"ש קול דודי דופ\"ק<sup data-n=\"9177\">137</sup> כו', והענין הוא דבחי' רצוא ושוב הנ\"ל שרשו נמשך מבחי' הדפק כי אנו רואי' בחוש שיש בדפק ענין עלי' וענין ירידה דהיינו הסתלקו' החיו' והתפשטו' החיות והם באים זא\"ז בתמידו' והוא ענין הדפק בלב שהוא הנשימה, וגם בדפק היד נרגש העלא' והמשכה זו בתמידו'. וכך למעלה בחי' רצוא ושוב כמראה הבזק שבעבודת הלוים לנשאת המשכן שרשם הוא מבחי' הדפק העליון שהוא בחי' <span data-k=\"pg\">1320</span> ּ הסתלקו' והתפשטו' והוא מה שאמר אשר פק\"ד עפ\"י משה עבודת הלוים שהוא מבחי' אחוריי' דמ\"ה דמשה שהן אותיו' דפ\"ק היפוך אותיו' פק\"ד, אך משכן העדו' פק\"ד עפ\"י משה מבחי' פנימי' כו' וכנ\"ל. ואמנם דוקא בחכמה הוא שיש התפשטו' והסתלקו' והוא בא בהתלבשו' בדפק אבל בבחי' בינה אין שם הסתלקו' אלא התפשטו' בלבד והיינו ענין הדם המתפשט בשס\"ה גידי' שנא' בו כי הדם הוא הנפש<sup data-n=\"9178\">138</sup> דהיינו עיקר המחי' אך ע\"י בחי' החכמה נעשה בגידי הדם בחי' הדפ\"ק כו', והן בחי' יחוד עליון הנ\"ל די\"ה ע\"י מל\"ת דלאו קודם להן כו' וזהו קול דודי דופק שהוא יחוד חו\"ב תרין ריעין<sup data-n=\"9179\">139</sup> כו', וזהו אשר פקד עפ\"י משה גם עבודת הלוים ברצוא ושוב למטה כו' וד\"ל.\n<b>ומה</b> שאמר ביד איתמר בן אהרן כו' הענין הוא שלא ישאר האדם רק בבחי' זו דרצוא ושוב בלבד כי אין זה תכלית הכונה אלא צריך שימשיך זה בבחי' כלי שישכון בו בחי' הביטול הזה בבחי' רצוא ושוב (כמו מראה הבזק שיש כלי לאור שעולה ויורד בו כך צריך להיו' בחי' כלי לאור ישר ואור חוזר שבנפש האלקי', והיינו מ\"ש נר ה' נשמת אדם כמו שהנר בחי' כלי לאור המתנענע בו כך האדם צריך להיו' כלי לנשמה שבו. ומה שנק' נשמה הוא מפני בחי' הנשימה<sup data-n=\"9180\">140</sup> שהוא כמו בחי' הדפק בבחי' רו\"ש ועיקר זה הוא בחכמה שנק' נשמה כידוע בפי' נר\"נ שהרו\"ח במדו' והנשמה<sup data-n=\"9181\">142</sup> בחכמה<sup data-n=\"9182\">141</sup> כו'). והנה בחי' הכלי לאור דרו\"ש הוא הדיבור בד\"ת דוקא וכמ\"ש בפ' דק\"ש אחר ואהבת ברצוא ושוב כנ\"ל ודבר\"ת ב\"ם בשבתך בביתך<sup data-n=\"9183\">143</sup> כו'. פי' ודבר\"ת",[["9176","136","<b>שהדפק. . קפ\"ד אחוריי' דאבא</b>: ראה טעמי המצות להאריז\"ל פ' וירא."],["9177","137","<b>קול דודי דופ\"ק</b>: שה\"ש ה, ב. ראה גם לעיל פ' בא קד, ג. וש\"נ."],["9178","138","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג."],["9179","139","<b>חו\"ב תרין ריעין</b>: נסמן לעיל בפ' תצוה שמז, ב."],["9180","140","<b>נשמה. . הנשימה</b>: ראה גם לעיל פ' תצוה שיח, ד. וש\"נ."],["9181","142","<b>והנשמה בחכמה</b>: ראה גם לעיל בפ' בא קד, ג. שערי אורה י, ב."],["9182","141","<b>שהרו\"ח במדו' והנשמה בחכמה</b>: ראה אבן עזרא משפטים כג, כה. לעיל פ' בשלח קמה, א."],["9183","143","<b>ודבר\"ת ב\"ם בשבתך בביתך</b>: ואתחנן ו, ז."]]],[2300550419,"שתמשיך רו\"ש הזה בבחי' כלי והוא באותיו' התורה ודוקא כשיש בדיבור זה בחי' הביטול וע\"ד המבואר במ\"א ע\"פ ואשים דברי בפיך<sup data-n=\"9184\">144</sup> שאינו רק כלי לדבר ה' זו הלכה<sup data-n=\"9185\">145</sup> שאומר בפיו ואזי הדיבור בחי' כלי לרו\"ש כו' וד\"ל<sup data-n=\"e37\">לז</sup>.\n<b>וזהו</b> ביד איתמר פי' איתמר מלשון (אתאמר שכבר אמור וכענין פי' איתמר שבגמ'<sup data-n=\"9186\">146</sup> שכבר איתמר אלא שהוא בלשון תרגום וכאן אמר איתמר בלה\"ק, ועוד משמעות) איתמר שממילא איתמר<sup data-n=\"9187\">147</sup>, וכענין אז נדברו יראי ה'<sup data-n=\"9188\">148</sup> שענינו הוא ענין הדיבור אשר הוא בא ממילא ומאליו ששייך לומר נדבר\"ו לשון נפעל ממילא, שאם הדיבור בא מצד עצמם הי' לו לומר מדברים או דוברים אלא נדבר\"ו היינו כאשר נדבר הדיבור בהם ממילא. וכך הענין בפי' איתמר בלשון תרגום שנאמר ממילא כו' והוא בדבר ה' שנאמר ממילא מפני שהדיבור של האדם הוא בתכלית הביטול בעצמותו עד שאין הדיבור בא מצד עצמו כלל אלא נדבר בו דבר ה' זו ההלכה ממילא ומאליו וכענין אז נדבר\"ו יראי ה' כו'. וזהו כדוגמת לימוד המשניו' שלמד הרב ב\"י שאמר לו המגיד אני המשנה המדברת בפיך<sup data-n=\"9189\">149</sup> כו', וכענין שכינה מדברת מתוך גרונו<sup data-n=\"9190\">150</sup> של משה כו' וד\"ל<sup data-n=\"e38\">לח</sup>. וזהו ענין ודבר\"ת בם שאחר ואהבת שהוא לעשו' כלי בבחי' הביטול להיו' ואשי\"ם דבר\"י בפיך כו', וכן לענין מעשה המצות המה ג\"כ בחי' כלים אלא שהן מתחלקי' באופנים שונים, ועכ\"ז הרי כללו' כולם הוא שיהא בחי' כלי לשכון בו <span data-k=\"pg\">תרס</span> ּ בחי' קדושה העליונ' וכמ\"ש ועשיתם את כל מצותי<sup data-n=\"9191\">151</sup> והייתם קדושי\"ם לאלקיכם אני ה' אלקיכם<sup data-n=\"9192\">152</sup>, שיש בזה בחי' ההעלא' וההמשכה כנ\"ל והמצוה היא בחי' כלי לזה כמ\"ש כי נר מצוה<sup data-n=\"9193\">153</sup> כו' וד\"ל<sup data-n=\"e39\">לט</sup>. ונמצא כללות סדר התפלה בפסד\"ז וק\"ש ואהבת ודברת בם כו' היינו כסדר האמור בפסוק זה דאלה פקודי כו' עד איתמ\"ר בן אהר\"ן הכהן ופי' אהר\"ן הכהן ידוע שהוא בחי' אהבה רבה דכהנא רבא והוא הממשיך הכח הזה להיו' כל סדר העבודה הזאת וכמ\"ש במ\"א ע\"פ בהעלות\"ך את הנרות<sup data-n=\"9194\">154</sup> וכו' וד\"ל.",[["9184","144","<b>ואשים דברי בפיך</b>: ישעי' נא, טז. ראה גם מאמרי אדה\"ז תקס\"ב ח\"ב ע' שפו. לעיל פ' וארא עב, א."],["9185","145","<b>לדבר ה' זו הלכה</b>: עמוס ח, יב. שבת קלח, ב."],["9186","146","<b>אתאמר. . איתמר שבגמ'</b>: ירושלמי ב\"ב פ\"ג, ה\"א. . ברכות ט, א (איתמר). י, א (אתמר)."],["9187","147","<b>איתמר שממילא איתמר</b>: ראה גם לקמן תס, סע\"ב ואילך. תו\"ח נח נב, ג ובהערה 30 [ושם נדפס תו\"ח פקודי ע' רסט וצ\"ל: תרסט]."],["9188","148","<b>אז נדברו יראי ה'</b>: מלאכי ג, טז."],["9189","149","<b>אני המשנה המדברת בפיך</b>: ראה גם לעיל פ' תצוה שסב, ד. וש\"נ."],["9190","150","<b>שכינה מדברת מתוך גרונו</b>: ראה תניא פל\"ד. לעיל פ' בשלח קצד, ד הערה 540."],["9191","151","<b>ועשיתם את כל מצותי</b>: שלח טו, מ."],["9192","152","<b>אני ה' אלקיכם</b>: שלח שם, מא."],["9193","153","<b>כי נר מצוה</b>: משלי ו, כג."],["9194","154","<b>בהעלות\"ך את הנרות</b>: ראה גם לעיל פ' יתרו רסט, סע\"ב ואילך. וש\"נ.\n\n<b>לז</b>  <b>וד\"ל</b>: נמחק.\n<b>לח</b>  <b>וד\"ל</b>: נמחק.\n<b>לט</b>  _<b>וד\"ל</b>: נמחק."]]],[2300550069,"<b>להבין שרשי הדברים הנ\"ל </b>\nלהבין שרשי הדברים הנ\"ל<sup data-n=\"9195\">1</sup>. הנה מבואר בלק\"ת ששרש הל\"ת הוא בבחי' יחוד דאו\"א וזהו שמי עם י\"ה כו' ושרש מ\"ע הן בבחי' יחוד דזו\"נ<sup data-n=\"9196\">2</sup> וזהו ו\"ה עם זכרי<sup data-n=\"9197\">3</sup> כו'. וביאור הדברים הנה בחי' יחוד דאו\"א הענין הוא בחי' ביטול היש עד שאינו תופס מקום כלל וכלל וכענין שאמר משה ואנחנו מ\"ה<sup data-n=\"9198\">4</sup> מה ממש כו', והענין הוא משום דדוקא בדבר המושג בהשגה והתבוננו' אז שייך ההתפעלו' שבאה מפני שמשיג הדבר להיו' מורגשת בהרגשת דבר מה כמו התפעלות האהבה והדביקו' שמורגשת בנפש מאד מצד שהיא באה מפני ההשגה דוקא, וה\"ז ההתבוננו' עם ההתפעלות הכל בבחי' יש ודבר נראה ונרגש שהרי יש דבר מושג ויש מי שמשיג ויש מי שמתפעל כו'. אבל בדבר שאינו מושג בהשגה כלל וכלל כמו בחי' סתימו דכל סתימין<sup data-n=\"9199\">5</sup> דלית מחשבה תפיס' בי' כלל<sup data-n=\"9200\">6</sup>, אין ההתבוננו' בו בבחי' הרגשה כלל אחר שאינו משיג אין כאן דבר מושג שיהא נראה ונדמה כו', וגם ההתפעלו' מזה אינו בבחי' יש מורגש כלל כמו האהבה, אלא ההתפעלו' ממנו אינו רק בחי' הביטול והוא שמתבטל מן המציאו' וכמ\"ש ונחנו מ\"ה כו'. והטעם להתפעלו' כזאת דוקא הענין הוא משום דגם במה שמתבונן באור א\"ס שנק' סתימו דכל סתימין ועילת העלו'<sup data-n=\"9201\">7</sup> וכיוצא הרי אין בו השגה ממש רק שמשיג בו בחי' השלילה בלבד, וענין השלילה ידוע בלשון הפלסופי'<sup data-n=\"9202\">8</sup> ג\"כ דהיינו כאשר אין לאדם השגה גמורה בענין עומק איזה שכל לא ישיג ממנו רק השלילות והוא שיפשיט ממנו כל דבר המנגד ומסתיר לאותו הענין איך שהוא מושלל מהיפכו בלבד, ע\"ד דוגמא כשיפשיט ההגשמה מן הרוחניות לא יפשיט אלא היפך הרוחניו' והוא הגשם אבל מ\"מ לא ישיג בגופו ומהותו של הרוחני איך הוא ומה הוא, ומה שיודע ומשיג הפשטת הגשם ממנו אין זה ידיעה בעצמותו כלל רק בחי' השלילה מה שהוא מושלל מהיפכו בלבד כו'. ועד\"ז יובן גם בהשגו' אלקו' עד רום המעלות שיש ב' מיני השגו', הא' בגופו של דבר המושג, והב' כאשר לא ישיג בגופו כלל רק בחי' השלילה ממנו בלבד איך שהוא מושלל מהיפך כו' ואין לו השגה כלל וכלל בגופו כו'. והכלל הזה הוא ההפרש באורו' הנאצלי' בין בחי' יחוד או\"א דהיחוד שם בבחי' השלילה בלבד באור הכת\"ר שמקבלי' ממנו אחר דלית מחשבה תפיס' בי' כו', ובין יחוד זו\"נ שהן בחי' המדו' אוי\"ר וכיוצא שנמשכי' אחר השכל וההתבוננו' כו' <span data-k=\"pg\">1322</span> ּ דהיינו שיש להם השגה ממש ולא בדרך שלילה בלבד וד\"ל. וזהו הטעם שההתפעלו' שנמצאת מצד ההתבוננו' באור הכת\"ר שנק' אי\"ן<sup data-n=\"9203\">9</sup>",[["9195","1","<b>להבין שרשי הדברים הנ\"ל</b>: הנחת כ\"ק אדה\"א מדרוש אביו כ\"ק אדה\"ז משנת תקס\"ו. ראה לקו\"ת פקודי ו, א בשינויים. ביאורי הזהר מהצ\"צ ח\"ב ע' תתרו ואילך. ראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י."],["9196","2","<b>מבואר בלק\"ת. . הל\"ת. . דאו\"א. . מ\"ע. . דזו\"נ</b>: ספר טעמי המצות (להאריז\"ל) בהקדמה."],["9197","3","<b>שמי עם י\"ה. . ו\"ה עם זכרי</b>: נסמן לעיל תמב, ד הערה 19."],["9198","4","<b>ואנחנו מ\"ה</b>: בשלח טז, ז. ח [ושם: ונחנו וכ\"ה בסמוך בפנים — ראה מאמרי אדה\"א הנחות תקע\"ז ע' כו. וש\"נ]. ראה גם לעיל מג, א. וש\"נ."],["9199","5","<b>סתימו דכל סתימין</b>: ראה זהר בהקדמה ב, א. ועוד."],["9200","6","<b>דלית מחשבה תפיס' בי' כלל</b>: ראה ת\"ז בהקדמה (יז, א)."],["9201","7","<b>באור א\"ס. . ועילת העלו'</b>: ראה פרדס (שער אם הא\"ס הוא הכתר) ש\"ג, פ\"א."],["9202","8","<b>השלילה ידוע בלשון הפלסופי'</b>: ראה גם מו\"נ ח\"א, פנ\"ח. עקרים מאמר ב פכ\"ב. פכ\"ג. לקו\"ת כאן ו, ג. לעיל פ' בא צט, א. וש\"נ."],["9203","9","<b>הכת\"ר שנק' אי\"ן</b>: ראה זהר שלח קנח, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תנח. וש\"נ. הנחות תקע\"ז ע' ב. וש\"נ."]]],[2300550101,"ונק' עילת העלו'<sup data-n=\"9204\">10</sup> וכיוצא הוא בחי' הביטול במציאו' בלבד שאינו אלא ענין הפשטת המנגד והוא שלא יסתיר בהגשמה שלו כו', לפי שגם ההשגה בו אינו אלא ג\"כ בדרך השלילה בלבד וכנ\"ל וכל התפעלו' בהכרח שתדמה למקורה המולידה והוא ההתבוננו' כידוע, וזהו ענין התפעלו' משה כשאמר ונחנו מ\"ה כו' והוא למעלה בחי' יחוד דאו\"א כשמתייחדי' מאור הכת\"ר כידוע וד\"ל.\n<b>וזהו</b> ענין הנ\"ל דבמצות ל\"ת דוקא הוא בחי' יחוד דאו\"א הנ\"ל כי הנה כל הל\"ת הן באי' רק בבחי' השלילה והוא במניעת ההמשכה כמו לא תאכל חלב<sup data-n=\"9205\">11</sup> כו' וכיוצא, והוא מפני ששרשם מבחי' אור הכתר ששם יחוד דאו\"א דלית מחשב' תפיס' כו' אלא רק בדרך שלילה והיינו שיפשיטו ממנו המנגד והמסתיר בלבד לומר שדבר זה בודאי מושלל ומופשט ממנו אע\"פ שלא ידענו מהותו כנ\"ל, וכך הם ענין מל\"ת לא תאכל חלב כו' מפני שדבר זה בודאי מסתיר ומונע והוא לעומת בחי' הביטול דבחי' מ\"ה כו' כי זהו בודאי בחי' יש נפרד היפך האי\"ן כו', ויש כמה ל\"ת שפוגמין בחי' הביטו\"ל בלבד והוא מניעת ההשגה גם בדרך שלילה כמו דכולא קמי' כלא<sup data-n=\"9206\">12</sup> כו' מפני שהם בחי' יש נפרד ההפכי כו', ויש כמה מצות ל\"ת שמלבד שפוגמי' אור הביטול אלא שכורתים את הנפש שלא להיו' בה בחי' הביטול לעולם והוא ענין הכרת שנא' הכרת תכרת הנפש<sup data-n=\"9207\">13</sup> כו' כמו באוכל חמץ דמלבד שמונע אור הביטול אלא שנכרת נפשו מיום הראשון עד יום השביעי<sup data-n=\"9208\">14</sup> כו' מכל בחי' מ\"ה ששורה במצה בז' הימים הללו דפסח וכמ\"ש מצות יאכל את ז' הימים<sup data-n=\"9209\">15</sup> וכמשי\"ת בעזר\"ה וד\"ל.\n<b>וזהו</b> ענין הנ\"ל במצות ל\"ת דזהו מ\"ש בארץ ל\"א זרועה<sup data-n=\"9210\">16</sup> כו' דלאו קודם להן מלמעלה למטה כמאמר ברישא חשוכא והדר נהורא<sup data-n=\"9211\">17</sup> כו', לפי שבחי' אי\"ן דכת\"ר לא יוכל לבא בבחי' כלי להיות אורו מאד נעלה מן ההשתלשלו' באורו' וכלים כנ\"ל דלית מחשבה תפיס' בי' כו' אלא בלא\"ו בלבד הוא שיכול לבא, והיינו בדרך השלילה הנ\"ל והוא הצמצום והסתר שבהעלם קודם שיבא לידי גילוי אור וכמ\"ש ישת חושך סתרו<sup data-n=\"9212\">18</sup> כו', ולמטה לא ימצא לו בחי' כלי שישכון בו רק בהעדר ההיפוך במל\"ת כו' וד\"ל. משא\"כ רמ\"ח מ\"ע דיכול האור לבא לידי גילוי בכלים מכלים שונים זרעי' חסד<sup data-n=\"9213\">19</sup> דרועא ימינא<sup data-n=\"9214\">20</sup> כו' כנ\"ל ועד\"ז כל רמ\"ח מ\"ע שנק' רמ\"ח איברי'<sup data-n=\"9215\">21</sup> כו' והוא בחי' יחוד זו\"נ שהן ו\"ה עם זכר\"י",[["9204","10","<b>הכת\"ר. . ונק' עילת העלו'</b>: ראה פרדס בהערה 7."],["9205","11","<b>לא תאכל חלב</b>: ראה ויקרא ג, יז."],["9206","12","<b>דכולא קמי' כלא</b>: נסמן לעיל בפ' משפטים רעז, ב."],["9207","13","<b>הכרת תכרת הנפש</b>: שלח טו, לא."],["9208","14","<b>באוכל חמץ. . שנכרת נפשו מיום הראשון עד יום השביעי</b>: בא יב, טו. ראה גם תו\"ח לך פח, ד ובהערה 19. שה\"א יח, א. מאמר ד\"ה דור לדור מכ\"ק אדה\"א (קה\"ת תשנ\"ב) ע' 26."],["9209","15","<b>מצות יאכל את ז' הימים</b>: בא יג, ז."],["9210","16","<b>בארץ ל\"א זרועה</b>: ירמי' ב, ב. ראה לעיל תמג, ג."],["9211","17","<b>ברישא חשוכא והדר נהורא</b>: שבת עז, ב (כגי' רש\"י)."],["9212","18","<b>ישת חושך סתרו</b>: תהלים יח, יב."],["9213","19","<b>זרעי' חסד</b>: נסמן לעיל בפ' ויקהל תלט, ד הערה 1913."],["9214","20","<b>חסד דרועא ימינא</b>: ת\"ז בהקדמה (יז, א)."],["9215","21","<b>רמ\"ח מ\"ע שנק' רמ\"ח איברי'</b>: ראה ת\"ז ת\"ל (עד, סע\"א). שע\"ת עב, ג הערה 17."]]],[2300550133,"שעולה רמ\"ח כו', לפי ששרש המ\"ע הן מבחי' גילוי האור שבא מן ההעלם והוא ההן שאחר הלאו כו' ולא בדרך שלילה בלבד אלא הוא מושג דוקא, ולכך בא ג\"כ במדו' בחו\"ג דוקא מגולי' ונראי' ומלובשי' ג\"כ בכלים מכלים שונים וכמו ענין הנ\"ל באהבה המורגשת מצד ההשגה בדבר המושג כו' וד\"ל.\n<b>ובכל</b> זה מובן ענין הנ\"ל דכד אתכפיא סט\"א<sup data-n=\"9216\">22</sup> אסתלק יקרא דקדב\"ה כו' פי' קדב\"ה הוא בחי' ז\"א<sup data-n=\"9217\">23</sup> והן המדו' דאצי' כידוע ופי' אסתלק היינו שעלה ברום המעלו' והוא בבחי' יחוד דאו\"א ששם <span data-k=\"pg\">תרסא</span> ּ לא יוכל האור לבא בגילוי בכלי רק בדרך שלילה כנ\"ל, וכל זה רק ע\"י דאתכפיא סט\"א כו' דהיינו כשיבוררו הברורי' דרפ\"ח ניצוצי' שנפלו בנוג\"ה בעה\"ד כו' מפני שמחמתם מוסתר האור האלקי בכל מל\"ת כמו לא תאכל חלב כו' וכיוצא לפי שהחלב והדם סט\"א נדבק בה ונעשה חושך גמור להסתיר ממש וכשיסירו זה המסתיר והמנגד אזי יתגלה בחי' יחוד דאו\"א גם במדרגו' התחתונו' שנמשכו מזו\"נ בבי\"ע כו' וד\"ל. וזהו דאסתלק יקרא דקדב\"ה כו' פי' יקרא הוא בחי' הכת\"ר דז\"א שנמשך מת\"ת דאימא<sup data-n=\"9218\">24</sup> ונסתלק ועלה להיו' בבחי' כת\"ר הכללי הכולל כל הכתרים והוא כת\"ר דא\"א כמשי\"ת וד\"ל. וזהו נתאוה הקדב\"ה להיות לו דירה בתחתונים<sup data-n=\"9219\">25</sup> פי' תחתוני\"ם הן בחי' זו\"נ שהם שרשי העולמו' הנפרדי' יש מאין כו' וכאשר אתכפיא סט\"א יוכל אור הכת\"ר הכללי להאיר למטה כמו בבחי' יחוד דאו\"א הנ\"ל הנק' עליונים בדרך כלל, והיינו בבחי' הביטול דמ\"ה שיהי' למטה בעולמו' התחתונים כמו בעליונים מטעם הנ\"ל ואין זה אלא דוקא בבחי' ביטול הי\"ש לגמרי וכמו לע\"ל דכתיב ואת רוח הטומא' אעביר<sup data-n=\"9220\">26</sup> כו' ובלע המות לנצח<sup data-n=\"9221\">27</sup> כו' וד\"ל.\n<b>והנה</b> ביחוד זו\"נ יש ג\"כ ב' מדרגו', הא' והוא ז\"א יש בו בחי' יחוד דאו\"א קצת והוא מעלת התורה על המצות דהנה במצו' שנק' רמ\"ח איברי' דמלכא המה רק כלים מכלים שונים לגילוי אורו' דאצי' כמו האתרוג לבחי' ספי' מל'<sup data-n=\"9222\">28</sup> והלולב כו', אבל בתורה יש מעלה יתירה והוא מבחי' מוחי' דאו\"א ממש, שהרי הקדב\"ה יושב ושונה כנגדו<sup data-n=\"9223\">29</sup> ופי' הקדב\"ה הוא בחי' ז\"א",[["9216","22","<b>דכד אתכפיא סט\"א</b>: נסמן לעיל תמב, ד."],["9217","23","<b>קדב\"ה. . ז\"א</b>: ראה סידור שער התפילין ז, ג. תו\"ח נח סט, א הערה 1."],["9218","24","<b>הכת\"ר דז\"א שנמשך מת\"ת דאימא</b>: ראה ע\"ח (שער מוחין דצלם) שכ\"ג, רפ\"ה ורפ\"ז. מאמרי אדה\"א דברים ח\"ג ע' תתעג. וש\"נ."],["9219","25","<b>נתאוה. . דירה בתחתונים</b>: ראה תניא רפל\"ו. לעיל פ' וארא ע, ג הערה 67."],["9220","26","<b>ואת רוח הטומא' אעביר</b>: זכרי' יג, ב."],["9221","27","<b>ובלע המות לנצח</b>: ישעי' כה, ח."],["9222","28","<b>האתרוג. . מל'</b>: ראה פרדס (שער עה\"כ) שכ\"ג מערכת אתרוג. תו\"ח לך פג, ג הערה 44."],["9223","29","<b>הקדב\"ה יושב ושונה כנגדו</b>: ראה תדא\"ר רפי\"ח. לעיל פ' וארא נח, ג הערה 18."]]],[2300550165,"וכשיושב ושונה הרי חכמת אד\"ם זה כמ\"ש על הכסא דמו'<sup data-n=\"9224\">31</sup> כמרא\"ה אד\"ם בגי' מ\"ה<sup data-n=\"9225\">32</sup> כו' תאיר פניו<sup data-n=\"9226\">30</sup> ובחי' הארת הפני\"ם שלו הוא מבחי' יחוד דאו\"א, דלכך נק' אד\"ם לפי שיש בו מבחי' המוחי' דאו\"א בג' חללי גלגלתא<sup data-n=\"9227\">33</sup> כו'. וזהו ענין בחי' הגוונין שבמשכן זהב ותכלת וארגמן כו' אלא שהן רק המשכו' מאור פנים דאו\"א כי אוריי' שהוא ז\"א<sup data-n=\"9228\">34</sup> מחכמ' דאור אבא נפק'<sup data-n=\"9229\">35</sup> כו' וד\"ל.\n<b>וזהו</b> אלה פקוד\"י המשכן<sup data-n=\"9230\">36</sup> משכן העדות אשר פוק\"ד עפ\"י מש\"ה כו' ותחלה יש לבאר ענין הדפ\"ק, דהנה האיברי' המה נגדלי' מן החלק הלחלוחי' שיש בדם והוא חלק המי\"ם והן מבחי' החסדי'<sup data-n=\"9231\">37</sup> כמו האילן שגדל ע\"פ המים כו' ויש לכל אבר ואבר מזג חיו' בפ\"ע כפי תכונתו, והעיקר הוא ע\"י הגידים שבהם הולך וסובב כל הדם הוא הנפש מאבר לאבר, והדם עצמו הוא מבחי' הגבורו\"ת<sup data-n=\"9232\">38</sup> כי יש בו חמימות כידוע והוא עיקר המשפיע חיו' לכל האיברי' כולם וכמ\"ש כי הדם הוא הנפש<sup data-n=\"9233\">39</sup> כלומר שבו שוכן ומלובש כח החיו' הנפשיו' והוא מבחי' ס\"ג דאימא<sup data-n=\"9234\">40</sup> כו' בגי' קס\"א<sup data-n=\"9235\">41</sup>. והדפ\"ק אשר בלב והוא הנק' דפיקו דלבא הוא בא מאור אבא ונמשך עד בחי' החזה ושם דופק כמ\"ש קול דודי דופ\"ק<sup data-n=\"9236\">42</sup>, והוא בגי' קפ\"ד<sup data-n=\"9237\">43</sup> להיותו רק אחוריי' דאור אבא<sup data-n=\"9238\">44</sup>, כי בחי' אחוריי' דחכמה ובחי' פנימי' אימא מתלבשי' יחד באד\"ם ליתן שפע וחיו' בכל האיברי' ובלב הוא ראשית הגילוי של ההתלבשו' דאור אבא בבחי' האחוריי' והוא הדפ\"ק והד\"ם <span data-k=\"pg\">1324</span> ּ הוא הנפ\"ש מבחי' אור אימא מתגלה בלב, ומן הלב נמשך לכל האיברי' כידוע דלב מלך על כל האיברי'<sup data-n=\"9239\">45</sup> ופליג לכל שייפין<sup data-n=\"9240\">46</sup> כו' וכמ\"ש במ\"א וד\"ל. ולהיו' כי בבחי' אור אבא יש בו בחי' הביטול דמ\"ה דוקא כנ\"ל ע\"כ גם בבחי' האחוריי\"ם שלו דהיינו בדפיקו' דלבא, וגם בדפ\"ק היד יש שם בחי' הביטול שהרי אור החיו' עולה ומסתלק וחוזר ויורד והוא הדפיקו והנשימה של רוח החיים שבלב וכמ\"כ בדפ\"ק היד כידוע. אמנם בחי' הד\"ם עצמו הוא בבחי' י\"ש לילך ולסבוב בכל חלקי האיברי' להחיותם כו' והוא מבחי' בינ\"ה<sup data-n=\"9241\">47</sup> שנק' יש<sup data-n=\"9242\">48</sup> כידוע, ול\"א חלק עשירי' ממספר י\"ש והיינו ל\"א דאחוריי' דאבא ועם בחי' הפנימי' דאימא ועם המילויי' של השמו' עולה במספר מש\"ה שהוא קפ\"ד וקס\"א<sup data-n=\"9243\">49</sup>",[["9224","31","<b>על הכסא דמו'</b>: נסמן לעיל תמג, א."],["9225","32","<b>אד\"ם בגי' מ\"ה</b>: נסמן לעיל בפ' משפטים רפא, ד."],["9226","30","<b>חכמת אד\"ם. . תאיר פניו</b>: קהלת ח, א."],["9227","33","<b>בג' חללי גלגלתא</b>: נסמן לעיל בפ' תצוה שעז, ב."],["9228","34","<b>אוריי' שהוא ז\"א</b>: נסמן לעיל פ' תצוה שסב, ד."],["9229","35","<b>אוריי'. . מחכמ'. . נפק'</b>: נסמן לעיל בפ' יתרו רסח, ד."],["9230","36","<b>אלה פקוד\"י המשכן</b>: פקודי לח, כא."],["9231","37","<b>המי\"ם. . החסדי'</b>: נסמן לעיל בפ' משפטים רעט, א."],["9232","38","<b>והדם. . הגבורו\"ת</b>: ראה מאורי אור מערכת דם סט\"ז. תו\"א נח ט, ג. לקו\"ת שה\"ש טז, ב פ\"ג (ע\"פ אוה\"ת תזריע ע' תקלד). מאמרי אדה\"א דברים ח\"ד ע' א'תלט."],["9233","39","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג."],["9234","40","<b>הדם. . ס\"ג דאימא</b>: דם — בינה [נסמן בסמוך הערה 47] ושם ס\"ג הוא ב[אימא] בינה [נסמן לעיל בפ' וארא פד, ד הערה 810]."],["9235","41","<b>הדם. . בגי' קס\"א</b>: אהי' בריבוע בגימטריא דם [ראה פע\"ח (שער חה\"מ) שכ\"א, פ\"א. מאמרי אדה\"א קונטרסים ע' תקמ. וש\"נ]. ואהי' במילוי יודין בגימטריא קס\"א — ראה רמ\"ז לזהר קדושים פו, א."],["9236","42","<b>קול דודי דופ\"ק</b>: שה\"ש ה, ב. ראה גם לעיל פ' בא קד, ג הערה 374."],["9237","43","<b>דופ\"ק והוא בגי' קפ\"ד</b>: נסמן בסמוך בהערה 50."],["9238","44","<b>דופ\"ק. . קפ\"ד. . אחוריי' דאור אבא</b>: ראה טעמי המצות להאריז\"ל פ' וירא."],["9239","45","<b>דלב מלך. . האיברי'</b>: ראה אבן עזרא שמות ח, יח. רד\"ק תהלים קיט, עג. בחיי ר\"פ שלח. ספר יצירה פ\"ו. מ\"ב."],["9240","46","<b>דלב. . ופליג לכל שייפין</b>: נסמן לעיל בפ' תרומה שיד, א הערה 166."],["9241","47","<b>הד\"ם. . מבחי' בינ\"ה</b>: ראה פרדס (שעה\"כ) שכ\"ג מערכת דם."],["9242","48","<b>בינה שנק' יש</b>: ראה גם לעיל פ' תצוה שנט, ג ובהערה 45."],["9243","49","<b>מש\"ה שהוא קפ\"ד וקס\"א</b>: ראה מאורי אור מערכת משה סנ\"ה. אוה\"ת ויקרא כרך ד ע' תתקעח בהערה."]]],[2300550197,"יחד כו', וזהו אשר פוק\"ד עפ\"י מש\"ה בחי' מ\"ה דאבא. ואע\"פ שזה נאמר בבחי' יחו\"ד עליון דאו\"א שנק' משכן העדות כמשי\"ת זהו בבחי' הפנימית כפי הכתוב פק\"ד אבל בהיפוך אתוון שהוא דפ\"ק בגי' קפ\"ד<sup data-n=\"9244\">50</sup> הוא בבחי' האחוריי', דהיינו כשאו\"א מתלבשי' בז\"א שאינו אלא מבחי' החיצוניו' כו' וד\"ל. ואמנם הרי בזה מעלת השס\"ה ל\"ת על רמ\"ח מ\"ע דהנה השס\"ה ל\"ת שרשן בשס\"ה גידי' דאור אימא כנ\"ל ורמ\"ח מ\"ע הן רמ\"ח האיברי' שמקבלי' מבחי' החסדי' שבהם ומעלת הגבורו' שבדם הוא גבוה הרבה מן החסדי' כי המה עיקר המחי' כו' וד\"ל, ולפ\"ז קאי אשר פוק\"ד עפ\"י מש\"ה על ב' המדרגו' דמשכן בין בפנימי' המשכן בין בחיצוניו' וד\"ל.\n<b>וזהו</b> אלה פקוד\"י המשכן משכן העדות כו' ב' מדרגו' הן הא' משכן תחתון שהוא בבחי' יחוד זו\"נ והב' משכן העליון בבחי' או\"א ונק' משכן העדו\"ת ושניהם פק\"ד עפ\"י מש\"ה כנ\"ל. ותחלה יש לבאר בחי' משכן התחתון והוא מה שאמר אל\"ה פקודי לשון אל\"ה הוא לשון רבים דוקא וכמ\"ש שאו מרו\"ם עיניכם<sup data-n=\"9245\">51</sup> וראו מ\"י ברא אל\"ה כו', פי' אל\"ה הוא בגי' ל\"ו<sup data-n=\"9246\">52</sup> שהוא לפי שהמדות הן ששה<sup data-n=\"9247\">53</sup> כידוע וכמ\"ש לך ה' הגדולה והגבורה והת\"ת והנצח וההוד<sup data-n=\"9248\">54</sup> וכאו\"א כלול מששה כידוע הרי ל\"ו ולכך נק' אל\"ה. וגם הוא אותיו' לא\"ה<sup data-n=\"9249\">55</sup> כי לא\"ה ילדה ששה בנים<sup data-n=\"9250\">56</sup> שהן בחי' ו\"ק דז\"א כידוע, ואין גילוי פרטיו' דאל\"ה זה אלא כאשר כבר נולדו ויצאו המדות בבחי' ההתגלו' מאור אימא שנק' א\"ם הבני\"ם כו'. וזהו מ\"י ברא אלה פי' מ\"י הוא אור אימא, ומ\"י ברא את אל\"ה שהן ששה מדו' שנק' בני לא\"ה כו', וזהו אותיו' שם אלקי\"ם דאימא מ\"י אל\"ה<sup data-n=\"9251\">57</sup> ביחד וכשיצאו ונולדו בהתגלו' אז נא' פלג אלקים<sup data-n=\"9252\">58</sup> שנפלגו ויצאו לחלק אל\"ה ממ\"י אם הבנים כו' וכמ\"ש במ\"א וד\"ל. והנה יחוד ז\"א בנוק' שנק' משכן שהיא בחי' מל' דאצי' שנק' שכינה וכמ\"ש ושכנתי בתוכם<sup data-n=\"9253\">59</sup> כו' וכנ\"ל היינו מה שבחי' ז\"א ממשיך למל' דאצי' ומל' דאצי' בבי\"ע כו' כידוע, וזהו אל\"ה פקודי המשכ\"ן כענין חייב אד\"ם לפקוד אשת\"ו<sup data-n=\"9254\">60</sup> כו' שהוא בחי' יחוד דזו\"נ שנק' אד\"ם ואשתו וכמ\"ש על הכסא דמו' כמראה אד\"ם וכס\"א הוא שם ב\"ן<sup data-n=\"9255\">61</sup> והאד\"ם הוא בחי' שם מ\"ה כידוע <span data-k=\"pg\">תרסב</span> ּ והיינו יחו\"ד ופקידה דמ\"ה וב\"ן ונק' אל\"ה לשון רבים כי היחוד הוא ברמ\"ח איברי' כו' והן יחוד דזו\"נ בו\"ה עם זכר\"י שעולה רמ\"ח כו' וד\"ל.",[["9244","50","<b>דפ\"ק בגי' קפ\"ד</b>: ראה טעמי המצות שם. לעיל פ' בא קד, ג הערה 372."],["9245","51","<b>שאו מרו\"ם עיניכם</b>: ישעי' מ, כו."],["9246","52","<b>אלה הוא בגי' ל\"ו</b>: ראה לקמן תמח, ג. הנסמן לעיל פ' משפטים רצא, ב. וש\"נ."],["9247","53","<b>שהמדות הן ששה</b>: ראה אגה\"ת פ\"ד. לקו\"ת כאן ז, א. תו\"ח נח נז, ד ובהערה 68. בהערה שלפנ\"ז."],["9248","54","<b>לך ה' הגדולה. . וההוד</b>: דהי\"א כט, יא. ומונה כאן רק ה'. ראה לעיל תמג, ד."],["9249","55","<b>אל\"ה. . אותיו' לא\"ה</b>: ראה לעיל תמד, א הערה 83."],["9250","56","<b>לא\"ה ילדה ששה בנים</b>: ויצא ל, כ. ראה גם לעיל פ' שמות יח, א. וש\"נ."],["9251","57","<b>אלקי\"ם. . מ\"י אל\"ה</b>: ראה זהר בהקדמה ב, א."],["9252","58","<b>פלג אלקים</b>: תהלים סה, י. ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקפט ואילך. לקו\"ת במדבר ו, ד."],["9253","59","<b>ושכנתי בתוכם</b>: תרומה כה, ח."],["9254","60","<b>חייב אד\"ם לפקוד אשת\"ו</b>: נסמן לעיל תמד, א."],["9255","61","<b>וכס\"א הוא שם ב\"ן</b>: ראה פע\"ח (שער חה\"ס) שכ\"ח, פ\"א. ס' ערכי הכנוים לבעל סדר הדורות מערכת כסא סתם כסא מלכות."]]],[2300550229,"<b>ואמנם</b> משכן העליון הפנימי הוא הנק' משכן העדות והוא בחי' הפנימי' למשכן דזו\"נ והיינו בבחי' יחוד דאו\"א הנ\"ל שע\"י מצות ל\"ת כמ\"ש זה שמ\"י ושמי עם י\"ה שס\"ה כו', והטעם שנק' עדו\"ת וכמ\"ש עדו\"ת לישראל כו' לפי ששם עלו שבטי' שבטי י\"ה<sup data-n=\"9256\">62</sup> כו'. הנה בתחלה יש להבין שרש ענין ותרבי ותגדלי בעדי עדיי\"ם<sup data-n=\"9257\">63</sup> שהוא לשון קישוט<sup data-n=\"9258\">64</sup> כנ\"ל כו', דהנה ידוע בע\"ח דבחי' נצח והוד דא\"א מלובשי' באו\"א ומהם נעשה תרין עטרין עילאי' שהן אחסנתא דירית או\"א<sup data-n=\"9259\">65</sup> כו' והן הנק' עדיי\"ם ב' כתרים לאו\"א כו', ופי' עד\"י עדיי\"ם הוא מקור כל הכתרים וכל העדיים, והוא בחי' הכתר הכללי בחי' רעוא דכל רעוין<sup data-n=\"9260\">66</sup> שהוא בחי' גלגלתא דא\"א<sup data-n=\"9261\">67</sup> כו' עד בחי' ת\"ת דאימא שנעשה כת\"ר לז\"א שהוא כתר האחרון היותר פרטי כו', וזהו שנק' עדו\"ת לישראל שהוא כת\"ר דז\"א כו', ושרש כל העדיו\"ת הללו הוא בחי' רעוא דכל רעוין כו' שנק' עד\"י עדיי\"ם כו'.\n<b>ולהבין</b> ביאור כל זה הנה בתחלה יש להבין תחלת הפסוק רבבה כצמח השדה<sup data-n=\"9262\">68</sup> כו' ותרבי ותגדלי כו' ואח\"כ ותבואי בעד\"י עדיים כו' הנה צמח השדה ידוע שלא יצמח אלא אחר רקבון הגרעין<sup data-n=\"9263\">69</sup> בארץ בתחלה כו', והטעם הוא כדי שיופשט מגשם שבו ויוכלל ברוחניו' כח המצמיח שהוא בחי' אי\"ן וע\"י ביטול זה מיש לאי\"ן יצמיח בו כח המצמיח כו' עד שיהי' צמח גדול כו'. וכך הנמשל למעלה דידוע שא\"א להיו' בחי' החזרת פב\"פ בפרצוף שלם אם לא שנסתר פרצוף הראשון להיות בתחלה<sup data-n=\"9264\">70</sup> רק כנקודה א' תחת היסוד<sup data-n=\"9265\">71</sup> כו', כי מתחלה הם בבחי' אב\"א וכדי שיוחזרו מבחי' אב\"א להיו' בבחי' פב\"פ צריך להיו' באמצע בחי' ביטול ממציאו' הראשון ולהעשו' רק נקודה א' תחת היסוד כו'. ודוגמא זו היא ברקבון הגרעין שנכלל כולו בבחי' ביטול ואח\"כ חוזר ומצמיח כו', וכן בטפה זרעית שנסרחת בתחלה<sup data-n=\"9266\">72</sup> כו'' וכיוצא בזה מן הדיבור לגבי המדו' ומן המדו' לגבי השכל כו', ועד\"ז יובן בכל פרטי הפרצופי' העליונים בבחי' היחוד שלהם מן המשפיע עם המקבל כו' וד\"ל. וזהו מפני שי\"ש מי\"ש א\"א להיו' שום התהוות חדש כ\"א מביטול היש לאין אזי אור המשפיע שופע בו מאין ליש כו' וכמ\"ש בלק\"א להה\"מ ז\"ל<sup data-n=\"9267\">73</sup>. וזהו רבבה כצמח השדה ביצ\"מ מפני שע\"י שנעשי' בחי' נקוד' תחלה דוקא כענין ה\"א לחמא עני\"א די אכלא<sup data-n=\"9268\">74</sup> כו' אזי חוזרת להיו' בבחי' פב\"פ כמו בשעת מ\"ת וזהו ותרבי ותגדלי כו' בבחי'",[["9256","62","<b>עדו\"ת לישראל. . ששם עלו שבטי' שבטי י\"ה</b>: תהלים קכב, ד."],["9257","63","<b>ותרבי ותגדלי בעדי עדיי\"ם</b>: יחזקאל טז, ז [בדילוג]."],["9258","64","<b>בעדי. . קישוט</b>: ראה לעיל תמד, ב."],["9259","65","<b>בע\"ח דבחי' נצח והוד. . דירית או\"א</b>: השוה לקו\"ת פקודי כאן (ז, א). ראה זהר (אד\"ז) האזינו רצא, א. רצב, ב. ע\"ח (שער הנסירה) שכ\"ט, פ\"ו."],["9260","66","<b>רעוא דכל רעוין</b>: נסמן לעיל בפ' תצוה שנח, ב."],["9261","67","<b>רעוא דכל רעוין. . גלגלתא דא\"א</b>: ראה ע\"ח שער הכללים פ\"ב. (שער א\"א) שי\"ג, פ\"ו."],["9262","68","<b>רבבה כצמח השדה</b>: יחזקאל טז, ז."],["9263","69","<b>רקבון הגרעין</b>: נסמן לעיל תמד, ב."],["9264","70","<b>שא\"א. . החזרת פב\"פ. . שנסתר. . בתחלה</b>: ראה ע\"ח (שער תיקון הנוק') של\"ד, פ\"ב. פ\"ג."],["9265","71","<b>כנקודה א' תחת היסוד</b>: ראה זהר בלק קצא, א ובהגהת הרח\"ו שם. לעיל בפ' וארא עא, ד הערה 30."],["9266","72","<b>בטפה זרעית שנסרחת בתחלה</b>: ראה גם לעיל פ' תצוה שכ, ג. וש\"נ."],["9267","73","<b>שי\"ש מי\"ש א\"א להיו'. . וכמ\"ש בלק\"א להה\"מ ז\"ל</b>: ראה שם סמ\"ח."],["9268","74","<b>ה\"א לחמא עני\"א די אכלא</b>: ראה נוסח ההגדה. פע\"ח (שער חהמ\"צ) שכ\"א, פ\"ז בפיסקא זו."]]],[2300550260,"מוחי' דגדל\"ו' כו', ואח\"כ ותבואי בעד\"י עדיי\"ם כו', דהנה קבלת התורה והמצו' הוא בבחי' יחוד דזו\"נ בלבד כנ\"ל והיינו ותרבי ותגדלי כו' אבל עדי עדיים היינו בחי' הכתרי\"ם הנק' עטרין עילאי' כנ\"ל. והנה יש בהן מדרגו' הרבה הא' בחי' ת\"ת דאימא שנעשה כת\"ר לז\"א שנק' עדו' לישרא\"ל בלבד כנ\"ל, הענין הוא מה שקיבלו ישראל עדי וקישוט הכתרי\"ם בשעת קבלת התורה וכמ\"ש ויתנצלו בנ\"י את עדיי\"ם<sup data-n=\"9269\">75</sup> מהר חורב כו' והוא הנק' כת\"ר תור\"ה כו'.\n<b>וביאור</b> ענין הכתר בכלל הנה בפי' עד\"י יש ג' ענינים, א' כפשוטו לשון קישוט. והב' לשון נצחיות כמו עד\"י ע\"ד<sup data-n=\"9270\">76</sup> ע\"ד עולם<sup data-n=\"9271\">77</sup> וכיוצא. והג' לשון עד ולא עד בכלל<sup data-n=\"9272\">78</sup> או עד כאן שפי' <span data-k=\"pg\">1326</span> ּ עד זה ענין הפסק<sup data-n=\"9273\">79</sup> הוא לומר עד כאן ויותר לא תגיע כו'. והנה כל הג' פרושי' ענין א' הם, והוא אשר בחי' הכת\"ר בכל מקום שהוא הוא בחי' ההעלם של התחתון ואין המקבלי' יכולי' לקבל ממנו בבחי' גילוי אור כלל אלא נשאר עליהם בבחי' מקיף וסובב ולכך נק' כת\"ר וכמו העטרה המקפת על הראש היא כותרת ומקפת הראש כו' כידוע. והנה בענין זה יש כל הג' פרושי' הנ\"ל, א' מה שהכת\"ר הוא בחי' עד\"י וקישו\"ט הענין הוא לפי שהקישוט והעדי נותן חן לפני האדם בבחי' מקיף בלבד כעטרת זהב מאבנים טובו' ומרגליו' שעל הראש שמאירי' את הפנים בבחי' ההעלם שיש בהם, כי אין בהם היופי וההידור הזה שנותנים בפנים בעצמם ומהותם כשתלויים בכותל אלא כשנתונים על הראש מאירי' הפנים הרי היופי הזה נמשך מבחי' ההעלם כו'. ועוד שגם בעצמם ומהותם אין היוקר הגדול שבהם בגילוי אור שהרי הם רק אבן דומם כשאר אבנים אלא מפני שהם מאירי'<sup data-n=\"9274\">80</sup>, ולא מצד האור עצמו שהרי אור הנר אינו חשוב כלום כו' וכמ\"ש במ\"א. ועוד שהם נתונים בבחי' כת\"ר דהיינו בעטרה על הראש דוקא כו'. והב' ענין נצחיו' כמו עד\"י ע\"ד כו', גם זה הוא בענין ובחי' הכת\"ר דהנה הכת\"ר הוא בחי' ממוצע<sup data-n=\"9275\">81</sup> בין עצמו' אור א\"ס לנאצלי' ויש בו מבחי' התחתונה שבא\"ס והוא בחי' הנצחיות בבלתי הגבלה בכלי כו' משא\"כ שאר האורו' כו', וזהו פי' עדי עד כמו עד עולם וכיוצא. והג' ענין הפסק כמו עד כאן כו' לפי שלעולם אין תפיס' והשגה באור הכת\"ר, והוא לפי שיש בו מבחי' הארת אור א\"ס דלית מחשבה תפיס' ביה כו' וע\"כ בכל השגה שישיגו בו לא יגיעו לאמיתתו אלא ישאר עליהם בבחי' מקיף וסובב כנ\"ל והיינו כענין עד ולא עד בכלל כלומר עד כאן ותו לא שלא תשיג יותר, וכענין מה פשפשת<sup data-n=\"9276\">82</sup>",[["9269","75","<b>ויתנצלו בנ\"י את עדיי\"ם</b>: תשא לג, ו."],["9270","76","<b>עד\"י. . נצחיות כמו עד\"י ע\"ד</b>: נסמן לעיל תמד, ג."],["9271","77","<b>ע\"ד עולם</b>: בא יב, כד. בשלח יד, יג."],["9272","78","<b>עד ולא עד בכלל</b>: ברכות כו, ב."],["9273","79","<b>עד\"י. . הפסק</b>: נסמן לעיל תמד, ג."],["9274","80","<b>אבנים. . שהם מאירי'</b>: ראה גם מאמרי אדה\"ז תקס\"ז ע' ריד. תו\"א בראשית ח, ב. לקו\"ת נשא כג, ג. ראה כה, ד."],["9275","81","<b>הכת\"ר. . ממוצע</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"א. לעיל פ' שמות יא, ג. וש\"נ."],["9276","82","<b>מה פשפשת</b>: זהר בהקדמה א, ב."]]],[2300550290,"כו' מפני שאין ביכולת המקבלי' להגיע לסוף אורו וגם אם יגיעו עוד להשגו' נפלאו' מן הראשונו' עדיין לא יגיעו לאמיתתו כו', ועד\"ז יוכל להיו' הרבה פעמי' שיוכל לומר בהן עד ולא עד כו' כפי ערך בחי' הכת\"ר ההו\"א כו'. ונמצא שג' הפרושי' ענין א' הם כי בפי' בחי' הכת\"ר כולם אמת וד\"ל, אך בחי' הכת\"ר אינו שוה בכל מקום. והנה עכ\"ז שרש כל הכתרי\"ם ענין א' הם<sup data-n=\"9277\">83</sup> אחר שנק' העל\"ם ובבחי' ההעלם לא שייך השתלשלו' וכמ\"ש במ\"א, ולכך כתר התחתון מתאחד עם כת\"ר היותר העליון והיו לאחדי' ממש והיינו כת\"ר דז\"א שעולה עד בחי' הכת\"ר הכללי כו'.\n<b>וזהו</b> ותבואי בעדי עדיים פי' בשעת קבלת התורה שנק' כת\"ר תור\"ה היינו בחי' כת\"ר דז\"א וענין בחי' כת\"ר דז\"א הוא בחי' רעותא דלבא שנולד מן הארו' השכל שהן חו\"ב תרין ריעין<sup data-n=\"9278\">84</sup> כו', אבל כתר כהונה הוא בחי' כת\"ר דאו\"א שנק' עטרין עילאי' מהתלבשו' נה\"י דא\"א כנ\"ל. והענין הוא כי הנה בחי' המשכו' הרצון והתענוג שמתלבש בחו\"ב וכמ\"ש והחכמ\"ה מאי\"ן תמצא<sup data-n=\"9279\">85</sup> וכידוע הרי הן ב' מזלו' דא\"א מזל הח' ומזל הי\"ג שמהן נעשה שרשי המוחי' לאו\"א<sup data-n=\"9280\">86</sup> כו', אך בחי' הכתר\"י' שלהם הן מבחי' פרקין העליונים <span data-k=\"pg\">תרסג</span> ּ שבנצח והוד דא\"א שמתוכם נעשה עטרין לאו\"א בבחי' מקיף וסובב כעטרה ועד\"י הראש כנ\"ל. ויש בו כל הג' פרושי' הנ\"ל באופן יותר עמוק לפי ערך מעלת אורו' דאו\"א על אורו\"ת דזו\"נ כו' ועד\"י עדיי\"ם היינו בחי' כת\"ר הכללי דא\"א מבחי' רעוא דכל רעוין הנק' כת\"ר של הכתרי\"ם כו' (וג' כתרים הן<sup data-n=\"9281\">87</sup> מתפשטי' בג' קוין והן כתר תורה קו האמצעי וכתר כהונ' קו הימין וכתר מל' בשמאל וכתר שם טוב עולה ע\"ג וכמ\"ש טוב שם גם משמן הטוב<sup data-n=\"9282\">88</sup> כו') והן<sup data-n=\"9283\">89</sup> ג' פעמי' היכל ה' המה<sup data-n=\"9284\">90</sup> דלע\"ל יבאו הכתרי\"ם בבחי' גילוי בכלי דוקא משא\"כ עכשיו או' ג\"פ קדו\"ש<sup data-n=\"9285\">91</sup> כו', והגילוי הוא רק בבחי' ביטול כענין כריעו' והשתחוואו' דר\"ע<sup data-n=\"9286\">92</sup> וכיוצא שהוא הלא\"ו שקודם להן, ומה שעכשיו אינו מתגלה רק בלא\"ו דל\"ת והיינו בהעד\"ר הכלי כמו ההשתחווא', לע\"ל יתגלה בכלי ונק' היכל ה' ממש והיינו שיאמרו לפני הצדיקי' קדו\"ש<sup data-n=\"9287\">93</sup> כו' וד\"ל). וזהו אלה פקודי המשכן בבחי' יחוד זו\"נ ואח\"כ משכן העדו\"ת בבחי' הכתרי' דאו\"א וזו\"נ עד כתר הכללי הנק' עד\"י עדיי\"ם כנ\"ל וד\"ל.\n<b>אשר</b> פוקד עפ\"י משה כו'. הנה בהקמת המשכן נא' ונשאו הלוי\"ם<sup data-n=\"9288\">94</sup> כו' והקימו את המשכן<sup data-n=\"9289\">95</sup> כו' ובהתחלת הקמת המשכן הוקם ע\"י מש\"ה<sup data-n=\"9290\">96</sup> כו'. דהנה מבואר בפע\"ח דבחי' יחוד",[["9277","83","<b>שרש כל הכתרי\"ם ענין א' הם</b>: ראה גם מאמרי אדה\"ז אתהלך לאזניא ע' נד. שעה\"י קטו, א ובהערה 1. וראה גם אוה\"ת וישלח ע' רלט."],["9278","84","<b>חו\"ב תרין ריעין</b>: נסמן לעיל בפ' תצוה שמז, ב."],["9279","85","<b>והחכמ\"ה מאי\"ן תמצא</b>: איוב כח, יב."],["9280","86","<b>ב' מזלו' דא\"א. . המוחי' לאו\"א</b>: ראה ע\"ח שער הכללים פ\"ה. לעיל פ' שמות לו, א הערה 455."],["9281","87","<b>וג' כתרים הן</b>: אבות פ\"ד, מי\"ג. ראה גם לקמן תנא, ב תנז, ג."],["9282","88","<b>טוב שם גם משמן הטוב</b>: קהלת ז, א [ושם בהשמטת תיבת גם [שניתוספה כאן בין השיטין]־ טוב — ראה ש\"א מב, ב. מאמרי אדה\"א נ\"ך ע' רטו]."],["9283","89","<b>והן</b>: אוצ\"ל: (והן."],["9284","90","<b>ג' פעמי' היכל ה' המה</b>: ירמי' ז, ד."],["9285","91","<b>ג' פעמי' היכל. . ג\"פ קדו\"ש</b>: ראה גם לעיל תמב, ד. וש\"נ."],["9286","92","<b>כריעו' והשתחוואו' דר\"ע</b>: ברכות לא, א."],["9287","93","<b>שיאמרו לפני הצדיקי' קדו\"ש</b>: ב\"ב עה, ב."],["9288","94","<b>ונשאו הלוי\"ם</b>: נסמן לעיל תמה, א הערה 124."],["9289","95","<b>והקימו את המשכן</b>: בהעלותך י, כא."],["9290","96","<b>ובהתחלת הקמת המשכן הוקם ע\"י מש\"ה</b>: ראה רש\"י פקודי לט, לג. לקו\"ש פקודי (כרך יא) ע' 181."]]],[2300550317,"או\"א הוא בפסוק ראשון דק\"ש בתיבות דהוי' אלקינ\"ו<sup data-n=\"9291\">97</sup> שהן בחי' י\"ה כו' ובפסוק ואהבת ואילך היחוד נעשה בבחי' ז\"א<sup data-n=\"9292\">98</sup>, כי האהבה הוא אור החסד דז\"א וכל הפרקין דז\"א מתייחדים בו כו' אבל בפסוק ראשון שהיחוד בבחי' או\"א כנ\"ל אין אור האהבה מורגשת שם עדיין אחר שהיחוד שם בבחי' הביטול דחכמ\"ה כח מ\"ה כנ\"ל, ובבחי' הביטול כזה לא שייך אור אהבה בהתפעלות מורגשת אחר שאין עוד מלבדו ממש כו' לא יש מי שאוהב כו', אלא אחר בחי' היחוד דאו\"א בבחי' הביטול אח\"כ נמשך האור למטה להיו' מתפשט האור בבחי' החסד שבז\"א והוא אור האהבה וכן עד\"ז שאר הפרקין כו'. ונמצא היחוד שבפסוק ראשון הוא כמו מדרגת משכן העדו\"ת הנ\"ל שהוא ג\"כ בבחי' יחוד דאו\"א ולכך פקד עפ\"י מש\"ה דוקא שהוא בחי' מ\"ה שבחכמה כו' ובפסוק ואהבת הוא כדוגמת משכן דלתתא בבחי' יחודא תתא' דזו\"נ כנ\"ל וד\"ל.\n<b>והנה</b> סדר העבודה סידרו אנשי כה\"ג לומר פסוקי דזמרה<sup data-n=\"9293\">99</sup> קודם ק\"ש, והענין הוא לפי שמעלת יחוד זה דאו\"א גבוה מאד ולא יוכלו כנ\"י להגיע אליו מצד שרש נפשם שהוא רק בבחי' זו\"נ כידוע, לכך תיקנו שיאמרו פסוקי דזמרה תחלה. וענין הזמרה הזאת הוא מעלת ומדרגת הלוים נושאי המשכן וכמ\"ש בהם ונשאו הלוים כו' והקימו המשכן<sup data-n=\"9294\">100</sup> כו', לפי שהשיר בחי' אור חוזר הוא ויכול לנשאות ולהגבי\"ה את נפש האדם למטה. וכך המשל למעלה שהשכינה מתרוממת בכסא הכבוד ע\"י נושאי הכסא וכמ\"ש והחיו' נושאו'<sup data-n=\"9295\">101</sup> כו' והוא מפני בחי' השיר של המלאכי' הנושאי' את הכסא כו' וכמ\"ש בזוהר ע\"פ ותשרנה <span data-k=\"pg\">1328</span> ּ הפרו\"ת<sup data-n=\"9296\">102</sup> כו'. וכך הי' ענין הלוים למטה שהיו נושאי' המשכן כו', ועד\"ז הוסדו פסוקי דזמרא<sup data-n=\"9297\">103</sup> לנשאות ולהגביה את בחי' משכן התחתון דזו\"נ ולקשרו ולחברו בבחי' משכן העליון שבבחי' או\"א ואזי יוכלו כנ\"י ליחד יחוד העליון הזה דאו\"א בפסוק ראשון וד\"ל. אך קודם שנשאו הלוים המשכן הוקם המשכן ע\"י משה דוקא ואזי הי' כח בלוים לנשאו' אותו תמיד והענין הוא בחי' כח המעלה מ\"ן<sup data-n=\"9298\">104</sup> מלמטה שהוא מהארת והשפלת בחי' יסוד אבא כו' וכמ\"ש במ\"א.\n<b>ונמצא</b> סדר העבודה כך הוא פסוקי דזמרה קודם לנשאו' יחודא תתא' ולחברו ביחודא עילא' בפסוק ראשון",[["9291","97","<b>בפע\"ח דבחי' יחוד או\"א. . דהוי' אלקינ\"ו</b>: ואתחנן ו, ד. ראה שם (שער הק\"ש) ש\"ח, פ\"ז. פי\"א. סידור שער הק\"ש עד, סע\"ד."],["9292","98","<b>ואהבת ואילך. . ז\"א</b>: שם ו, ה. ראה פע\"ח שם פכ\"ג."],["9293","99","<b>סידרו אנשי כה\"ג לומר פסוקי דזמרה</b>: ראה גם לעיל תמה, א. וש\"נ."],["9294","100","<b>והקימו המשכן</b>: ראה לעיל הערה 95. תמה, א הערה 125."],["9295","101","<b>והחיו' נושאו'</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד. הנסמן במאמרי אדה\"א בראשית ע' שעג."],["9296","102","<b>ותשרנה הפרו\"ת</b>: שמו\"א ו, יב [ושם: וישרנה — ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשסו. וש\"נ. תו\"ח וישלח קפא, ג הערה 43]. ראה זהר ח\"ש קכג, א. תרומה קלח, רע\"א."],["9297","103","<b>דזמרא</b>: כ\"ה בגוכי\"ק."],["9298","104","<b>כח המעלה מ\"ן</b>: ראה גם הנסמן לעיל בפ' תצוה שמו, ב הערה 59."]]],[2300550342,"שהוא משכן העדו' וזהו ששם עלו שבטי' שבטי י\"ה דוקא עדו' לישראל כו' וכנ\"ל, ואח\"כ ואהבת וכו' נמשך האור מיחוד דאו\"א בזו\"נ והיינו מאמר כגוונא דאינון מתייחדי' לעילא<sup data-n=\"9299\">105</sup> כו' עד למהוי אחד באחד כו' ואח\"כ ביד איתמ\"ר בן אהרן<sup data-n=\"9300\">106</sup> כו' שהוא כענין אתאמר<sup data-n=\"9301\">107</sup> וכמ\"ש אז נדבר\"ו<sup data-n=\"9302\">108</sup> כו'. הענין הוא מה שאמר בק\"ש אחר ואהבת כו' והיו הדברים האלה כו' ודברת בם<sup data-n=\"9303\">109</sup> בשבתך כו' שהוא בחי' גילוי אורו' דאו\"א ממש למטה כו', והיינו שיהא נמצא מציאת בחי' הביטול במציאו' שבמקום או\"א גם למטה בהיכלו' ועולמו' שנמשכי' מזו\"נ כו', וזהו רק ע\"י הדיבור בד\"ת דוקא וכמ\"ש ואשים דבר\"י בפיך<sup data-n=\"9304\">110</sup> כו'. וכענין שנמצא בחי' ביטול הזה גם במלאכי' העליונים שנא' בהם והחיו' רצוא ושוב<sup data-n=\"9305\">111</sup> כמראה הבזק כו' שהלהב עולה ויורד כנר המאיר ששלהבת עולה ויורד תמיד שהוא ג\"כ בחי' ביטול קצת אבל בדיבור בד\"ת הוא אמיתי' הביטול והוא ענין ביטול תמידי בלתי הפסק כלל, וכענין מ\"ש אלקי' אל דמי לך<sup data-n=\"9306\">112</sup> אל תחרש ואל תשקוט כו' וכמ\"ש בזוהר והדיבור אינו אלא בחי' כלי בעלמא לביטול זה וכמ\"ש ואשים דבר\"י בפיך כו' וכמ\"ש במ\"א שזהו כמו מדרגת משה שהיתה שכינה מדברת מתוך גרונו<sup data-n=\"9307\">113</sup> כו' וזהו איתמ\"ר ממילא כמו אז נדבר\"ו כו' וד\"ל. וזהו נתאוה הקדב\"ה להיו' לו דירה בבחי' הביטול הזה בתחתוני\"ם דוקא והוא בחי' גילוי יחוד דאו\"א למטה ולע\"ל יהי' גילוי זה על צד השלימות משום שיבוער הרע לגמרי וכמ\"ש בלע המות לנצח כו' וכנ\"ל ועכשיו אין גילוי זה בשלימות אך אפס קצהו מלובש ביטול זה בדיבור בד\"ת וזהו כל העוסק בט\"ל תורה<sup data-n=\"9308\">114</sup> טל תורה מחייהו וד\"ל.\n<b>ובזה</b> יובן ג\"כ שרש ענין ז' ימי' דפסח שנא' בהן מצות יאכל את ז' הימי' וכנ\"ל שהוא בחי' המשכת הביטול הנ\"ל גם במדו' דז\"א כו' שהן ז' ימים, אך מפני בחי' קטנו' המוחי' דז\"א צריך שיתלבש בחי' ביטול זה בבחי' הקטנו' והוא בחי' קטנות דאבא<sup data-n=\"9309\">115</sup>, והיינו במה שמלובש במאכל גשמי כמצה וכמ\"ש במ\"א בענין המצה שהוא כענין אין התינוק יודע לקרות אבא<sup data-n=\"9310\">116</sup> כו' שידיעה זו בהעלם היא אצלו כו' כך מ\"ה דאבא במצה בהעלם היא להיו' כי ז' הימי' בבחי' הקטנו' הם עדיין בפסח שהוא בחי' הליד\"ה כידוע וד\"ל.",[["9299","105","<b>כגוונא דאינון מתייחדי' לעילא</b>: ראה זהר תרומה קלה, סע\"א."],["9300","106","<b>ביד איתמ\"ר בן אהרן</b>: פקודי לח, כא."],["9301","107","<b>אתאמר</b>: ירושלמי ב\"ב פ\"ג, ה\"א."],["9302","108","<b>אז נדבר\"ו</b>: מלאכי ג, טז."],["9303","109","<b>והיו הדברים. . ודברת בם</b>: ואתחנן ו, ו. ז. ראה גם לעיל פ' יתרו רנג, ד. משפטים רפז, ג. ויקהל שפט, ד. מאמרי אדה\"א שמות ח\"א ע' רצ. וש\"נ."],["9304","110","<b>ואשים דבר\"י בפיך</b>: ראה גם לעיל תמה, ד ובהערה 144."],["9305","111","<b>והחיו' רצוא ושוב</b>: יחזקאל א, יד. ראה לעיל תמה, א הערה 126."],["9306","112","<b>אלקי' אל דמי לך</b>: נסמן לעיל בפ' יתרו רעג, ב הערה 160."],["9307","113","<b>שכינה מדברת מתוך גרונו</b>: ראה תניא פל\"ד. לעיל פ' בשלח קצד, ד הערה 540."],["9308","114","<b>כל העוסק בט\"ל תורה</b>: ראה יל\"ש ישעי' כו, יט (רמז תלא) [ושם: כל המשתמש]. וראה לעיל פ' בשלח רלט, א הערה 1067."],["9309","115","<b>מצות. . קטנות דאבא</b>: ראה גם סידור סדר הגדה חצר סע\"א ואילך. לעיל פ' בא צד, ד. וש\"נ."],["9310","116","<b>אין התינוק יודע לקרות אבא</b>: ראה ברכות מ, א. לעיל שם צה, ב הערה 410."]]],[2300550070,"<b>בעזר\"ה יום א' דפסח (ביאור שני לתורה דאלה פקודי המשכן כו')</b>\n<span data-k=\"pg\">תרסד</span> ּ<b>להבין</b> שרשי הדברים הנ\"ל<sup data-n=\"9311\">1</sup> ע\"פ אלה פקודי המשכן<sup data-n=\"9312\">2</sup> משכן העדות אשר פקד עפ\"י משה כו'. הנה כתיב שאו מרום עיניכם וראו מ\"י ברא אל\"ה<sup data-n=\"9313\">3</sup> פי' מ\"י הוא בחי' בינה<sup data-n=\"9314\">4</sup> הנק' אם הבנים<sup data-n=\"9315\">5</sup> ולהיות כי יש בה חמשים שערים ונק' חמשים שערי בינה<sup data-n=\"9316\">6</sup> כידוע לכך נק' מ\"י שמספרו חמשים<sup data-n=\"9317\">7</sup>, ומ\"י ברא אל\"ה שתולדות המדו' נולדו מן השכל וההתבוננו' והתפעלות השכל נק' שער\"י בינ\"ה כידוע, ויציא' והמשכת התפעלות השכל ללב שבו משכן המדו' אוי\"ר וענפיהן נצח והוד וכו' נק' אל\"ה להיותם ששה מדו' וכל מדה כלולה מששה שמספרו ל\"ו<sup data-n=\"9318\">8</sup> כו' ולהבין איך כל מדה כלולה מששה המדו' הנה מבוארי' המה בכוונו' הספירה<sup data-n=\"9319\">9</sup> ביום הא' ספי' חסד שבחסד וביום הב' גבורה שבחסד וכו' עד מל' שבחסד שהיא השביעי' ואינה במנין הששה מדו'<sup data-n=\"9320\">10</sup> כידוע.\n<b>וביאור</b> ענין חסד שבחסד וגבורה שבחסד כו', הנה ידוע שהאהבה נק' חסד כמ\"ש אהבת עולם אהבתיך<sup data-n=\"9321\">11</sup> ע\"כ משכתיך חסד וחסד שבחסד היינו אהבה הנגלית מתוך האהבה המסותרת, כמו אהבת האב לבנו כשהיא מתגלית לעיני הכל הגם שאין בה התחדשו' כי אהבתו טבעית אליו בתמידו' אך יציאת' בגילוי זה מתוך ההסתר המוטבע נק' חסד שבחסד כמו שהחסדן מצד טבעו כאשר מתחסד עם הבריו' כו'. ובחי' גבורה שבחסד הוא בחי' קו השמאל שבמדה זו והיא מעצמו' המדה אלא שמלובשת האהבה בדבר שהוא היפכה, דהיינו כמו לשנוא מי ששונא לאוהבו וכיוצא שהשנאה הזאת גבורו' ודינין היא והיא נמשכה מצד האהבה שאוהב לאוהבו. וכן אהבת האב לבנו גורמת דוקא שיכהו בשבט מוסר על הטותו מדרך הטוב שלולי האהבה לא הי' כועס עליו כלל, וכיוצא בזה בכל מה שיתפס אור האהבה בלבוש שהוא היפכה נק' גבורה שבחסד, כלומר הדין המסתעף רק מצד האהבה שדין זה מעצמו' מדת האהבה הוא ונק' גבורה שבחסד, והם נקראי' בחי' גבורו' ממותקו' כמ\"ש במ\"א (בענין קללו' שבמשנה תורה שיהופכו לברכו'<sup data-n=\"9322\">12</sup> מפני שמתוך האהבה נאמרו וכאשר יבוער הרע יגלה אור האהבה שבהן). ובחי' תפארת שבחסד הוא דוקא כאשר מתפאר ומתייפה ע\"י השפעת הטוב והחסד הזה בעיני הבריו' שזהו מצד היופי שיש במדה זו מפני שיש חסד שהוא יפה ומייפה בתפארת",[["9311","1","<b>להבין שרשי הדברים הנ\"ל</b>: הנחת כ\"ק אדה\"א מדרוש אביו כ\"ק אדה\"ז מיום א' דפסח שנת תקס\"ו. ראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י."],["9312","2","<b>אלה פקודי המשכן</b>: פקודי לח, כא."],["9313","3","<b>שאו מרום. . אל\"ה</b>: ישעי' מ, כו."],["9314","4","<b>מ\"י הוא בחי' בינה</b>: נסמן לעיל תמג, ד הערה 78."],["9315","5","<b>בינה הנק' אם הבנים</b>: נסמן לעיל בפ' משפטים רצו, ב."],["9316","6","<b>חמשים שערי בינה</b>: ר\"ה כא, ב."],["9317","7","<b>מ\"י שמספרו חמשים</b>: ראה זהר בהקדמה ד, א."],["9318","8","<b>המדו'. . נק' אל\"ה. . שמספרו ל\"ו</b>: נסמן לעיל בפ' משפטים רצא, ד."],["9319","9","<b>בכוונו' הספירה</b>: ראה סידור אדה\"ז סדר ספירת העומר. סידור האריז\"ל שם. פע\"ח ומ\"ח שם."],["9320","10","<b>מל'. . ואינה במנין הששה מדו'</b>: ראה אגה\"ת פ\"ד. לעיל תמז, א הערה 53."],["9321","11","<b>אהבת עולם אהבתיך</b>: ירמי' לא, ב [ושם: ואהבת — נסמן לעיל בפ' וארא סב, ג הערה 131]."],["9322","12","<b>קללו'. . שיהופכו לברכו'</b>: ראה גם לעיל פ' תצוה שנב, ג. וש\"נ."]]],[2300550102,"לעושי' ג\"כ משא\"כ כשהחסד בלתי מפואר כמו כאשר יטיב חסדו לרשעי' וכיוצא, וכמ\"ש כי טוב חסדך מחיים<sup data-n=\"9323\">13</sup> וכן מה יקר חסד\"ך<sup data-n=\"9324\">14</sup> וכיוצא שכולם ענין יופי החסד כשנשפע החסד במדת היופי כו'. ובחי' נצח שבחסד הוא אשר אנו רואי' באדם שיש לו איזה אהבה ותשוקה לדבר מה הנה ישתדל בכל כחו להמציא אותו הדבר אליו או שיגיע הוא ויתקרב לאותו הדבר ואם יהי' מניעו' רבות מאד עד שאין ביכולתו להשיגו אז יבוא במדת הנצחון שינצח א\"ע לעמוד נגד כל מונע וישיג ויגיע לאותו הדבר בנצחון גדול כו', והרי סיבת ניצוח הזה אינו אלא מצד האהבה וכל שהאהבה אינה גוברת בו כ\"כ לא יוכל <span data-k=\"pg\">1330</span> ּ לעמוד בנצחון כ\"כ נגד כל מונע ומעכב כו' וערך הניצוח הוא לפי ערך האהבה, וזהו הנק' נצח שבחסד שהיא אור האהבה עצמה אלא שמלובשת בנצחון כו' (משא\"כ מדת הנצח כשהוא מצד עצמו בלבד בלתי הגלו' בו אור האהבה שנק' בדי ערבו' שאין בהן טעם וריח<sup data-n=\"9325\">15</sup> כו' היינו נצח והוד<sup data-n=\"9326\">16</sup> הנק' ירכין<sup data-n=\"9327\">17</sup> ולא נחשבו מגופי המדו' חו\"ג כלל, והיינו כאשר אהבתו נסתלקה לגמרי אך רשימו בעלמא נשאר ובזה מנצח א\"ע להיו' נמשך בעל כרחו כמו האוהב ללמוד בטבע שאע\"פ שלפעמי' לא יחשוק כלל ינצח א\"ע כו' וכמ\"ש במ\"א. אבל נצח זה שמצד הגלות נגלו' בו אור האהבה דוקא זהו הנק' נצח שבחסד והיא ממדת האהבה ממש כנ\"ל הטעם שהרי כל מה שיאהוב יותר יותר יעמוד נגד כל מונע בנצחון כו' וד\"ל). ועד\"ז יתפרשו כל פרטי התכללות המדות כל א' מששה כמו מדת הדין שיש בו בחי' חסד שבגבורה וגבורה ות\"ת ונצח וכו' וכן במדת הת\"ת חסד שבת\"ת וגבורה ונצח שבת\"ת וכו'<sup data-n=\"9328\">18</sup> וד\"ל.\n<b>והנה</b> ענין ספירת העומר הוא לספור בחי' המדות עליונו' ז' שבועו'<sup data-n=\"9329\">19</sup> בכלל שהן ז' פעמי' ז' בפרט כדי לספר<sup data-n=\"9330\">*20</sup> ולברר המדות מכל סיג ופסולת, כי הנה ענין העומר מדה היא כמ\"ש והעומר עשירי' האיפה<sup data-n=\"9331\">20</sup> כו' והענין של מדת העומר הוא כענין ודוגמא של העומר במן שנא' בו עומר לגלגלת<sup data-n=\"9332\">21</sup> כו'. כך למעלה יהא אורו' המדות נמדדי' במדה זו הנק' עומ\"ר לגלגלת כו', דהיינו מבלתי יטה אור שפעם להיכלו' הנוג\"ה שמקבלי' ממותרי המדו' כענין אברהם איש החסד<sup data-n=\"9333\">22</sup> שיצא ממנו ישמעאל<sup data-n=\"9334\">23</sup> כו'. וזהו היום נמדד יום אחד לעומ\"ר<sup data-n=\"9335\">24</sup> למדת העומר ונק' עומר לגלגל\"ת (דהיינו בחי' כת\"ר<sup data-n=\"9336\">25</sup> ), להיו' כי בעה\"ד טו\"ר נשפע מותרו' וע\"י העומר נמדד והוגבל האור ונבדל הפנימי' מן",[["9323","13","<b>כי טוב חסדך מחיים</b>: תהלים סג, ד."],["9324","14","<b>מה יקר חסד\"ך</b>: תהלים לו, ח."],["9325","15","<b>בדי ערבו' שאין בהן טעם וריח</b>: ויק\"ר פ\"ל, יב. וראה גם שה\"א קא, ב."],["9326","16","<b>בדי ערבו'. . נצח והוד</b>: ראה זהר ויחי רכ, ב. לעיל פ' בשלח רמח, ג הערה 75."],["9327","17","<b>נצח והוד הנק' ירכין</b>: ראה ת\"ז תי\"ג (כט, א) ובהנסמן בניצוצי זהר שם."],["9328","18","<b>וכו'</b>: תיבה זו איננה ברורה בגוכתי\"ק."],["9329","19","<b>ספירת העומר. . ז' שבועו'</b>: אמור כג, טז."],["9330","*20","<b>לספר</b>: כ\"ה בגוכתי\"ק."],["9331","20","<b>והעומר עשירי' האיפה</b>: בשלח טז, לו."],["9332","21","<b>עומר לגלגלת</b>: בשלח טז, טז."],["9333","22","<b>אברהם איש החסד</b>: נסמן לעיל פ' יתרו רנט, א."],["9334","23","<b>אברהם. . שיצא ממנו ישמעאל</b>: ראה פסחים נו, א. לעיל פ' בא קיז, ג. וש\"נ."],["9335","24","<b>היום. . יום אחד לעומ\"ר</b>: נוסח ספירת העומר."],["9336","25","<b>לגלגל\"ת. . כת\"ר</b>: ראה ע\"ח (שער א\"א) שי\"ג, פ\"ג."]]],[2300550134,"החיצוניו' בכל ההמשכו' שנמשך בזמן ימי הספירה מהמדו' עליונו', ומה שמקבלת מלכו' דנוג\"ה עומר שעורי'<sup data-n=\"9337\">26</sup> מאכל בהמ\"ה<sup data-n=\"9338\">27</sup> מאחוריי' דשם ב\"ן דבהמ\"ה<sup data-n=\"9339\">28</sup> דקדוש' גם הוא נקרב בזמנו ומתברר ממנו כל משך זמן הימי' הללו. ולכך נק' ספיר\"ת העומר מלשון אבן ספי\"ר<sup data-n=\"9340\">29</sup> מפני שמתברר העומר שעורי' מאכל בהמ\"ה מה שנאחזי' במדו' תערובו' טו\"ר בעה\"ד כו'. ואמנם אין ההתבררו' אלא ע\"י הבינה הנק' אם הבנים כמ\"ש אם רחץ ה'<sup data-n=\"9341\">30</sup> צואת בנות ציון א\"ת א ם אלא א ם<sup data-n=\"9342\">31</sup> והוא בחי' בינה אימא עילא' הנק' אם הבנים וכאמרו תבא האם ותקנח צואת בנה<sup data-n=\"9343\">32</sup> כו', כי עד\"מ התינוק כשהוא בקטנותו מתלכלך בצואה וטיט שאין בשכלו לרחוץ ולנקות א\"ע אלא תבוא אמו ותקנחו מצואתו ותרחיצנו, כך הנמשל למשכיל למעלה דבחי' המדו' העליונו' דז\"א כשבאי' בבחי' הקטנו' אזי באים בבחי' המותרו' בעה\"ד טו\"ר כו' ונק' עד\"מ כמו צואת התינוק וע\"י אימא עילא' הוא בחי' בינה דאצי' שמאירי' בימי הספי' באמרו היום יום א' כו' מתבררי' בחי' הקטנו' הללו ומרחיצין כל סיג ופסולת וזהו אם רחץ ה' צואת כו'. ויובן זה בנפש האדם למטה שמדותיו הבהמיי' התאוה והכעס וכו' המה נאחזי' במדו' דקדושת נפש האלקי' ומדו' המגונו' שלו נק' צואה של מדו' דקדושה וצריכי' ריחוץ ונקיון תמיד כמ\"ש ארחץ בנקיון כפי<sup data-n=\"9344\">33</sup> כו' והוא להסיר המדו' המגונו' הללו, וזהו בימי ספירת העומר דוקא ואזי יוכלו לקבל בנפשם בחי' ביטול במציאו' כמ\"ש באברה\"ם הלוך ונסוע הנגב\"ה<sup data-n=\"9345\">34</sup> פי' הנגב\"ה הוא בחי' ביטול במציאו' כמו הנגב שאין לחלוחיו' כלל כו', אך א\"א לבא לבחי' ביטול זה כ\"א בהקדים תחלה אוי\"ר בבחי' רצוא ושוב כמ\"ש באברהם הלוך ונסוע שהוא בחי' רו\"ש<sup data-n=\"9346\">35</sup> כידוע ואח\"כ בא בחי' הנגב\"ה כו' וד\"ל.\n<b>וזהו</b> אם הבנים שמחה<sup data-n=\"9347\">36</sup> שזהו נאמר דוקא בגמר ענין ימי הספירה מפני שע\"י הבינה הנק' אם הבנים דוקא <span data-k=\"pg\">תרסה</span> ּ נבררו כל המדו' מכל סיג ופסולת, כי ע\"י ההתבוננו' דוקא יבורר אור כל מדה כמו מדת האהבה שבלתי ההתבוננו' לא תהא מבוררת כ\"כ מתערובו' טו\"ר כענין אברהם שיצא ממנו ישמעאל וכיוצא בזה בעבודת ה' ידוע שיש טו\"ר בכל התפעלו' כו', אבל ע\"י ההתבוננו' שמקפת את ההתפעלו' מבררת אותה עד שתהא ברורה לגמרי וכמ\"ש נקי כפיים וב\"ר לבב<sup data-n=\"9348\">37</sup> כב\"ר היוצא מן התבן וכיוצא והוא ענין אימא עילא' למעלה שרוחצת את צואת",[["9337","26","<b>עומר שעורי'</b>: מנחות סח, ב. תו\"כ ויקרא ב, יד."],["9338","27","<b>שעורי' מאכל בהמ\"ה</b>: ראה פסחים ג, סע\"ב. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תרמג."],["9339","28","<b>דשם ב\"ן דבהמ\"ה</b>: ראה תניא ספמ\"ו. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ."],["9340","29","<b>ספיר\"ת העומר מלשון אבן ספי\"ר</b>: ראה גם ספר ערכי הכנויים לבעל סדר הדורות מערכת ספיר [ספירה]. לקו\"ת אמור לה, ב. מאמרי אדה\"א במדבר ח\"א ע' סג. ח\"ב ע' שכ."],["9341","30","<b>אם רחץ ה'</b>: ישעי' ד, ד [ושם: את צאת]."],["9342","31","<b>א\"ת א ם אלא א ם</b>: פע\"ח (שער השבת) שי\"ח, פ\"ג. מאמרי אדה\"א ויקרא ח\"ב ע' תקיב. וש\"נ."],["9343","32","<b>תבא האם ותקנח צואת בנה</b>: ראה במדב\"ר פי\"ט, ח. תנחומא חוקת ח."],["9344","33","<b>ארחץ בנקיון כפי</b>: תהלים כו, ו."],["9345","34","<b>הלוך ונסוע הנגב\"ה</b>: לך יב, ט [ושם: ויסע אברם]."],["9346","35","<b>הלוך ונסוע. . רו\"ש</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרל. לעיל פ' בשלח קעה, ג. וש\"נ."],["9347","36","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["9348","37","<b>נקי כפיים וב\"ר לבב</b>: תהלים כד, ד."]]],[2300550166,"הבן עד\"מ כנ\"ל בפי' א\"ם רחץ ה' כו'. ולכך נק' הבינה יובלא עילא' בזוהר לפי שהיא מבררת כל סיג ואין לחיצוני' יניק' כלל במדות ואז נק' בני חורין, וזהו שנק' בינ\"ה עולם החירות<sup data-n=\"9349\">38</sup> חירות משיעבוד מלכיו'<sup data-n=\"9350\">39</sup> כו' שהי' בשעת מ\"ת אחר שספרו ימי הספירה דוקא כמ\"ש בעטרה שעטרה לו אמ\"ו<sup data-n=\"9351\">40</sup> כו' כי בימי הספירה נבררו מכל סיג כנ\"ל. וזהו אם הבנים שמחה פי' שמחה בחי' המתקת הדינין נק' שמחה כי השמחה ממתקת הדינין<sup data-n=\"9352\">41</sup> כידוע, ושמחה זו דאימא עילא' הוא בשעת מ\"ת בשבועו' אחר שנמתקו כל הדינין ע\"י הבינה בכל ימי הספירה כי נתהפכו כל המדו' מחלק הרע הנאחז בהן לטוב, וידוע שבחי' ההתהפכו' הרע לטוב במדו' אינו אלא ע\"י הבינה<sup data-n=\"9353\">42</sup> משא\"כ בלא התבוננו' אינו אלא אתכפייא ולא אתהפכא כמ\"ש במ\"א, ואח\"כ יכלו לקבל התורה בבחי' יחוד פב\"פ כמ\"ש פא\"פ דיבר ה'<sup data-n=\"9354\">43</sup> כו' והוא בחי' הביטול במציאו' כמ\"ש וינוע\"ו<sup data-n=\"9355\">44</sup> והיינו ענין הנגב\"ה הנ\"ל אבל בלא התהפכו' המדו' א\"א לבא לבחי' מדרגת קבלת התורה בבחי' הביטול במציאו' כנ\"ל וד\"ל.\n<b>והנה</b> כדוגמא זאת הנ\"ל במדות שהן ששה וכאו\"א כלול מששה כו' כך בתורה יש בחי' המדו' הנ\"ל בכלל והן שיתא סדרי משנה<sup data-n=\"9356\">45</sup> כידוע שסדר זרעים בחסד<sup data-n=\"9357\">46</sup> וכו' וכאו\"א כלול מששה, כי הרי סדר זרעים כלול גם מסדר טהרות שהמשנה בלולה בכל מסכת' ממשניו' של סדר אחר זולתו ובסדר זרעי' נמצאו משניו' מכל חמשה הסדרים זולתה ועד\"ז בכל סדר וה\"ז כמו שמבואר למעלה דכל מדה כלולה מכל הששה (ופרטיהן ל\"ו מסכתו'<sup data-n=\"9358\">47</sup> שמספרו ג\"כ אל\"ה). והמצות הן הנק' איברי'<sup data-n=\"9359\">48</sup> כידוע והן בחי' חיצוניו' לבחי' המדו' הללו דשית' סדרי משנה, כי המדו' הללו הן בחי' פנימיו' המדו' עליונו' וחיצוניו' שלהן בבחי' לב העליון ולב פליג לכל שייפין<sup data-n=\"9360\">49</sup> שהן רמ\"ח פקודי' רמ\"ח איברי'<sup data-n=\"9361\">50</sup>. ואמנם דרך כלל התורה נק' אברי' הפנימי' והמצות איברי' החיצוני', ועד\"מ באדם התחתון הנה איברי המזון כאצטומכא וכיוצא למטה מאיברי הנשימ' לב וריאה ואברי המזון מבררי' המאכל ושולחי' שפע רוחני' המאכל לכל האיברי' החיצונים ומתחזקין בכחם עי\"ז ומבלעדי המזון היו מתחלשי' כח הראי' מתחלש בעין וכח ההילוך מתחלש ברגל וכיוצא. כך למעלה המצות שנק' איברי' המה בחי' איברי' החיצוני' ומתחזקי' כולן ע\"י איברים הפנימי' המבררי' המזון",[["9349","38","<b>הבינה יובלא עילא'. . עולם החירות</b>: ראה זהר תצוה קפג, א. לעיל פ' שמות כו, ג הערה 109."],["9350","39","<b>חירות משיעבוד מלכיו'</b>: ראה זהר (סבא) משפטים קיג, סע\"ב. ת\"ז תקונא שביעאה קמו, ב."],["9351","40","<b>בעטרה שעטרה לו אמ\"ו</b>: נסמן לעיל תמד, ב הערה 98."],["9352","41","<b>השמחה ממתקת הדינין</b>: ראה גם לעיל פ' וארא סט, ג ובהערה 23."],["9353","42","<b>ההתהפכו'. . במדו'. . ע\"י הבינה</b>: ראה גם מאמרי אדה\"ז אתהלך לאזניא ע' נז."],["9354","43","<b>פא\"פ דיבר ה'</b>: ואתחנן ה, ד."],["9355","44","<b>וינוע\"ו</b>: יתרו כ, טו."],["9356","45","<b>שיתא סדרי משנה</b>: ראה במדב\"ר פי\"ב, יז. פי\"ג, טוטז. לעיל פ' שמות ג, א. וש\"נ."],["9357","46","<b>שסדר זרעים בחסד</b>: נסמן לעיל בפ' ויקהל תלט, ד הערה 1913."],["9358","47","<b>ל\"ו מסכתו'</b>: ראה מגלה עמוקות אופן רלז בהגה. ובמפתחות לסימן זה. לקוטי לו\"י אגרות ע' תיח."],["9359","48","<b>והמצות. . איברי'</b>: נסמן בהערה 50."],["9360","49","<b>ולב פליג לכל שייפין</b>: נסמן לעיל בפ' תרומה שיד, א הערה 166."],["9361","50","<b>רמ\"ח פקודי' רמ\"ח איברי'</b>: ראה ת\"ז ת\"ל (עד, סע\"א). שע\"ת עב, ג הערה 17."]]],[2300550198,"והוא אור התורה שנק' מזו\"ן וכמ\"ש לכו לחמו בלחמ\"י<sup data-n=\"9362\">51</sup> כידוע וזהו מ\"ש ותורתך בתוך <span data-k=\"pg\">1332</span> ּ מע\"י<sup data-n=\"9363\">52</sup> כו' והלב בו פנימי' המדו' שבתורה שהן סדרי המשנה כו', ונמצא ע\"י התורה מתחזק כח המצות ואם לאו היו מתחלשי' וע\"כ אמרו ז\"ל דת\"ת כנגד כולן<sup data-n=\"9364\">53</sup> וכן תלמוד גדול שמביא לידי מעשה<sup data-n=\"9365\">54</sup> וד\"ל.\n<b>ואמנם</b> הנה בזאת יתרון מעלת מעשה המצות מבתורה שהרי התורה הוא בחי' המדו' כמו שהן למעלה בבחי' אצי' דאיהו וחיוהי וגרמוהי חד<sup data-n=\"9366\">55</sup> כו' הכל בבחי' אלקו' ממש כו', משא\"כ המצות הן באי' ומתלבשי' למטה מטה בלבושי' הנפרדי' בעולמו' הנפרדי' בי\"ע עד רגלי העשי' בעולם השפל כמו בקלף תפילין וצמר ציצית וכיוצא. ונמצא על ידן נעשה ונמשך בחי' גילוי אלקו' גם במדרגו' היותר תחתונות מכל ההשתלשלו'. והנה ידוע הכלל דכל שההארה מתפשטת במקום ומדרגה היותר נמוך מוכרח לומר ששרש אותה ההארה באה ממקום ומדרגה היותר גבוה כי כל הגבוה גבוה יותר<sup data-n=\"9367\">56</sup> יותר יוכל להשפיל א\"ע ע\"כ בהכרח לירידת אור במקום הנמוך מאד דוקא ממקום ומדרגה הגבוה מאד, כענין הידוע ע\"פ ועברתי בארץ מצרים אנ\"י ולא מלאך<sup data-n=\"9368\">57</sup> כו' שמפני שקליפ' מצרים במ\"ט שערי טומא'<sup data-n=\"9369\">58</sup> הי' ע\"כ בהכרח שיבא האור לשם מהיותר גבוה מכל ההשתלשלו' והוא מ\"ש אנ\"י ולא מלאך כו' וכמ\"ש במ\"א. וא\"כ גם במצו' מעשיות בהכרח לומר עפי\"ז שיש בהן ההארה ממקום היותר גבוה מכל ההשתלשלו' דאבי\"ע.\n<b>והענין</b> הוא שזהו הטעם שאמרו ז\"ל היום לעשותם ולמחר לקבל שכרם<sup data-n=\"9370\">59</sup> דהנה לכאורה אינו מובן דהרי ג\"ע עליון גם היום ישנו במציאו' וצדיקי' יושבי' בו ונהנין מזיו השכינה<sup data-n=\"9371\">60</sup> מדי חדש ושבת<sup data-n=\"9372\">61</sup> כידוע ולמה אמר למח\"ר דוקא לקבל שכרם של מעש' המצו', אלא צריך לומר דמה שנהנין עכשיו מזיו כו' אינו קיבול שכר עדיין אלא למחר דוקא והוא לאחר תחיית המתים דכתיב אז עין בעין יראו<sup data-n=\"9373\">62</sup> כו' שהוא מדרגה יותר גבוה הרבה ממה שנהנין מזיו בג\"ע כו'. והטעם להבין זה הנה מובן ממה שקדם למעלה הכלל דכל שהאור בא למטה יותר הוא בא ממקום הגבוה יותר כו', והנה בתחיית המתים שיחיו הגופים הגשמיים וכמ\"ש בעצמות היבישו' וקרב עצם אל עצמו<sup data-n=\"9374\">63</sup> כו' הרי עור ובשר ועצמו' שהמה תכלית הגשם כאשר יבא",[["9362","51","<b>לכו לחמו בלחמ\"י</b>: משלי ט, ה."],["9363","52","<b>ותורתך בתוך מע\"י</b>: תהלים מ, ט."],["9364","53","<b>דת\"ת כנגד כולן</b>: פאה רפ\"א."],["9365","54","<b>תלמוד גדול שמביא לידי מעשה</b>: קדושין מ, ב."],["9366","55","<b>דאיהו וחיוהי וגרמוהי חד</b>: ראה ת\"ז בהקדמה (ג, ב)."],["9367","56","<b>ידוע הכלל. . כל הגבוה גבוה יותר</b>: ראה שערי אורה שער הפורים ע' נח וע' סה. לעיל פ' שמות כא, ב הערה 863."],["9368","57","<b>ועברתי. . אנ\"י ולא מלאך</b>: בא יב, יב. ספרי תבוא כו, ח. זהר (מהנ\"ע) וירא קיז, א. הגדה של פסח. ראה גם לעיל פ' וארא נד, ב. וש\"נ."],["9369","58","<b>שקליפ' מצרים במ\"ט שערי טומא'</b>: ראה ז\"ח יתרו לא, א. לעיל פ' שמות מא, ד. וש\"נ."],["9370","59","<b>היום לעשותם ולמחר לקבל שכרם</b>: ואתחנן ז, יא. ראה ערובין כב, א."],["9371","60","<b>וצדיקי'. . ונהנין מזיו השכינה</b>: אולי הכוונה למדרש תהלים מה, א (ג). ראה לקמן תנ, ב ד\"ה ובכל זה."],["9372","61","<b>וצדיקי'. . מדי חדש ושבת</b>: ראה גם לעיל פ' שמות לה, ב. וש\"נ."],["9373","62","<b>עין בעין יראו</b>: ישעי' נב, ח."],["9374","63","<b>וקרב עצם אל עצמו</b>: יחזקאל לז, ז [ושם: ותקרבו עצמות עצם אל עצמו]."]]],[2300550230,"עליהם אור וחיו' שיחיו מאור אלקי שיחיה אותם לעתיד, הנה בהכרח לומר שיבא האור ממדרגה היותר גבוה מאד נעלה אחר שהוא בא לתכלית הירידה בתחיית מתי עפר כו' כענין הנ\"ל בפסוק ועברת\"י בארץ מצרים כו', כי המת הוא אבי אבו'<sup data-n=\"9375\">64</sup> כו'. וע\"כ נאמר לעתיד כי עין בעין יראו כו' מפני שיבא האור מעצמו' המאציל שלמעלה מבחי' השתלשלו' אורו' וכלים כו' והוא הנק' מקור כל המקיפי' העליוני', דכל האורו' אינן אלא מבחי' הקו והחוט<sup data-n=\"9376\">65</sup> כו' עד שנמשך ובא לרגלי העשי' וכמשל העיגול שאין בו מעלה ומטה<sup data-n=\"9377\">66</sup> והתחתון עליון כמ\"ש ומתחת זרועו' עולם<sup data-n=\"9378\">67</sup> עד שרוחניו' וגשמיו' שוין ממש כו' וכידוע ולכך יחי' גם העצמו' היבישו' כו', והוא הטל שעתיד להחיו' בו המתים<sup data-n=\"9379\">68</sup> כמ\"ש כי טל אורו' טלך<sup data-n=\"9380\">69</sup> כידוע והוא בחי' טלא דנטיף מעתיקא<sup data-n=\"9381\">70</sup> ואנער לההוא דלבר כמ\"ש באד\"ר וד\"ל. וע\"כ קיבול שכר האמיתי יהי' דוקא למחר אחר תחיית המתים כי גבוה הרבה ממדרגת גילוי אלקו' שבג\"ע <span data-k=\"pg\">תרסו</span> ּ שנהנין מזיו כו' שהוא רק תענוג הנשמו' הרוחניי' אבל אחר שיוכל האור לבא גם להחיו' הגופים הגשמיי' בתח\"ה זהו בא ממדרגת עצמו' המאציל שלפני ההשתלשלו' דבחי' ממלא וסובב שהן הוי' אלקי'<sup data-n=\"9382\">71</sup> בחי' זו\"נ דאצי' בכלל כו' וד\"ל.\n<b>וזהו</b> כי עין בעין יראו כו' פי' עין בעין הוא ענין התחברו' ממלא וסובב שיתחברו והיו לאחדי' אז והוא בחי' עין של הא\"פ עם עין של א\"מ שיתחברו אז כו'. וביאור הדברים הנה תחלה יש להקדים מ\"ש בע\"ח דא\"פ מזכך חצי הכלי מבפנים והא\"מ מזכך חצי הכלי שמבחוץ<sup data-n=\"9383\">72</sup> ואזי ממילא נזדכך כל עובי דופני הכלי כו' ונעשה הכלי מצוחצח וזהו מ\"ש והשביע בצחצחות נפשך<sup data-n=\"9384\">73</sup> כו', דהנה ביאור ענין בחי' א\"פ ידוע שהוא מה שהמקבל האור יכול לקבל כפי השגתו בלבד דהיינו כפי הכלי אבל ההשגה עצמה שהיא בחי' הכלי מסתרת היא גופו של האור שאינו מאיר כמו שהוא בעצמו ומהותו מפני הגשמת כלי ההשגה כו', אך כשהאור מתגבר ומאיר תמיד בכלי ממקור השפע יכול זה הכח להאיר ולזכך גם את הגשמת הכלי מעט מעט ע\"י התמדת אורו בה, כנרא' בחוש הטבע שגם האבן המס ימס והי' למים כשהמים נובעי' בו בתמידו' יתירה וכמ\"ש אבנים שחקו מים<sup data-n=\"9385\">74</sup> וכענין שאמרו בר\"ע שנתפעל מזה כשהי' ע\"ה ולמד ק\"ו<sup data-n=\"9386\">75</sup> שלבו יקבל ד\"ת אם יתמיד להכניס אור התורה בלבו כו'.",[["9375","64","<b>המת הוא אבי אבו'</b>: ראה רש\"י פסחים יד, רע\"ב. יז, א. חוקת יט, כב (ד\"ה תטמא עד הערב). מאמרי אדה\"א דברים ח\"א ע' קסג, וש\"נ."],["9376","65","<b>דכל האורו'. . הקו והחוט</b>: ראה גם מאמרי אדה\"ז תקס\"ז ע' רמה. ענינים ע' שיז. שער היחוד קל, א ובהערה 5."],["9377","66","<b>העיגול שאין בו מעלה ומטה</b>: ראה גם לעיל פ' שמות לח, ד. וש\"נ."],["9378","67","<b>ומתחת זרועו' עולם</b>: ברכה לג, כז. ראה לעיל פ' וארא נה, ד. וש\"נ."],["9379","68","<b>הטל שעתיד להחיו' בו המתים</b>: ירושלמי ברכות פ\"ה, ה\"ב."],["9380","69","<b>כי טל אורו' טלך</b>: ישעי' כו, יט."],["9381","70","<b>טלא דנטיף מעתיקא</b>: ראה זהר (אד\"ר) נשא קכח, ב."],["9382","71","<b>ממלא וסובב. . הוי' אלקי'</b>: ראה גם לעיל פ' וארא עג, ב. וש\"נ."],["9383","72","<b>דא\"פ. . הכלי מבפנים והא\"מ. . שמבחוץ</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"ב. (שער השתל' הי\"ס) ש\"ב, ענף ג."],["9384","73","<b>והשביע בצחצחות נפשך</b>: ישעי' נח, יא."],["9385","74","<b>אבנים שחקו מים</b>: איוב יד, יט."],["9386","75","<b>בר\"ע. . ולמד ק\"ו</b>: אבות דר' נתן פ\"ו, ב."]]],[2300550261,"<b>וענין</b> מה שאור המקיף מזכך חצי הכלי מבחוץ הוא העומק מה שלא יתפס כלל בהשגת הכלי וישאר בבחי' מקיף על הכלי הוא אשר יזכך חצי עובי הכלי מבחוץ, כידוע שמפני הפלאת ההשגה תפול ההגשמה בנפש האדם אע\"פ שאינו מבין כו' והזדככו' זאת בחיצוניו' ההגשמה דוקא, משא\"כ מצד ההשגה בבחי' א\"פ יזדכך הפנימי' כו' ולפי שא\"מ גדול הרבה מא\"פ ע\"כ יזכך גם חלק החיצוניו' כו' וד\"ל. והנה מה שהנשמו' נהנין עכשיו מזיו השכינה בג\"ע העליון כו' הוא מבחי' ממלא כ\"ע והוא מבחי' א\"פ שנכנס בכלי שהוא בחי' הזיו והאור שיוכלו הנשמו' להנות ממנו בהרגשה ובא בכלי שלהם לזכך בהגשמה<sup data-n=\"9387\">*76</sup> כו', וזה האור מגיע להם כפי ערך המעשה שעשו והוא מעשה המצו' בעוה\"ז מפני שעשו עי\"ז בחי' כלים לקבל האור באצילו' כו' כידוע דרמ\"ח פקודי' רמ\"ח איברי' דמלכא ועי\"ז נמשך תוס' גילוי אורו' בכלים דז\"א בתמידו' כמאמר היום לעשותם, שהוא כענין מאמרם ז\"ל ועשיתם אתם כאילו עשאונ\"י<sup data-n=\"9388\">76</sup> פי' ברמ\"ח איברי' עד שנק' אד\"ם דאצי' וכמ\"ש אלה המצות אשר יעשה אותם האד\"ם<sup data-n=\"9389\">77</sup> כו' האדם דלעילא כידוע, וכמבואר למעלה דהמצות הן בחי' איברי' החיצוני' כו'. וגם והרחבת<sup data-n=\"9390\">78</sup> האור אלקי בג\"ע דבריא' נעשה עי\"ז לפי סדר ההשתלשלו' מאצי' לבריא' כו' כידוע שזהו פי' נעשה אד\"ם<sup data-n=\"9391\">79</sup> כו'. אך אע\"פ דכל שיתא אלפי שני דהוי עלמא<sup data-n=\"9392\">80</sup> נמשך תוספת גילוי אורו' בכלים דאבי\"ע בתמידו' מ\"מ אין זה רק מבחי' א\"פ, וגם זה עדיין נשאר אותו התוספת למעלה באצי'<sup data-n=\"9393\">81</sup> ואין מזכך חצי הכלים גם מבפנים כו' מפני שיש עדיין יניק' לחיצוני' בכלים של האורו' בכל עולם לפי ערכו, וגם באצי' דאיהו וגרמוהי חד כו' מ\"מ יש מחיצוניו' הכלים שרש ומקור ליניקו' החיצוני' <span data-k=\"pg\">1334</span> ּ למטה בבי\"ע כו'. אבל לע\"ל הנה יבוער רוח הטומא' לגמרי מכל וכל וכמ\"ש בלע המות לנצח<sup data-n=\"9394\">82</sup> כו', ואין זה הביעור מכל וכל אלא ע\"י בחי' אור המקיף שמזכך חצי הכלי מבחוץ ג\"כ שאז אין להם שרש יניק' כלל וכלל, וע\"כ אמרו היום לעשות\"ם ולמח\"ר לקבל שכר\"ם מפני שגדול יהי' אור אלקי הנגלה לע\"ל מהגילוי דזיו השכינ' בג\"ע עכשיו וד\"ל.\n<b>וביאור</b> זה הנה שרש כל הא\"פ הוא בחי' הקו והחוט<sup data-n=\"9395\">83</sup> כו' ושרש כל המקיפי' הוא מבחי' העיגול שלמעלה מבחי' הקו<sup data-n=\"9396\">84</sup> כו' שנק' סובב כ\"ע בכללות, והנה במעשה המצוה יש ב' מדרגו', הא' הכוונה בה מצד ההשגה בבחי' א\"פ. והב' מעשה המצוה לעשו' מצד שאמר ונעשה רצונו למעלה מן הטעם וההשג' והוא באמרו אשר קדשנ\"ו<sup data-n=\"9397\">85</sup> בקדושת אור מקיף כו'. ועכשיו יש בכל מעשה מצוה ענין ההגשמה מצד הכלי שהמצוה",[["9387","*76","<b>לזכך בהגשמה</b>: תיבת לזכך נרשמה ממעל לשורה. אולי מתחלה נרשם ההגשמה ותוקן בהגשמה."],["9388","76","<b>ועשיתם אתם כאילו עשאונ\"י</b>: נסמן לעיל פ' יתרו רנט, ד."],["9389","77","<b>אלה המצות אשר יעשה אותם האד\"ם</b>: חיבור שני כתובים (אלה המצות) בחוקותי כז, לד. (אשר. . האד\"ם) אחרי יח, ה. ראה גם הנסמן לעיל פ' בשלח קעה, ד."],["9390","78","<b>וגם והרחבת</b>: מתחלה נרשמה תיבת: והרחבת ואח\"כ ניתוסף ממעל לשורה תיבת: וגם. ועפ\"ז לכאו' צ\"ל: הרחבת."],["9391","79","<b>נעשה אד\"ם</b>: בראשית א, כו. וראה גם סידור שער התפלה יט, א. לעיל פ' בשלח רח, ד. וש\"נ."],["9392","80","<b>שיתא אלפי שני דהוי עלמא</b>: ראה ר\"ה לא, א. הנסמן במאמרי אדה\"א בראשית ע' נג."],["9393","81","<b>התוספת למעלה באצי'</b>: ראה פע\"ח בהקדמה. לעיל פ' בשלח קנו, ב. וש\"נ."],["9394","82","<b>בלע המות לנצח</b>: ישעי' כה, ח."],["9395","83","<b>הא\"פ. . הקו והחוט</b>: ראה גם לעיל פ' שמות כד, סע\"א. וש\"נ."],["9396","84","<b>המקיפי'. . העיגול שלמעלה מבחי' הקו</b>: ראה גם לעיל שם כט, א. לקו\"ת קרח נב, רע\"ג. דר\"מ מצות ציצית טז, א. ש\"א עט, ב ואילך."],["9397","85","<b>באמרו אשר קדשנ\"ו</b>: נוסח ברכת המצות. ראה גם לעיל פ' תצוה שנט, ד."]]],[2300550291,"נעשי' בעניני' גשמיי' מדצח\"ם דעשי' כנ\"ל, אבל לע\"ל יתברר ויזדכך הגשמת מעשה המצו' מצד בחי' אורו' המקיפי' עליונים שיבאו למטה ויתגלו ע\"י כונו' הברכו' של כל המצו' מעשיו' שעושין הצדיקי' למעלה מן הטעם כו' והוא ע\"י מס\"נ בתשובה עילא' בתחלה כו', ואזי מצחצחי' הגשמת כלי המצו' מבחוץ כי א\"מ מזכך גם חצי ההגשמה של הכלי מבחוץ ואור הפנימי שהוא כונות המצו' בהשגה וטעם יזכך הכלים של המצו' מבפנים ויבאו אז בבחי' הגילוי מן בחי' ההעלם שהם עכשיו כו' וממילא יזדכך הכלי לגמרי, וזהו מ\"ש והשביע בצחצחו' נפשך ב' צחו'<sup data-n=\"9398\">86</sup> א' מבחי' א\"מ וא' מבחי' א\"פ והנפש הוא בחי' הכלי כו' וד\"ל. וזהו כי עין בעין כו' פי' עין של בחי' א\"פ הוא עכשיו בחי' מקבל מא\"מ שמסתכל בו מלמטה למעלה כדרך כל עלול שדבוק בעילתו כו' ועין של הא\"מ הוא מסתכל מלמעלה למטה להמשיך כח לא\"פ כו', אך לע\"ל אחר שהא\"מ יזכך חיצוניו' הכלים הרי יבא גם הוא מלמטה למעלה בבחי' אור חוזר, כי כל המקיפי' שמצד ברורי רפ\"ח כו' כמו במעשה המצו' הוא בא בבחי' אור חוזר א\"כ יתחברו וישתוו בחי' א\"פ ובחי' א\"מ בהשווא' א' כו' וד\"ל. והנה כל זה מסיבת טעם הנ\"ל דא\"מ להיותו גבוה יותר יותר יוכל להשפיל א\"ע לזכך חצי הכלי החיצוניו' וע\"כ יהי' לעתיד ענין תחיית המתים דוקא ולא עכשיו כי להחיו' רוח שפלים<sup data-n=\"9399\">87</sup> כעצמו' היבישו' וכיוצא צריך שיבא האור מבחי' א\"מ היותר גבוה כו' וד\"ל.\n<b>ובכל</b> זה מובן מה שאמרו ז\"ל דלעתיד צדיקים יושבים ועטרותיהם בראשיהם<sup data-n=\"9400\">88</sup> כו' ולכאורה אינו מובן מהו ענין העטרו' וגם למה נק' עטרותיהן דמשמע שהן שלהם כו', אך הענין הוא משום דהיום לעשותם בלבד לעשו' התוספ' גילוי אורו' ולעשו' הכלים דמצו' כנ\"ל אבל גילוי אותו התוספ' בא\"פ וגילוי הא\"מ למטה אינו אלא לעתיד דוקא מצד שיבא אז הא\"מ בגילוי מפני שאז זמן כלות הברורי' דרפ\"ח כו', והוא גבוה הרבה ממה שנהנין מזיו עכשיו שחסר ב' מדרגו' הללו כנ\"ל. וזהו שלא הזכיר לשון עטרותיהם בראשיהם במאמר שאמר שהנשמו' נהנין מזיו השכינה בג\"ע כי אין להם עדיין עטרו' הללו רק לעתיד, והענין הוא שלעתיד יתגלו כל המקיפי' העליוני' הנק' עטרות וכמ\"ש בעטר\"ה שעטר\"ה לו אמו כו' ומטעם הנ\"ל. ולכך נק' עטרותיה\"ם לפי שהם שלהם שזכו <span data-k=\"pg\">תרסז</span> ּ אותם במעשה המצות במס\"נ שלמעלה מן הטעם והן באי' בבחי' או\"ח לכך עטרותיהם לשון כותרת ומקיף מפני שזהו קיבול שכרם לעתיד שהוא גבוה הרבה ממה שנהנין עכשיו בג\"ע מזיו כו', והיינו שאמר היום",[["9398","86","<b>בצחצחו'. . ב' צחו'</b>: ראה זהר ויחי רכד, ב. ע\"ח (שער עתיק) שי\"ב, פ\"ה. אוה\"ת ישעי' (נ\"ך כרך ב) ע' תתמד. בראשית (כרך ז) תתיז, ב."],["9399","87","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["9400","88","<b>דלעתיד צדיקים יושבים ועטרותיהם בראשיהם</b>: ראה ברכות יז, א. מאמרי אדה\"ז תקס\"ט ע' רלט ואילך. מאמרי אדה\"א דברים ח\"ד ע' א'תפו ואילך. ויקרא ח\"א ע' קעא."]]],[2300550318,"לעשותם ולמח\"ר דוקא לקבל שכר\"ם. וזהו שכר מצוה מצוה<sup data-n=\"9401\">89</sup> כלומר המצוה עצמה שלמעלה מן הטעם וההשגה אשר יש בה שעי\"ז דוקא מקבלי' שכרם שיהי' נגלה עליהם מאור המקיף הכללי והן ענין העטרו\"ת שבראשיהם וד\"ל.\n<b>וזהו</b> אלה פקודי המשכן כו'. פי' פקודי הוא מלשון התקשרו' כמו חייב אדם לפקו\"ד<sup data-n=\"9402\">90</sup> כו', והמצו' הרי המה בחי' התקשרו' באור המאציל להיו' על ידן נמשך ובא בחי' תוספ' גילוי אור כנ\"ל, ולהיו' כי תכלית השלימות הוא כשיתחברו בחי' א\"פ ובחי' א\"מ ממלא וסובב כנ\"ל לכך אמר פקודי המשכן התחברו' המשכן דבחי' ממלא ודבחי' סובב כו'. ומה שאמר אל\"ה מבואר הטעם למעלה דבין בתורה שהוא בחי' המדו' בפנימי' הן מספר ל\"ו דו' סדרי' נחלקי' לל\"ו מסכתו', ובין במצות שכללותם הוא רק מבחי' התכללו' מדות המלובשי' בו' סדרי' שז\"ש לך ה' הגדולה והגבורה<sup data-n=\"9403\">91</sup> כו' וכל מדה כלולה מששה כו'.\n<b>והנה</b> כל זה ברמ\"ח מ\"ע שנרמזי' בתיבת זכר\"י עם ו\"ה<sup data-n=\"9404\">92</sup> כו', ופי' זכרי הוא עד\"מ החותם שחותמין בו שמו של אדם שבהחותם אין כאן אלא רק בחי' ענין חקיקת אותיו' השם שהוא כמו רק לאות ולסימן להיו' זכרון לשמו עי\"ז, וה\"ז ע\"ד דוגמא ממה שיעשה האדם ציון כמ\"ש הציבי לך ציונים<sup data-n=\"9405\">93</sup> שהציון הוא האות והסימן למראה בלבד ואינו נעשה רק לזכרון בעלמא, כמ\"כ כתיב הציבי לך ציונים, ציונים<sup data-n=\"9406\">94</sup> כלומר סימנים להיות סימנים וציונים בלבד לגילוי אורו' העליונים והן מעשה רמ\"ח מ\"ע שנק' בחי' כלים לאורו' והן נק' ציונים לתורה שנק' אור<sup data-n=\"9407\">95</sup> כו', והיינו פי' זכרי כלומר זכרון שמות של האורו' כו' ולא גופי השמות והאורו' כו'. אבל שס\"ה ל\"ת עם י\"ה כו' נק' שמי כלומר שמו' העצמיי' של המאציל כו' ולא זכרון וציון בעלמא, והענין הוא לפי שהם בחי' המשכו' אורו' מקיפי' שבלתי מוגבלי' בכלי בבחי' ציון כו' וע\"כ א\"א שיהי' להם למטה בחי' כלי במעשה אלא רק בשב ואל תעשה בלבד והוא הלאוין דשס\"ה ל\"ת וכמבואר שם שזהו פי' בארץ לא זרועה<sup data-n=\"9408\">96</sup> כו' דהיינו בהסרת המונע בלבד כו' ע\"ש.\n<b>וביאור</b> זה הנה יובן ע\"ד דוגמא שאמרו ז\"ל סייג לחכמה שתיקה<sup data-n=\"9409\">97</sup>, פי' עד\"מ הסייג שאינו עשוי אלא לשמור מה שבתוכו ולהקיפו כו' כך השתיקה הוא כמו סייג לחכמה",[["9401","89","<b>שכר מצוה מצוה</b>: אבות פ\"ד, מ\"ב."],["9402","90","<b>חייב אדם לפקו\"ד</b>: נסמן לעיל תמד, א."],["9403","91","<b>לך ה' הגדולה והגבורה</b>: דהי\"א כט, יא."],["9404","92","<b>ברמ\"ח מ\"ע. . זכר\"י עם ו\"ה</b>: נסמן לעיל תמב, ד הערה 19."],["9405","93","<b>הציבי לך ציונים</b>: ירמי' לא, כ."],["9406","94","<b>ציונים ציונים</b>: בגוכתי\"ק באה תיבת ציונים לבסוף השורה וכן בהתחלת שורה שלאח\"ז. ואולי אחד מהם מיותר־ או כמו שנרשם בפנים בפסיק ביניהם. ובתו\"ח כאן: וגו'."],["9407","95","<b>לתורה שנק' אור</b>: משלי ו, כג."],["9408","96","<b>בארץ לא זרועה</b>: ירמי' ב, ב. ראה לעיל תמג, סע\"ג. תמו, ב."],["9409","97","<b>סייג לחכמה שתיקה</b>: אבות פ\"ג, מי\"ג. וראה גם לעיל פ' יתרו רסז, ד. וש\"נ."]]],[2300550343,"הנשפעת מלמעלה והיינו בחי' הביטול במציאו'. כי הנה יש ב' מדרגו' בחכמה, א' הנשפע מלמעלה למטה בנפש האדם המשכלת ע\"י יגיעתו בכח העיון שלו לפי ערך יגיעת עיונו כו', ויש עומק המושג שא\"א לו להגיע אליו בשום יגיעה אלא רק ע\"י בחי' הביטול במציאו' והוא הנק' שתיקה כלומר ביטול מן ההשגה הקדומה כענין מה פשפשת<sup data-n=\"9410\">98</sup> כו', וכדוגמא שמצינו בגמ' ששאלו והקשו לרב ואישתיק<sup data-n=\"9411\">99</sup> ואח\"כ השיב להם<sup data-n=\"9412\">100</sup> כמו אשתומם כשעה חדא<sup data-n=\"9413\">101</sup> כו', הרי בשתיקה זו שהיא בחי' ביטול יוכל אור השפע נשפע מכח החכמה מה שלא יגיע בכלי השגת עיון כו'. והטעם הוא לפי שא\"א לבא האור שלמעלה מן הכלי בכלי אלא רק בבחי' הביטול <span data-k=\"pg\">1336</span> ּ שהוא העדר הכלי יכול לבא, וא\"כ א\"צ המקבל ההשפעה רק לבא לבחי' שתיקה ואז ממילא נשפעת השפע ולא שיעשה דבר מה באיזה יגיעה כו', והרי ההשפעה הזאת נק' השפעה שבאה ממילא בלתי סיבת הכנת כלי המקבל רק שיהי' בבחי' ביטול בהפשטת עצמותו מכל וכל כו' וד\"ל.\n<b>וכדוגמא</b> זו היה בשעת קריעת י\"ס דכתיב ואתם תחרישון<sup data-n=\"9414\">102</sup> פי' שלא הי' מועיל צעקה בתפלה בהעלא' מ\"ן כמ\"ש מה תצעק אלי כו', לפי שהי' האור צריך לבא ממקום הגבוה ביותר שאין העלא' מ\"ן מצד הכלי מגיע לשם כלל וכמ\"ש בזוהר מה תצעק אלי בעתיקא תליא<sup data-n=\"9415\">103</sup> שהוא מקור כל המקיפי' כו'. אבל ע\"י בחי' השתיקה בלבד שיהי' בבחי' ביטול עצמותם מכל וכל יוכל לבא ממילא ומאליו כנ\"ל, וזהו ואתם תחרישו\"ן א\"צ רק לחרוש ולשתוק וה' ילחם לכם ממילא מטעם הנ\"ל. וכדוגמא מעין זה יש בכל תפלת ש\"ע שבלחש גם היום, מטעם שבש\"ע ההמשכה באה מבחי' א\"מ כו'. ועם כל זה יובן בדוגמא גם בענין הנ\"ל בשס\"ה ל\"ת דלפי ששרשם מבחי' המקיפי' שא\"א לבא בכלי ע\"כ אין הגילוי רק בבחי' הלא\"ו שהוא ההעדר כדוגמת השתיק' לחכמה כנ\"ל וע\"כ הלאו קדם שם להן כו'. וזהו שמי עם י\"ה יו\"ד בתחלה שהוא הצמצום ואח\"כ הה\"א שהוא ההתפשטו'<sup data-n=\"9416\">104</sup> כמבואר שם<sup data-n=\"9417\">105</sup>, ובהן זה שאחר הלאו ג\"כ אינו בחי' כלי אלא שע\"י הסרת המונע בלבד הוא שיוכל לבא לידי גילוי אבל הגילוי אינו אלא לעתיד וכנ\"ל דהיינו למחר לקבל שכרם, ולכך גם הל\"ת נק' ציוני' לבחי' א\"מ כו' שכללו' המצו' מ\"ע ומל\"ת נק' ציו\"ן<sup data-n=\"9418\">106</sup> כידוע ועל כללותם אמרו היום לעשותם ולמחר דוקא לקבל שכרם מטעם הנ\"ל וד\"ל.",[["9410","98","<b>מה פשפשת</b>: זהר בהקדמה א, ב."],["9411","99","<b>ששאלו והקשו לרב ואישתיק</b>: ביצה ו, א. ראה לעיל פ' בא קכט, ב. וש\"נ. מאמרי אדה\"א בראשית ס\"ע צד ואילך. וש\"נ."],["9412","100","<b>ואח\"כ השיב להם</b>: ועד\"ז מובא במאמרי אדה\"ז הקצרים ע' רמח [אלא ששם נדפס: ואח\"כ השיג להם. ולכאו' צ\"ל: השיב]. ראה שברי לוחות להרמ\"ע מפאנו (ירושלים תשמ\"ז טו, ב ד\"ה ואשכחן): ואע\"ג דשתיק להו בקהל. . דהדר פריק להו בלחישה."],["9413","101","<b>אשתומם כשעה חדא</b>: דניאל ד, טז. שבת מז, א. ראה סידור שער נפ\"א צב, ג. שע\"ת מד, ב. מאמרי אדה\"א דברים ח\"ד ע' א'תט. וש\"נ."],["9414","102","<b>ואתם תחרישון</b>: בשלח יד, יד. ראה גם לעיל פ' בשלח קנז, ב."],["9415","103","<b>מה תצעק אלי. . בעתיקא תליא</b>: בשלח יד, טו. זהר בשלח מח, א. נב, ב. ראה גם לעיל פ' בשלח קצג, ד."],["9416","104","<b>יו\"ד. . הצמצום. . הה\"א שהוא ההתפשטו'</b>: ראה אגה\"ת פ\"ד."],["9417","105","<b>כמבואר שם</b>: אולי הכוונה ללעיל תמג, ב ואילך."],["9418","106","<b>שכללו' המצו' מ\"ע ומל\"ת נק' ציו\"ן</b>: ראה גם ספרי ורש\"י עקב יא, יח. סידור שער החנוכה רפ, ג. שערי אורה לא, ב ואילך."]]],[2300550366,"<b>משכן</b> העדות כו'. הנה שרש ענין ששם עלו שבטים<sup data-n=\"9419\">107</sup> שבטי י \"ה להודו\"ת לשם ה' כו' יובן בהקדים ענין א' הידוע שיש כל בחי' המדו' הנ\"ל בפי' אל\"ה גם בבחי' הכת\"ר שלמעלה מן האצילו' והן הנק' בזוהר בשם טורי חשוכא<sup data-n=\"9420\">108</sup> וכמ\"ש ישת חושך סתרו<sup data-n=\"9421\">109</sup> והם הנק' בחי' אהבה רבה<sup data-n=\"9422\">110</sup> וכיוצא, וזהו ששם עלו שבטים שעלו המדו' הנ\"ל בבחי' כתר עליון ונק' שם ימי קדם<sup data-n=\"9423\">111</sup> כו', וידוע שבחי' הכת\"ר הוא מובדל ומרומם בערך מכל הנאצלי' מאתו כי הוא נק' בחי' ממוצע<sup data-n=\"9424\">112</sup> בין עצמו' אור א\"ס לנאצלי' כו'. וזהו מ\"ש בי\"ג מדה\"ר ויקרא הוי' הוי' ופסיק טעמא בנייהו<sup data-n=\"9425\">113</sup> לפי שהוי' הא' הוא בבחי' הכתר היו\"ד בחכמה שבכתר כו' והוי' השני' הוא הארו' והמשכו' י\"ג מדו' באצי' ואין ערך ביניהם לכך פסיק טעמא ולכך נק' חושך סתרו, וגם כשיורד ונמשך להיו' בבחי' מקיף לנאצלי' הוא בבחי' ירידה וכמ\"ש המשפילי לראו' בשמים<sup data-n=\"9426\">114</sup> כו' פי' גם בשמים להיו' בחי' מקיף אעפ\"כ המשפילי כו'. והנה להיות כן א\"א להגיע לשם בבחי' השגה ולהמשיך משם כי פסיק טעמא כו' אלא רק בבחי' הודאה בלבד, כי הענין של הודאה הרי הוא מרחוק כמו אדם מפני שאינו יכול לעמוד על עוצם גדולת ורוממו' המלך אז יודה לו בהודאה בלבד כלומר מכיר אני רק הפלאת ערכך שאין זה מערכי כלל ויותר לא אשיג בהיותו מופלא הרבה בערך כו'. והגם שבינה עד הוד אתפשטת<sup data-n=\"9427\">115</sup> בבחי' השגה, אבל בבחי' <span data-k=\"pg\">תרסח</span> ּ ההודאה עצמה נגמר וכלה ההשגה כנרא' בחוש שדבר שאינו מבין עומקו יודה בהודאה בלבד דהיינו שמודה על האמת מצד הפלאת השכל ממנו אבל לא מצד ההשגה וההבנה בו כו', ונמצא ההודאה לא שייך אלא בדבר המופלא הימנו והוא למעלה בחי' הכתר דנק' אמון<sup data-n=\"9428\">117</sup> מופלא<sup data-n=\"9429\">116</sup> וכמ\"ש עושה פל\"א<sup data-n=\"9430\">118</sup> כו' ודוקא בחי' ההודא\"ה יגיע אליו אבל לא בחי' הברכה. כי הברכה היא ענין קבלת שפע ההמשכה מן ההעלם לגילוי שזהו ע\"י השגה דוקא כשמגיע לשם וכמאמר איהו ברו\"ך ואיהי ברכ\"ה<sup data-n=\"9431\">119</sup> כו' שהוא בבחי' משפיע ומקבל שהמקבל משיג ההשפעה כו' וזהו מ\"ש ברכת ה' היא תעשיר<sup data-n=\"9432\">120</sup> ממש וכו', אבל בבחי' הכתר הנק' פל\"א וכמ\"ש ישת חושך סתרו אחר שנק' סתר ופלא אין הברכ\"ה מגיע לקבל משם אלא רק בבחי' ההודאה יכולי' להגיע לשם כנ\"ל וד\"ל. וזהו ששם עלו שבטי' כו' להודות לשם הוי' פי' לשם",[["9419","107","<b>ששם עלו שבטים</b>: תהלים קכב, ד."],["9420","108","<b>המדו'. . הכת\"ר. . טורי חשוכא</b>: ראה זהר פינחס רמט, ב. מאמרי אדה\"א שמות ח\"א ע' פח. וש\"נ. שעה\"י קכז, ב. ובהערה 31. לעיל פ' תצוה שסא, א."],["9421","109","<b>ישת חושך סתרו</b>: תהלים יח, יב."],["9422","110","<b>טורי חשוכא. . אהבה רבה</b>: ראה גם לעיל פ' תצוה שסא, ב."],["9423","111","<b>המדו'. . כתר. . ימי קדם</b>: ראה גם לעיל פ' בא צ, ג הערה 178."],["9424","112","<b>הכת\"ר. . ממוצע</b>: נסמן לעיל תמז, ג."],["9425","113","<b>ויקרא הוי' הוי' ופסיק טעמא בנייהו</b>: תשא לד, ו. ראה זהר (אד\"ר) נשא קלח, רע\"א. לעיל פ' בשלח קנז, ב הערה 361."],["9426","114","<b>המשפילי לראו' בשמים</b>: תהלים קיג, ו."],["9427","115","<b>שבינה עד הוד אתפשטת</b>: ראה זהר (רע\"מ) פינחס רנג, ב. לעיל פ' שמות טו, ג הערה 669."],["9428","117","<b>אמון מופלא</b>: ראה תו\"א לב, א ובהנסמן במ\"מ לשם. לעיל פ' בשלח קעט, ב הערה 680."],["9429","116","<b>הכתר דנק' אמון מופלא</b>: ראה פרדס (שער עה\"כ) מערכת אמון."],["9430","118","<b>הכתר. . עושה פל\"א</b>: בשלח טו, יא. ראה תיקונים לז\"ח צח, ד."],["9431","119","<b>איהו ברו\"ך ואיהי ברכ\"ה</b>: זהר תרומה קסב, א. (רע\"מ) ואתחנן רסד, ב."],["9432","120","<b>ברכת ה' היא תעשיר</b>: משלי י, כב."]]],[2300550386,"הוי' דכתר שנק' פלא וסתר כנ\"ל דפסיק טעמא כו' עלו שבטי' שם רק בבחי' ההודא\"ה בלבד מטעם הנ\"ל.\n<b>וזהו</b> מה שאמר משכן העדו\"ת כמ\"ש עדות לישראל כו' והנגלו' א\"צ עדות רק הנסתר והפלא והוא בחי' הכתר והיינו שהוא מלשון עדי וקישוט וכמ\"ש בעדי עדיים<sup data-n=\"9433\">121</sup> מפני שהן ג' כתרים בכלל, כי הנה ידוע שיש ג' קוין באצי' חח\"נ בג\"ה דת\"י<sup data-n=\"9434\">122</sup> וכאו\"א יש לו שרש באור הכתר שעל גביהן דהיינו בטורא דחשוכא הנ\"ל, וג' הקוין ידוע שהוא תורה ועבודה וגמ\"ח<sup data-n=\"9435\">123</sup> לוים בעבודה בשיר<sup data-n=\"9436\">124</sup> וגמ\"ח החסד שבקו הימין הוא בכהנים<sup data-n=\"9437\">125</sup> והתורה קו האמצעי<sup data-n=\"9438\">126</sup> שהוא בחי' ישראל<sup data-n=\"9439\">127</sup> וכמ\"ש ותורה שם בישראל<sup data-n=\"9440\">128</sup> ונק' עמודא דאמצעותא<sup data-n=\"9441\">129</sup> בריח התיכון<sup data-n=\"9442\">130</sup> כו', וג' הכתרים שע\"ג הן הנק' במשנה כתר כהונה<sup data-n=\"9443\">131</sup> וכתר תורה וכתר מלכו' כתר כהונה בקו הימין וכתר מלכו' בקו השמאל וכתר תורה בקו האמצעי. ושרש ג' הכתרים האלה המה כלולי' באור הכתר הכללי שעל גבי הקוין כו' והוא מ\"ש ותבואי בעדי עדיים ג' כתרים הללו אחר שאמר ותרבי ותגדלי<sup data-n=\"9444\">132</sup> במוחי' דגדלו' שני<sup data-n=\"9445\">133</sup> בזמן מ\"ת כו', והיינו ענין משכן העדות מג' הכתרים הללו והן באי' ונמשכי' ע\"י השס\"ה ל\"ת דוקא והוא בהעדר וביטול בלבד כנ\"ל הטעם, וזהו להודו' לשם הוי' כו' בבחי' ההודא\"ה בלבד. והיינו שאמרו ז\"ל מאן דלא כרע במודים<sup data-n=\"9446\">134</sup> אינו קם בתחיית המתים כי לעתיד יתגלה שרש השס\"ה ל\"ת שהי' בשב ואל תעש' בלבד שעי\"ז נמשך אור הכתר בלאו שקודם להן כנ\"ל, והיינו ענין מה שצדיקים יושבי' ועטרותיה\"ם בראשיהם כו' וכנ\"ל, ולהיו' כי א\"א להגיע לקבל משם רק בבחי' ההודא\"ה בלבד כנ\"ל ע\"כ מאן דלא כרע במודי\"ם בבחי' ההודא\"ה עכשיו אין לו דבר שיוכל לעתיד לקבל בו אור הכתר להיות לו לעטרה בראש כו', ומזה הטעם עצמו הוא שאינו קם בתח\"ה כי תח\"ה יהי' מאותו האור דוקא כנ\"ל שכדי להחיו' המתים שהוא תכלית היריד' צריך לבא האור ממקום גבוה וכמ\"ש כי טל אורו' כו' וד\"ל. ונמצא הכל ענין א' ענין מה שעטרותיה\"ם בראשיהם וענין התחיי' לעתיד ומה שכל זה מסיבת מעשה המצוה שירדה בלבושי' גשמיים דוקא כנ\"ל שזהו ענין אמרם היום לעשותם ולמחר לקבל שכרם כו' וד\"ל.",[["9433","121","<b>בעדי עדיים</b>: יחזקאל טז, ז."],["9434","122","<b>חח\"נ בג\"ה דת\"י</b>: נסמן לעיל פ' יתרו רסט, ג הערה 19."],["9435","123","<b>חח\"נ בג\"ה דת\"י. . תורה ועבודה וגמ\"ח</b>: ראה גם שערי אורה ל, ב ובהערה 28. שע\"ת לז, ד. מאמרי אדה\"א שמות ח\"ב ע' תרלז. ויקרא ח\"א ע' קיח. ח\"ב ע' תרצט. דברים ח\"ב ע' שצח וע' תרעז. תו\"ח לך פה, א."],["9436","124","<b>לוים בעבודה בשיר</b>: סוף תמיד. ראה גם לעיל פ' בא קו, ד. וש\"נ."],["9437","125","<b>החסד. . בכהנים</b>: ראה זהר נשא קמה, ב. צו כז, א. לעיל פ' וארא פה, ד הערה 866."],["9438","126","<b>והתורה קו האמצעי</b>: ראה גם לעיל פ' תרומה שטז, ב ובהנסמן שם."],["9439","127","<b>קו האמצעי. . ישראל</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רנב."],["9440","128","<b>וכמ\"ש ותורה שם בישראל</b>: תהלים עח, ה."],["9441","129","<b>קו האמצעי. . עמודא דאמצעותא</b>: ראה זהר (רע\"מ) תשא קפז, ב. ביאוה\"ז שם נד, ב."],["9442","130","<b>קו האמצעי. . בריח התיכון</b>: ראה ביאוה\"ז שם. לעיל פ' תרומה שטז, ב. וש\"נ."],["9443","131","<b>וג' הכתרים. . כתר כהונה</b>: אבות פ\"ד, מי\"ג. ראה גם לעיל תמז, ד."],["9444","132","<b>ותבואי בעדי עדיים. . ותרבי ותגדלי</b>: יחזקאל טז, ז."],["9445","133","<b>דגדלו' שני</b>: ראה גם לעיל פ' בשלח רא, ד. פ' בא קכח, סע\"ד. קכט, ב."],["9446","134","<b>מאן דלא כרע במודים</b>: ראה ב\"ק טז, סע\"א. לעיל פ' וארא עד, א. וש\"נ."]]],[2300550403,"<b>אשר</b> פקד עפ\"י משה כו'. הנה אמרו ז\"ל אנכי ולא יהי' לך מפי הגבורה נאמרו<sup data-n=\"9447\">135</sup> כו' ולא <span data-k=\"pg\">1338</span> ּ מפי משה כשאר הדברו' דכתיב משה ידבר<sup data-n=\"9448\">136</sup> כו', דהנה לכאורה אינו מובן לשון מפי הגבורה דוקא הל\"ל מפי הקדב\"ה או מפי המקום וכיוצא כו'. אך הענין הוא מובן עפ\"י הנ\"ל דמבחי' אור הכתר א\"א לבא האור כ\"א בבחי' הביטול והוא הלאו שקודם להן כו' וכנ\"ל כי מלמעלה מעלה הלאו קודם להן, היינו שבתחלה באי' בחי' גבורו' ואח\"כ בחי' חסדי' וכמ\"ש ישת חושך סתרו שבתחלה צמצום<sup data-n=\"9449\">137</sup> הנק' חושך ואח\"כ מאיר האור ממילא והארת האור הוא רק ע\"י הצמצום בלבד, כי מה שנתצמצם בזה בלבד גילוי אורו כי בלאו בלבד יוכל לבא כנ\"ל. משא\"כ למטה בבחי' אצי' החסדי' קודמי' לבא לבחי' הגבורו' כי יוכל האור לבא בבחי' כלי והיינו ההן שקדם ללאו למטה כו', וכמבואר בע\"ח דבאור הכתר הגבורו' והצמצום קודמי'<sup data-n=\"9450\">138</sup> כו'. וזהו שאמר אנכי ולא יהי' לך כו' פי' אנכי הוא מי שאנכי<sup data-n=\"9451\">139</sup> דלא ידע לי' בר איהו<sup data-n=\"9452\">140</sup> כו' ולית מחשבה תפיס' בי' כלל<sup data-n=\"9453\">141</sup> רק בבחי' הלאו בלבד הוא שיכול להתגלו' והוא רק בהסרת ההיפך בלבד והיינו שלא יהי' לך אלקי' אחרי' כו' ולכך אנכי ולא יהי' לך בדיבור א' נאמרו<sup data-n=\"9454\">*142</sup> כי הגילוי דאנכי אינו אלא רק במה שלא יהי' לך כו' ונמצא הכל דיבור א' בלבד וד\"ל.\n<b>וזהו</b> שאמרו ז\"ל אנכי ולא יהי' לך מפי הגבור\"ה כי מפני בחי' הגבורו' שקדמו לחסדי' בכתר לבא לכך הם באו מפי הגבור\"ה דוקא והיינו מבחי' הגבור\"ה שבכת\"ר כנ\"ל, ומלבד זה הטעם הנה לא יוכלו ב' הדיברו' הללו לבא מפי משה כשאר הדברו' אלא מפי עצמו' אור א\"ס, דהנה במשה נא' משה ידבר והאלקי' יעננו בקול בקולו של משה<sup data-n=\"9455\">142</sup> כו' שהי' בחי' ממוצע<sup data-n=\"9456\">143</sup> וכמו שאמר משה ע\"ע אנכי עומד בין ה' וביניכם<sup data-n=\"9457\">144</sup> כו' שהי' עומד בבחי' ממוצע בין שם הוי' שבכת\"ר ובין שם הוי' ששרש כללו' נ\"י שם. ואע\"פ דפסיק טעמא בנייהו כמש\"ל, מ\"מ ע\"י משה הורד להם האור מהוי' שבכתר כי הי' בחי' דע\"ת<sup data-n=\"9458\">145</sup> שהוא בחי' ממוצע לחבר העליון בתחתון כידוע, וזהו דוקא בשאר הדברו' אבל אנכי ולא יהי' לך שהן בעצמו' הכת\"ר אנכי מי",[["9447","135","<b>אנכי. . מפי הגבורה נאמרו</b>: ראה מכות כד, א. לעיל פ' וארא סט, א. וש\"נ."],["9448","136","<b>משה ידבר</b>: יתרו יט, יט."],["9449","137","<b>ישת חושך סתרו. . צמצום</b>: ראה גם לעיל פ' בא קכג, ג ובהערה 445."],["9450","138","<b>דבאור הכתר הגבורו' והצמצום קודמי'</b>: ראה ע\"ח (שער או\"א) שי\"ד, פ\"א. רמ\"ז לזהר בהקדמה א, א (ה, ב בדפי הספר). ביאוה\"ז בראשית א, סע\"ג."],["9451","139","<b>אנכי. . מי שאנכי</b>: נסמן לעיל פ' יתרו רנד, ג."],["9452","140","<b>דלא ידע לי' בר איהו</b>: נסמן לעיל פ' ויקהל שפח, א."],["9453","141","<b>ולית מחשבה תפיס' בי' כלל</b>: ראה ת\"ז בהקדמה (יז, א)."],["9454","*142","<b>אנכי ולא יהי' לך בדיבור א' נאמרו</b>: נסמן לעיל פ' יתרו רסד, א. ראה גם לקמן תנו, ד."],["9455","142","<b>בקולו של משה</b>: ברכות מה, א."],["9456","143","<b>משה. . ממוצע</b>: ראה לעיל פ' תצוה שכג, ג הערה 196."],["9457","144","<b>אנכי עומד בין ה' וביניכם</b>: ואתחנן ה, ה."],["9458","145","<b>משה. . דע\"ת</b>: ראה תניא פמ\"ב. לעיל פ' וארא פה, ד הערה 856."]]],[2300550420,"שאנכי כו' לא יוכלו לבא ע\"י ממוצע כ\"א מפי הגבורה עצמו והוא ע\"י בחי' הגבורה שבכתר דהיינו הלא\"ו שקודם להן כו' ששרש שס\"ה ל\"ת נמשך משם כנ\"ל וד\"ל.\n<b>וזהו</b> משכן העדו' אשר פקד עפ\"י מש\"ה דהנה הוא בחי' הדע\"ת הממוצע כמ\"ש בין ה' וביניכם, ואמנם במשכן העדו' שהוא היחוד עליון שבכת\"ר שמשם נמשך העדו\"ת לישראל בעד\"י עדיי\"ם ג' כתרים כנ\"ל פקד עפ\"י מש\"ה באופן אחר, ולא שהי' בחי' ממוצע אחר שלא יוכלו להגיע לשם כו' אלא במדרגת בחי' הביטול במציאו' שהי' במשה והוא בחי' מ\"ה שבחכמ\"ה כמ\"ש ונחנו מ\"ה<sup data-n=\"9459\">146</sup> כו' עי\"ז עשה יחוד העליון הזה שבכת\"ר כי אינו מתגלה רק ע\"י ביטו\"ל, ועי\"ז נפקד משכן העדו' בבחי' יחוד והתקשרו' למטה כמ\"ש ותבואי בעדי עדיים והוא הנק' כת\"ר תורה. ומה שנא' תורה צוה לנו משה<sup data-n=\"9460\">147</sup> כו' היינו בשאר הדברו' אבל בלאוין דשס\"ה בפרט ובלאו דלא יהי' לך אלקי' אחרי' כו' בכלל הוא שנא' מפי הגבורה דוקא אלא שפק\"ד עפ\"י משה שהי' בחי' מרכב\"ה לזה בלבד והוא בבחי' הביטול דמ\"ה כו' וד\"ל.\n<span data-k=\"pg\">תרסט</span> ּ<b>עבודת</b> הלוים ביד איתמר כו'. הנה בלוים נא' והקימו את המשכן<sup data-n=\"9461\">148</sup> כו' ונשאו את היריעות<sup data-n=\"9462\">149</sup> כו' לפי שהם מבחי' הגבורו'<sup data-n=\"9463\">150</sup> שמעלים כל דבר למעלה ע\"י בחי' רשפי אש שלהבת אהבה כו', והיינו מפני שהיה עיקר עבודתם בשיר וכמאמר כל בעלי השיר יוצאי' בשיר<sup data-n=\"9464\">151</sup> שעליות המלאכים מהיכל להיכל יותר גבוה הוא ע\"י השיר והן המלאכי' העליונים שנק' בעלי השיר<sup data-n=\"9465\">152</sup> וכמבואר בהיכלו' דפ' פקודי<sup data-n=\"9466\">153</sup>. וסיבת ענין העליו' שיכולי' לעלות מהיכל להיכל כו' הוא לפי שהן בעלי שש כנפים<sup data-n=\"9467\">154</sup> שהוא בחי' שם מ\"ב<sup data-n=\"9468\">155</sup> שבו כל העליו'<sup data-n=\"9469\">156</sup> כידוע והיינו מ\"ש בהם בשתים יכסה פניו כו' ובשתים יעופף<sup data-n=\"9470\">157</sup> מלמטה למעלה מעלה מהיכל להיכל כו' וד\"ל. ובפסוקי דזמרה שלפני ק\"ש הוא עבודת הלוים הזאת בשיר ואז יכול להיו' יחוד עליון דב' משכנות הנ\"ל, והוא הכונות שבתיבו' הוי' אלקינו ה' אחד שהוא יחוד או\"א<sup data-n=\"9471\">158</sup> ויחוד זו\"נ<sup data-n=\"9472\">159</sup> כידוע בפי' א\"ח דלי\"ת<sup data-n=\"9473\">160</sup> כו'",[["9459","146","<b>ונחנו מ\"ה</b>: בשלח טז, ז. ח. ראה גם לעיל פ' שמות מג, א. וש\"נ."],["9460","147","<b>תורה צוה לנו משה</b>: ברכה לג, ד."],["9461","148","<b>והקימו את המשכן</b>: בהעלותך י, כא."],["9462","149","<b>ונשאו את היריעות</b>: נשא ד, כה [ושם: יריעת]."],["9463","150","<b>בלוים. . הגבורו'</b>: ראה גם לעיל פ' וארא פה, ד הערה 867."],["9464","151","<b>כל בעלי השיר יוצאי' בשיר</b>: שבת נא, ב (במשנה)."],["9465","152","<b>המלאכי'. . בעלי השיר</b>: ראה גם זהר אחרי סד, ב: מארי שירתא."],["9466","153","<b>כל בעלי השיר. . המלאכי' העליונים. . בהיכלו' דפ' פקודי</b>: ראה גם בענין שירה שם רמז, א. ב. רמט, ב. רנ, א. וראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' רל [הנחת הר\"מ בן כ\"ק אדה\"ז]. מארז\"ל ע' קכ. סידור שער החנוכה ערה, ד. לקו\"ת ברכה צח, א (ובכל הנ\"ל בשם הה\"מ). מאמרי אדה\"ז תקס\"ו ע' ק [הנחת הר\"מ — מקביל לסידור ולקו\"ת הנ\"ל]. תו\"א בראשית ז, ג. שע\"ת מד, ג. פט, א ובהערה 1. מאמרי אדה\"א דברים ח\"ב ע' תקפב, וש\"נ. דרושי חתונה ח\"ב ר\"ע תקיח."],["9467","154","<b>המלאכי'. . שש כנפים</b>: נסמן בהערה 157."],["9468","155","<b>שם מ\"ב</b>: נסמן לעיל פ' משפטים רצא, ד."],["9469","156","<b>שם מ\"ב שבו כל העליו'</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשטו ואילך ובהנסמן במ\"מ לשם."],["9470","157","<b>בשתים. . ובשתים יעופף</b>: ישעי' ו, ב."],["9471","158","<b>ה' אלקינו. . יחוד או\"א</b>: נסמן לעיל תמז, סע\"ד ואילך."],["9472","159","<b>ה' אחד. . ויחוד זו\"נ</b>: ראה גם זהר ואתחנן רסג, א. סידור שער השמים — של\"ה — במקומו. לקו\"ת שה\"ש כט, א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשיד. דרך מצותיך קכב, א. מאמרי אדה\"א בראשית ע' שפ. שעה\"י קכח, א."],["9473","160","<b>אחד. . א\"ח דלי\"ת</b>: ראה פע\"ח (שער הק\"ש) ש\"ח, פי\"ב [וכן צ\"ל במאמרי אדה\"א שמות ח\"ב ע' תסב]. שו\"ע אדה\"ז הל' ק\"ש סס\"א, ס\"ו [וכן צ\"ל בהנרשם בסמוך]. מאמרי אדה\"א דברים ח\"ב ס\"ע תקסב ואילך."]]],[2300550436,"וד\"ל. והנה ואהבת<sup data-n=\"9474\">161</sup> הוא בחי' אהבה רבה שבבחי' הרצון כי שרשו לשון אב\"ה<sup data-n=\"9475\">162</sup> כידוע, ומשמעו' הענין שמסיבת ואהבת יכול להיו' והיו הדברי' האלה<sup data-n=\"9476\">163</sup> אשר אנכ\"י<sup data-n=\"9477\">164</sup> כו' עד ודברת בם<sup data-n=\"9478\">165</sup> שהוא בחי' הביטול הנ\"ל בענין אשר פק\"ד עפ\"י משה בחי' מ\"ה, והיינו ענין איתמר כמו אז נדברו<sup data-n=\"9479\">167</sup> שהדיבור ממילא<sup data-n=\"9480\">166</sup> בא והוא אינו כלי רק שלא להיו' מסתיר ומונע כענין השתיקה הנ\"ל וכמ\"ש במ\"א שזהו מ\"ש ודבר\"י אשר שמתי<sup data-n=\"9481\">168</sup> כו'. וזהו ביד איתמר בן אהרן הכהן, פי' איתמר הוא בחי' ביטול עד שהדיבור נדבר בו ממילא כנ\"ל וזה בא מחמת אהבה רבה שברצון הנק' אהר\"ן, כידוע בפי' אהר\"ן שהוא ה\"ר הה\"ר ונו\"ן<sup data-n=\"9482\">169</sup> הוא המשכת א\"ר זו למטה כמ\"ש כשמן הטוב<sup data-n=\"9483\">170</sup> כו' יורד על הזקן זקן אהרן שיורד עפ\"י מדותי\"ו וד\"ל. ולכך נק' איתמר בן אהר\"ן הכהן מפני שנולד הביטול מפני הא\"ר כו', ויש אהבה זוטא שלמטה מן השכל שנולדה מן השכל ואז היא הכנה לבא למדרגת הביטול הנ\"ל וזהו ענין הלוך ונסוע הנגב\"ה הנ\"ל, ומפני שעבודת הלוים בשיר לבא לבחי' ביטול הוא והיינו שע\"י איתמ\"ר דוקא היה אופן העבוד\"ה של הלוי\"ם במסעו\"ת שלהם כו' וד\"ל.",[["9474","161","<b>ואהבת</b>: ואתחנן ו, ה."],["9475","162","<b>אהבה. . שרשו לשון אב\"ה</b>: ראה גם לעיל פ' בשלח קצט, א. וש\"נ."],["9476","163","<b>והיו הדברים האלה</b>: ואתחנן ו, ו."],["9477","164","<b>אשר אנכ\"י</b>: תיבות אלו נכתבו בין השיטין וכנראה שמקומם כאן."],["9478","165","<b>ודברת בם</b>: ואתחנן ו, ז."],["9479","167","<b>אז נדברו</b>: מלאכי ג, טז."],["9480","166","<b>איתמר. . ממילא</b>: נסמן לעיל תמה, ד הערה 147."],["9481","168","<b>ודבר\"י אשר שמתי</b>: ישעי' נט, כא. ראה גם לעיל פ' תצוה שע, ב."],["9482","169","<b>אהר\"ן שהוא ה\"ר הה\"ר ונו\"ן</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' קכז ואילך. לעיל פ' וארא עח, ב. וש\"נ."],["9483","170","<b>כשמן הטוב</b>: תהלים קלג, ב."]]],[2300550071,"<b>בעזר\"ה פ' פקודי פה ק' וויטעפסק תקפ\"ד</b>\n<span data-k=\"pg\">1296</span> ּ<b>אלה</b> פקודי המשכן<sup data-n=\"9484\">1</sup> משכן העדות אשר פקד עפ\"י משה עבודת הלוים<sup data-n=\"9485\">2</sup> כו', הנה הדקדוקים <span data-k=\"pg\">תרמח</span> ּ בזה רבים, א' מ\"ש אלה לשון רבים. ועוד מ\"ש בכפל ב\"פ משכן, א' פקודי המשכן וכפל עוד לומר משכן העדות. ועוד מ\"ש במשכן הראשון משכן סתם ובמשכן הב' אמר משכן העדות. ועוד מ\"ש אשר פוקד ע\"פ משה דוקא עבודת הלוים כו'. ועוד מה שקוראו משכן ומשכן העדות ולפעמים קוראו מקדש כמ\"ש ועשו לי מקדש ושכנתי בתוכם<sup data-n=\"9486\">3</sup>. אך הנה טעם קריאת שם משכן ידוע שהוא ע\"ש השראת",[["9484","1","<b>אלה פקודי המשכן</b>: מיוסד על ד\"ה זה משנת תקס\"ו שנדפס לעיל תמב, ג. ראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["9485","2","<b>אלה פקודי. . עבודת הלוים</b>: פקודי לח, כא."],["9486","3","<b>ועשו לי מקדש ושכנתי בתוכם</b>: תרומה כה, ח."]]],[2300550103,"גילוי שכינה כמ\"ש ושכנתי בתוכם שזהו בחי' מל' דאצי' הנק' שכינה<sup data-n=\"9487\">4</sup> כידוע ששורה בהיכל ק\"ק העליון דבריא' ויורד ושוכן למטה במשכן, וזהו שנק' משכן העדות כמ\"ש ונועדתי לך שמה<sup data-n=\"9488\">5</sup> ודברתי אתך כו' שזהו מבין ב' הכרובים שצמצם שכינתו שם בין ב' בדי הארון<sup data-n=\"9489\">6</sup> וזהו שנק' ארון העדות<sup data-n=\"9490\">7</sup> כידוע, ולזה הטעם נק' שכינה מפני ששוכן הוא ית' למטה בתחתונים כמ\"ש שנתאוה להיות לו דירה למטה בתחתונים<sup data-n=\"9491\">8</sup> דוקא. והנה מ\"ש ושכנתי בתוכם היינו בכנ\"י וזהו דוקא כשעשו מקדש ומשכן אז ושכנתי בתוכם, והענין הוא דתומ\"צ שישראל עושין הן בחי' כלים מכלים שונים לגילוי אור השראת אוא\"ס ב\"ה כמו בכלים שבמשכן ממש וזהו עיקר ענין דירה בתחתונים שיהי' השראת אור רצה\"ע וחכמתו בתו\"מ בפו\"מ אך אין השראה זאת כ\"א כשעשו לי מקדש ומשכן דוקא אז ושכנתי בתו\"מ שלהם כו'.\n<b>ולהבין</b> זה הנה תחלה י\"ל בענין עיקר<sup data-n=\"9492\">9</sup> דירה בתחתונים בין בתו\"מ ש[ה]אדם עושה בגשמיות ובין בגילוי אור השכינה במשכן במקום גשמי איך יתכן שיהי' הוא ית' נתפס בגדר מקום גשמי, שהרי הוא למעלה מבחי' מקום שהרי אמר השמים כסאי כו' איזה בית אשר תבנו לי<sup data-n=\"9493\">10</sup> כו' וגם השמים ושה\"ש לא יכלכלוהו<sup data-n=\"9494\">11</sup> כו'<sup data-n=\"9495\">12</sup> וכמא' הוא מקומו ש\"ע<sup data-n=\"9496\">13</sup> ואין העולם מקומו וכמ\"ש ברוך המקום<sup data-n=\"9497\">14</sup> שיהי' נמשך בבחי' מקום כו' ואיך יהי' נתפס בגדר מקום גשמי [כו']. וגם אם לאחר הצמצום וההסתר להיות בבחי' מקום וזמן שנק' עש\"נ<sup data-n=\"9498\">15</sup> הרי בחי' צמצום אינו מסתיר לפניו כלל וע\"כ אין שינוי לפניו בין קודם הבריאה לאח\"כ כלל, שלאחר הבריאה הארת אוא\"ס שבאצי' מאיר למעלה ולמטה בשוה בלי חילוק מדרגות כלל כמו שהי' קודם הבריאה ממש וכמ\"ש אני הוי' לא שניתי<sup data-n=\"9499\">16</sup> כו' לפי שאין כל ההשתל' דבי\"ע תופס מקום כלל, וא\"כ איך שייך ל[שון] השראת [ה]שכינה במקום מיוחד דוקא דמאחר ששוה מעלה ומטה הרי אמר דאת השמים ואת הארץ אני מלא<sup data-n=\"9500\">17</sup> דלית אתר פנוי מיני'<sup data-n=\"9501\">18</sup> בהשוואה א' מטעם זה, וזהו בבחי' סוכ\"ע שלמעלה מכל ההשתל' שמקיף לכל ההשתל' בשוה כנ\"ל לפי שאין שינוי לפניו [כלל] כו'<sup data-n=\"9502\">19</sup>. ואף גם בבחי' כח [ה]אלקי שמלובש בעולמות בבחי' [ה]השתל' אחר הצמצום הרי א' דמכה\"כ זיו יקרי'<sup data-n=\"9503\">20</sup> שנק' ממכ\"ע [מ]ראש כל המדרגו' עד סוף",[["9487","4","<b>מל' דאצי' הנק' שכינה</b>: ראה תניא רפנ\"ב. הנסמן לעיל פ' שמות א, ד."],["9488","5","<b>ונועדתי לך שמה</b>: תרומה כה, כב [ושם: שם — ראה גם לקו\"ת נשא כד, ב. מאמרי אדה\"ז תקע\"א ע' צו]."],["9489","6","<b>שצמצם שכינתו שם בין ב' בדי הארון</b>: נסמן לעיל פ' תרומה שטו, ג."],["9490","7","<b>ארון העדות</b>: תרומה שם."],["9491","8","<b>שנתאוה. . למטה </b>[חט: ליתא]<b> בתחתונים</b>: ראה תניא רפל\"ו. לעיל פ' וארא ע, ג הערה 67."],["9492","9","<b>בענין עיקר</b>: אחט: בעיקר ענין."],["9493","10","<b>השמים כסאי. . תבנו לי</b>: ישעי' סו, א."],["9494","11","<b>השמים ושה\"ש לא יכלכלוהו</b>: מל\"א ח, כז [ושם: יכלכלוך — נסמן לעיל פ' בשלח רלד, ב הערה 792]."],["9495","12","<b>כו'</b>: חט: ליתא."],["9496","13","<b>הוא מקומו ש\"ע</b>: ראה ב\"ר פס\"ח, ט. תו\"ח בראשית מג, א הערה 2."],["9497","14","<b>ברוך המקום</b>: מדות בסופה. הגש\"פ (פסקא זו)."],["9498","15","<b>עש\"נ</b>: עולם שנה נפש."],["9499","16","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["9500","17","<b>דאת השמים. . אני מלא</b>: ירמי' כג, כד."],["9501","18","<b>דלית אתר פנוי מיני'</b>: נסמן לעיל תמב, ג. הערה 8."],["9502","19","<b>כו'</b>: חט: כנ\"ל."],["9503","20","<b>דמכה\"כ זיו יקרי'</b>: ישעי' ו, ג ובתרגום יונתן שם."]]],[2300550135,"בשוה מטעם הנ\"ל שאין ענין הצמצום רק לגבי המקבלים ולא לפניו כו', וא\"כ [איך] יוכל להיות שיצמצם אור הא\"ס א\"ע כ\"כ להיות דירתו למטה דוקא בסוף עשי' בהיכל ק\"ק במקום מיוחד בין ב' בדי [ה]ארון דוקא, שלא יתכן להיות בב' מדרגות דסובב וממלא שבשניהם שוה <span data-k=\"pg\">1298</span> ּ מעלה ומטה ממש מטעם הנ\"ל וז\"ש איזה בית כו' וד\"ל.\n<b>אך</b> הנה צ\"ל דמ\"ש נתאוה להיות לו דירה בתחתונים דוקא כמו בתו\"מ בפו\"מ ובגילוי שכינה בהיכל ומקום גשמי כו' זהו הארת אור הע[צמות] דא\"ס ב\"ה [ממש] שלמעלה [גם] מבחי' סומ\"מ כו', שכל יכול הוא לצמצם א\"ע שיהי' השראת פנימי' עצמותו ממש שורה בתחתונים דוקא והוא כמו במעשה גשמי' דמצות בעוה\"ז השפל דוקא כו', אעפ\"י שהוא סוף כל המדרגות [ב]השתלשלות דממלא וסובב (שגם בחי' סובב שייך להשתל'<sup data-n=\"9504\">21</sup> מאחר שנק' מקיף וסובב למעלה ומטה עכ\"פ). והיינו דוקא מפני שהשמים ושה\"ש (טה\"ע וטה\"ת)<sup data-n=\"9505\">22</sup> כו' ע\"כ יכול לצמצם שכינתו בסוף מעשה דוקא, וכן בגילוי שכינתו בהיכל ק\"ק דעשי' דוקא יותר מלפני האצי' כו' מפני שנתב\"ס<sup data-n=\"9506\">23</sup> שהוא אור הע[צמו'] דא\"ס שנק' תחלת כל התחלות וקדמון לכל הקדומים<sup data-n=\"9507\">24</sup> כו' בסוף הכל דוקא כו' (דמה שאוא\"ס למעלה עד אין קץ<sup data-n=\"9508\">25</sup> שורה בעומק תחת בסוף העשי' דוקא). וראי' לזה דהרי [ה]עוה\"ב שהוא בא משעשועי' הע[צמיי'] שברוממות וע[צמות] דא\"ס שיאיר בנשמות אינו בא רק ע\"י תורה ומע\"ט<sup data-n=\"9509\">26</sup> בעוה\"ז דוקא וע\"כ גזרו אומר דיפה שעה א'<sup data-n=\"9510\">27</sup> כו' [כידוע], הרי יגיע יתרון מעלה כזו לנה\"א בהיותה בעוה\"ז בגוף ועוסק בתורה ומע\"ט יותר מכמו שהיתה צרורה בצרור החיים<sup data-n=\"9511\">28</sup> בג\"ע, וגם יותר ממה שתחי' חיי עולם בעוה\"ב כו'. וכ\"ז מטעם הנ\"ל וד\"ל<sup data-n=\"9512\">29</sup> שנתאוה הקב\"ה להיות לו דירה ממש [ו]בתחתונים (ופי' [תחתונים לא] תחתונים במקום שהרי שוין לפניו מעלה ומטה כו' אלא תחתונים במעלה<sup data-n=\"9513\">30</sup> כו'<sup data-n=\"9514\">31</sup> ). והנה עיקר ענין [דירה ו]השראה זו בתחתונים בקיום התו\"מ יש בזה ב' מדרגות, הא' בקיום רמ\"ח מ\"ע בע[שה] ט[וב] והב' בסו\"מ בשס\"ה ל\"ת<sup data-n=\"9515\">32</sup>, והיינו כללו' דשם הוי' שאמר זה שמי וזה זכרי<sup data-n=\"9516\">33</sup> כו' שמי עם י\"ה גימ' שס\"ה וזכרי עם ו\"ה<sup data-n=\"9517\">34</sup> גימ' רמ\"ח כידוע והן הכל[ו]לים בב' דברות דאנכי ולא יהי' לך<sup data-n=\"9518\">35</sup> כידוע וד\"ל.",[["9504","21","<b>סובב שייך להשתל'</b>: ראה תניא פמ\"ח. ש\"א פט, א ובהערה 1."],["9505","22","<b>שהשמים ושה\"ש (טה\"ע וטה\"ת)</b>: ראה גם לעיל פ' בשלח קעח, ג. וש\"נ."],["9506","23","<b>שנתב\"ס</b>: ראה ס\"י פ\"א, מ\"ח."],["9507","24","<b>וקדמון לכל הקדומים</b>: ת\"ז תי\"ט (מב, א). ראה מאמרי אדה\"א דברים ח\"ב ע' תנט. וש\"נ."],["9508","25","<b>שאוא\"ס למעלה עד אין קץ</b>: נסמן לעיל בפ' תצוה שכג, א."],["9509","26","<b>[ה]עוה\"ב. . ע\"י תורה ומע\"ט</b>: ראה מאמרי אדה\"א בראשית ע' שצב. וש\"נ. לעיל פ' שמות ז, א. וש\"נ."],["9510","27","<b>דיפה שעה א'</b>: אבות פ\"ד מי\"ז [ושם: יפה — ראה גם לעיל בפ' שמות ט, א הערה 400]."],["9511","28","<b>צרורה בצרור החיים</b>: שמו\"א כה, כט."],["9512","29","<b>וד\"ל</b>: חט: ליתא."],["9513","30","<b>תחתונים במעלה</b>: ראה גם לעיל תמב, ג."],["9514","31","<b>כו'</b>: חט: כנ\"ל."],["9515","32","<b>רמ\"ח מ\"ע. . בשס\"ה מל\"ת</b>: מכות כג, סע\"ב."],["9516","33","<b>זה שמי וזה זכרי</b>: שמות ג, טו [בדילוג]."],["9517","34","<b>שמי עם י\"ה. . וזכרי עם ו\"ה</b>: נסמן לעיל תמב, ד הערה 19."],["9518","35","<b>רמ\"ח. . בשס\"ה. דאנכי ולא יהי' לך</b>: נסמן לעיל פ' יתרו רנב, א."]]],[2300550167,"[ו]<b>הנה</b> מאחר ששמי עם י\"ה גימ' שס\"ה כו' הרי שרש השס\"ה ל\"ת בי\"ה שקודם ו\"ה דמ\"ע וא\"כ שרש הל\"ת גבוה מ[ן ה]מ\"ע, וכך משמע מהמאמר הידוע בזהר דכד אתכפייא סט\"א אסתלק יקרא דקוב\"ה<sup data-n=\"9519\">36</sup> בכולהו עלמין ופי' אסתלק היינו בתוס' עילוי האור שאין זה בקיום המ\"ע אע\"פ שהן בחי' פנימי' רצה\"ע אלא דוקא בסו\"מ דל\"ת מצד דאתכפי' דסט\"א כו'. ולכאו' זהו פלא גדול דמה תופס מקום כל יניקת החיצונים לגבי כל ההשתל' דקדושה האלקי' שאינם מקבלים רק מאחוריי' דאחוריי' דש[ם] אלקי'<sup data-n=\"9520\">37</sup> שזהו פסולת ונובלות הנופל מן הקדושה כידוע, וכמו השממית בהיכל מלך<sup data-n=\"9521\">38</sup> שאינ[ה] תופס[ת] מקום כלל כמ\"ש כל הגוים כאין נגדו<sup data-n=\"9522\">39</sup> כו' וכשחק מאזנים<sup data-n=\"9523\">40</sup> כו', וא\"כ גם זה יפלא למה שרש הל\"ת בי\"ה דשם הוי' שנק' בשם נסתרות<sup data-n=\"9524\">41</sup> כמ\"ש הנסתרות לה' אלקינו<sup data-n=\"9525\">42</sup> והנגלות הן ו\"ה וכמשמעות שמי עם י\"ה כו' הרי שמ[י] מורה שהוא עיקר שמו וכמ\"ש זה שמי לעולם כו', ואמנם זה זכרי עם ו\"ה זכרי טפל לגבי עיקר דשם י\"ה דזכרי הוא רק זכרי דשם ה'<sup data-n=\"9526\">43</sup> העיקר לבד ולא עיקר השם, ואיך יוכל להיות שמ\"ע שהם בו\"ה הם בחי' טפל לגבי ל\"ת די\"ה. וצ\"ל דשרש הל\"ת גבוה ממ\"ע אעפ\"י <span data-k=\"pg\">תרמט</span> ּ שהל\"ת אינו רק בשב ואל תעשה, וראי' לזה משרז\"ל בעובר על מ\"ע<sup data-n=\"9527\">44</sup> ושב בתשו' מוחלין לו מיד, משא\"כ עבר על ל\"ת<sup data-n=\"9528\">45</sup> צריך תשובה ויסורים ממרקין ויוהכ\"פ מכפר (ובפורק עול מ\"ע חמור מל\"ת שהרי מכין אותו עד שתצא נפשו<sup data-n=\"9529\">46</sup> ובל\"ת די במלקות ל\"ט). ובאמת זה פלא גדול מאד איך יהי' שב ואל תעשה רע לבד דל\"ת גבוה מבחי' ע\"ט דמ\"ע שהם בחי' המשכן<sup data-n=\"9530\">47</sup> גילוי אלקות, כידוע דרמ\"ח פקודין נק' רמ\"ח מ\"ע<sup data-n=\"9531\">49</sup> רמ\"ח אברים דמלכא<sup data-n=\"9532\">48</sup> כו' ובל\"ת אין שום גילוי אלקות להיות[ו] רק מניעת המעשה דרע הפוגם ומסתיר אור האלקי, וגם זה בא בענין שב ואל תעשה לבד כמו אל תאכל חלב<sup data-n=\"9533\">50</sup> כו' וכה\"ג.\n<b>אמנם</b> הענין הוא משום דאדרבה היא הנותנת דלפי של\"ת הוא רק שב ואל תעשה דבר המסתיר כו' זהו הטעם שגבוה ממ\"ע שהוא המשכות דקדושה משום דלאו קודם להן<sup data-n=\"9534\">51</sup> בכ\"מ רק שבא [ב]דרך שלילה לבד כו'. ותחלה י\"ל בענין רמ\"ח מ\"ע שהן כמו רמ\"ח אברין<sup data-n=\"9535\">52</sup> כו', דהנה כל אבר ואבר יש לו חיות מיוחד שנמשך בו מעל<sup data-n=\"9536\">53</sup> הנפש ממש ששוכן בנשמה שבמוח ורוח",[["9519","36","<b>דכד אתכפייא סט\"א אסתלק יקרא דקוב\"ה</b>: נסמן לעיל תמב, ד. הערה 14."],["9520","37","<b>יניקת החיצונים. . מאחוריי'. . אלקי'</b>: ראה גם תו\"א קב, ב. קט, ד. לעיל פ' שמות ל, ב ובהערה 139."],["9521","38","<b>השממית בהיכל מלך</b>: ראה גם שערי אורה מח, ב."],["9522","39","<b>כל הגוים כאין נגדו</b>: ישעי' מ, יז."],["9523","40","<b>וכשחק מאזנים</b>: ישעי' שם, טו."],["9524","41","<b>בי\"ה דשם הוי' שנק' בשם נסתרות</b>: נסמן לעיל תמב, ד הערה 21."],["9525","42","<b>הנסתרות לה' אלקינו</b>: נצבים כט, כח."],["9526","43","<b>זכרי דשם ה'</b>: חט: זכר השם."],["9527","44","<b>בעובר על מ\"ע ושב</b>: ראה יומא פו, א. אגה\"ת רפ\"א."],["9528","45","<b>עבר על ל\"ת</b>: ראה יומא ואגה\"ת שם. ושם תשובה תולה ויוה\"פ מכפר, עבר על כריתות ומיתות ב\"ד תשובה ויוה\"כ תולין ויסורין ממרקין. וראה לעיל תמב, ד."],["9529","46","<b>מכין אותו עד שתצא נפשו</b>: כתובות פו, רע\"ב. ראה שדי חמד מערכת כפי' כלל מא."],["9530","47","<b>המשכן</b>: ח: כבפנים. ט: המשכות."],["9531","49","<b>רמ\"ח מ\"ע</b>: חט: ליתא."],["9532","48","<b>דרמ\"ח פקודין. . רמ\"ח אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). שע\"ת עב, ג הערה 17."],["9533","50","<b>אל </b>[שם: לא]<b> תאכל חלב</b>: ראה ויקרא ג, יז."],["9534","51","<b>דלאו קודם להן</b>: ראה גם לעיל תמג, ג. וש\"נ."],["9535","52","<b>רמ\"ח מ\"ע. . רמ\"ח אברין</b>: מכות כג, סע\"ב."],["9536","53","<b>מעל</b>: חט: מעצמות."]]],[2300550199,"החיים שבלב<sup data-n=\"9537\">54</sup>, וע\"כ כל האברים כלולי' ומתאחדים בעצמות הנפש ממש והיו לאחדים ממש עד שא\"א ל[י]פרד גם אבר א' קטן מן הנפש. והראי' מרצון הנפש ששולט בכל האברים בשוה ממש שיש בכל אבר מא[ו]ר הרצון ביחוד עכ\"ז כולם ביחד<sup data-n=\"9538\">55</sup> נשמעים לרצון הנפש עד שבכללם נק' אד\"ם, שהוא בחי' אדם חיצוני שמתאחד באדם פנימי שהוא הרצון ו[ה]חכמה שבמוח, כי בחי' החכ' שבמוח מתאחד יותר בעצם הנפש ונק' נפש השכלי'<sup data-n=\"9539\">56</sup> אעפ\"י שיש כלי מיוחד להשראת אור השכל כשאר האברים שכל א' נק' כלי לאור וחיות שבו, מ\"מ כח השכל שבמוח הוא [ה]מתאחד בעצם הנפש יותר. והוא כח הכולל לכל חיות [ה]אברים שע[ל] י[דו] דוקא יומשך כל אור וחיות מיוחד לכל [ה]אברים ע\"כ המוח מרגיש כל [ה]אברים יחד ועל ידו דוקא מתאחדים כל האברים בנפש עצמה, אעפ\"י שאור וחיות שבהם שוכן בכאו\"א בפ\"ע דוקא מ\"מ כולן מתכללי' יחד ע\"י כח הנשמה שכלי' שבמוח ורוח שבלב, שיש בהן כל האברים בהתכללות בבחי' פנימי' ורוחני' כמו שהאברים הן בחיצוני'. וכמו שיש ב' מיני אברים באדם בגשמי[ות], א' אברים חיצוני' ממש כיד ורגל וכה\"ג, והב' אברים פנימי' כריא' ולב ודקים שנקובתן במשהו<sup data-n=\"9540\">57</sup> כידוע. כך יש ב' מדרגות האברים בחיצוני' בגוף ובפנימי' בנפש ונשמה ורוח שבמוח ולב שנק' אברים פנימי' בכלל שחיותם פנימי יותר מחיות אברי דגוף בכלל וד\"ל.\n<b>והנמשל</b> מכ\"ז יובן למעלה בשרש ענין התו\"מ דבחי' התו\"מ<sup data-n=\"9541\">*58</sup> שהן ב' דברים וכמ\"ש כי נר מצוה<sup data-n=\"9542\">58</sup> ותורה אור כו', שהמצות הן בחי' כלים מכלים שונים כמו אברים חיצוני' לבחי' אדה\"ע שעל הכסא כו' שאור עצמות המאציל שורה בכאו\"א מהן ביחוד גמור כהתאחדות אברי [ה]אדם בעצמות הנפש, וכמ\"ש דאיהו וחיוהי וגרמוהי<sup data-n=\"9543\">59</sup> כולא חד ממש שהן או\"כ דאצי' שמי[ו]חדי' בתכלי' בע[צמות] המאציל <span data-k=\"pg\">1300</span> ּ בלתי פירוד לעולם, וגם למטה הן המצות שבכל מצוה יש [בחי'] אור רצה\"ע ביחוד כמצות צדקה וחסד ביד ימין כו' וכל מצוה נק' כלי לאור מיוחד בפ\"ע ועכ\"ז יש בהן בחי' היחוד וההתכללות בע[צמות] אוא\"ס ב\"ה בעה\"ר<sup data-n=\"9544\">60</sup> כו' שהוא התענוג שבעצמות שא' ונעשה רצוני<sup data-n=\"9545\">61</sup> בכל מצוה ומצוה כו', כמו שבאדה\"ת כל האברים נשמעים לרצונו ביחד כו' ושולט בכל האברים בשוה כנ\"ל. וזהו שנק' אור הכת\"ר בכלל שהוא פנימי' ועצמות רצה\"ע שבכל המצות ביחד",[["9537","54","<b>בנשמה שבמוח ורוח החיים שבלב</b>: ראה אבן עזרא משפטים כג, כה. לעיל פ' בשלח קמה, א הערה 55."],["9538","55","<b>ביחד</b>: ט: ליתא."],["9539","56","<b>נפש השכלי'</b>: ראה גם לעיל פ' בא קא, ג. וש\"נ."],["9540","57","<b>כריא' ולב ודקים שנקובתן במשהו</b>: ראה שו\"ע יו\"ד סל\"ו, ס\"א. ס\"מ, ס\"א. סמ\"ו, ס\"א."],["9541","*58","<b>דבחי' התו\"מ</b>: אח: כבפנים. גדט: דכתי' [ו]התורה והמצוה — נסמן לקמן בהערה 76."],["9542","58","<b>כי נר מצוה</b>: משלי ו, כג. ראה גם לעיל פ' תצוה שלו, א."],["9543","59","<b>דאיהו וחיוהי וגרמוהי</b>: ראה ת\"ז בהקדמה (ג, ב)."],["9544","60","<b>בעה\"ר</b>: ראה גם לעיל פ' ויקהל תיב, ד ובהערה 817."],["9545","61","<b>שא' ונעשה רצוני </b>[חט: רצונו]: ע\"פ ספרי פינחס כח, ח."]]],[2300550231,"כו' וע\"כ עי\"ז מתאחדים כל המצות בעצמות א\"ס בלתי הפרש במעלה ומדרגה בקלה כבחמורה כמו אם חסר אבר אחד שאינו נק' אדם כנ\"ל וד\"ל.\n<b>והנה</b> מבואר למעלה בב' מיני אברים פנימי' וחיצוני' שהמוח שבראש הוא כח הכולל לכל חיות האברים פנימי' וחיצונים והוא שמתאחד בעצם הנפש יותר וע\"י מתאחדים כל האברים כו', וכך יובן בשרש התורה דאוריי' מח\"ע נפקת<sup data-n=\"9546\">62</sup> שזהו בחי' חכ' מוחא<sup data-n=\"9547\">63</sup> שנק' חכים ולא בחכמה ידיעא<sup data-n=\"9548\">64</sup> כו' שזהו בחי' אור דתורה [שלמעלה] שכולל לכל או\"כ דאצי' בין בפנימי' ובין בחיצוני', והוא בחי' פנימי' דאדה\"ע כמו יאר ה' פניו אליך<sup data-n=\"9549\">65</sup> כו' כי החכ' במוח מתאחד בעצמות המאציל ממש יותר מכל רמ\"ח אברים כו'. וכמו שאנו רואים שבאור החכ' מחדש [י]עשה הארת פנים ביותר כמ\"ש חכמת אדם תאיר פניו<sup data-n=\"9550\">66</sup> כו' [ו]כמו צהבו פניו כו' דר\"א<sup data-n=\"9551\">67</sup> מפני שמצא תוספתא חדתא, וכן במ\"ת הי' הארת פנים עליונים דכנ\"י<sup data-n=\"9552\">68</sup> בכלל כמ\"ש באור פניך נתת לנו<sup data-n=\"9553\">69</sup> כו'. וכך הוא גם עתה בכל אדם בפרט כשיושב ושונה דבר ה' זו הלכה<sup data-n=\"9554\">71</sup> הקב\"ה יושב ושונה כנגדו<sup data-n=\"9555\">70</sup> בבחי' הארת פנים העליונים שבחכ[מת] אדה\"ע, כי הגם שמצד עצמו נק' חכים ולא בחכ' ידיעא כו' כלל. אבל בגילוי אור מחכ' הסתומה שבעצמו' נק' בחי' אור פנימי' דאדם בכלל להמשיך אור וחיות חדש לכל המצות בכל מצוה ומצוה בפרט, כמו המוח שממשיך חיות חדש לכל האברים ולעשות בהם התכללות ואחדות בעצמות א\"ס ב\"ה. וז\"ש כי נר מצוה ותו\"א שנק' אור כללי לכל או\"כ דמצות, ולזה הטעם מצות ת\"ת כנגד כולם<sup data-n=\"9556\">72</sup> ותלמוד גדול מפני שמביא לידי מעשה<sup data-n=\"9557\">73</sup> מטעם הנ\"ל (וע\"כ מצות ת\"ת תמידי' [ב]יום ולילה<sup data-n=\"9558\">74</sup> כו') שהמצות הן חיצוני' דאברים דמלכא ות\"ת הוא בבחי' הפנימי' דכללות כולם יחד וד\"ל.\n<b>והנה</b> התו\"מ הן בחי' ו\"ה דשם הוי'<sup data-n=\"9559\">75</sup> שהתורה [ש]נק' אור הכללי הפנימי' דמצות הוא [בחי'] וי\"ו והמצות הן בחי' ה' והוא בחי' משפיע ומקבל וז\"ש והתורה והמצות<sup data-n=\"9560\">76</sup> (וע\"כ גם באדם בפרט מה שקובע עתים לתורה זהו שרש חיות כללי ליחו\"ע שבמצות שעשה כל ימיו וא\"ל אין למצות חיות כלל וע\"כ עון דביטול תורה חמור יותר<sup data-n=\"9561\">77</sup>, ולהיפך האומר אין לי אלא תורה<sup data-n=\"9562\">78</sup> כו' דזהו כאור בלי כלי כלל כו'), וזהו והנגלו\"ת לנ\"ו",[["9546","62","<b>דאוריי' מח\"ע נפקת</b>: נסמן לעיל פ' יתרו רסח, ד."],["9547","63","<b>חכ' מוחא</b>: נסמן לעיל פ' ויקהל שפח, ב."],["9548","64","<b>חכים ולא בחכמה ידיעא </b>[חט: ליתא]: נסמן לעיל תמג, ב."],["9549","65","<b>יאר ה' פניו אליך</b>: נשא ו, כה."],["9550","66","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["9551","67","<b>צהבו פניו כו' דר\"א</b>: ראה ירושלמי שבת פ\"ח, ה\"א. לעיל פ' בשלח קעח, ב. וש\"נ."],["9552","68","<b>דכנ\"י</b>: ט: לכנ\"י."],["9553","69","<b>באור פניך נתת לנו</b>: סיום תפלת העמידה."],["9554","71","<b>דבר ה' זו הלכה</b>: עמוס ח, יב. שבת קלח, ב."],["9555","70","<b>כשיושב ושונה. . הקב\"ה יושב ושונה כנגדו</b>: ראה תדא\"ר רפי\"ח. לעיל פ' וארא נח, ג הערה 18."],["9556","72","<b>מצות ת\"ת כנגד כולם</b>: פאה רפ\"א."],["9557","73","<b>ותלמוד גדול. . לידי מעשה</b>: קדושין מ, ב."],["9558","74","<b>מצות ת\"ת תמידי' [ב]יום ולילה</b>: ראה מנחות צט, סע\"ב. לקמן תס, ב. לעיל פ' וארא פא, א ובהערה 601."],["9559","75","<b>התו\"מ. . ו\"ה דשם הוי'</b>: ראה גם לעיל תמג, ב. פ' בשלח קפד, ד. לקו\"ת פקודי ג, ג. תצא לט, א. מאמרי אדה\"א דברים ח\"ג ע' א'קג. וש\"נ."],["9560","76","<b>והתורה והמצות</b>: כ\"ה גם במאמרי אדה\"א בראשית ע' תקמט. במדבר ח\"ג ע' תתקפד. גד ולקמן תנה, ג: והתורה והמצוה — משפטים כד, יב. ט: התו' והמצוה — דהי\"ב יד, ג. ראה גם שערי אורה לח, א. מאמרי אדה\"א דברים ח\"ב ע' תרנט. ח\"ג ס\"ע א'סט ואילך."],["9561","77","<b>עון דביטול תורה חמור יותר</b>: ראה תניא פ\"א ובמ\"מ הגהות והע\"ק שם."],["9562","78","<b>אין לי אלא תורה</b>: יבמות קט, ב."]]],[2300550262,"ולבנינ\"ו כו' ו\"ה והנגלות הן תו\"מ כנ\"ל וזהו זכרי עם ו\"ה עולה רמ\"ח כו' כנ\"ל. והטעם שתו\"מ נק' זכרי אע\"פ שזהו בחי' פנימי' וחיצוני' דאדה\"ע כנ\"ל, הענין הוא דכמו שזכרון של השם אינו עיקר השם כנ\"ל, <span data-k=\"pg\">תרנ</span> ּ כך גם בתו\"מ הן רק בחי' שמות שהן בחי' כלים חיצוני' בבחי' לבושים בלבד שבהם מתלבש בחי' עצמות [או]א\"ס ב\"ה (אע\"ג דאיהו וחיוהי וגרמוהי חד כו'), שהרי גם אותיות התורה שנק' פנימי' דאדה\"ע כנ\"ל הרי א' דכל הקורא בתורה<sup data-n=\"9563\">79</sup> כאלו<sup data-n=\"9564\">80</sup> קורא בשמותיו של הקב\"ה, פי' קורא בשמותיו בבחי' קריאה וזכרון שם שאינו רק בחי' זכרון של שמותיו העצמי' ממש לפי שאותיות התורה אינו רק בחי' לבוש בלבד, אעפ\"י שאמר ותורה אור כמ\"ש עוטה אור כשלמה<sup data-n=\"9565\">81</sup> דקאי באור דתורה כידוע. אך עכ\"ז באותיות וזכרון שם<sup data-n=\"9566\">82</sup> דתורה יש זכרון שמות העצמי' ממש כמו שהן למעלה בעצמותו ממש, וזהו פי' קורא בשמותיו ממש שהוא עיקר מצות קריאת התורה. אבל מעשה המצות הם כלים ולבושים חיצוני' יותר להיותם מוגבלים בכלים ואברים חיצונים כנ\"ל, והן זכרון בחי' שמות ויחודים עליונים דאצי' שבאים למטה בעלמא דאתגליא בעשי' גשמי' בד' בתים דתפילין וחוטין דציצית וכה\"ג בכל המצות שנעשה יחו\"ע דקוב\"ה ו[שכינתי'], או יחו\"ע דאו\"א באורות פנימי' ומקיפי' כסכך דסוכה שהן מקיפים דאי<sup data-n=\"9567\">83</sup>[מא] כו' וכה\"ג הכל הן שמות ויחודים שנעשים למטה בארץ.\n<b>וזהו</b> לכו חזו מפעלות אלקים<sup data-n=\"9568\">84</sup> אשר שם שמות בארץ א\"ת שמות אלא שמות<sup data-n=\"9569\">85</sup> שהן שמות דיחו\"ע שבאצי' שבהם באים<sup data-n=\"9570\">*86</sup> למטה בארץ דוקא, וזהו שם שמות בארץ דוקא בשימה ועשי' ולא בשמות אותיות התורה שהן זכרון התורה<sup data-n=\"9571\">86</sup> השמות ועצמיות<sup data-n=\"9572\">87</sup> ממש רק שהלבושים<sup data-n=\"9573\">88</sup> בלבוש דאור דתורה שהוא לבוש פנימי מאד, אבל שמות דמעשה המצות שם אותי'<sup data-n=\"9574\">89</sup> בלבושים דעשי' בארץ ונק' מפעלות אלקי' כו', ועכ\"ז עליהם אמר ג\"כ וזה זכרי שהוא זכר דשם העיקר דשם הוי' שהרי נק' מצות הוי'<sup data-n=\"9575\">90</sup> אורחות הוי'<sup data-n=\"9576\">91</sup> דרכי הוי'<sup data-n=\"9577\">92</sup> כידוע רק שהן בה'['א] אחרונה דש' הוי' והתורה בוי\"ו כנ\"ל וד\"ל. וכ\"ז במעשה המצות בפ\"מ דוקא שעז\"א והנגלות לנו ולבנינו לשמור ולעשות<sup data-n=\"9578\">93</sup> דוקא (וזהו מצוה בא\"ת ב\"ש הוא שם הוי'<sup data-n=\"9579\">94</sup> בה<sup data-n=\"9580\">95</sup> די\"ה נתחלף [במ' צ']",[["9563","79","<b>דכל הקורא בתורה</b>: ראה גם לעיל פ' תצוה שנט, ד. וש\"נ."],["9564","80","<b>כאלו</b>: ט: ליתא."],["9565","81","<b>עוטה אור כשלמה</b>: נסמן לעיל פ' תצוה שלא, א הערה 494."],["9566","82","<b>וזכרון שם</b>: ט: ליתא."],["9567","83","<b>כסכך. . מקיפים דאי[מא]</b>: ראה גם לעיל פ' בשלח רלו, ב. מאמרי אדה\"א דברים ח\"ד ע' א'שנו. וש\"נ."],["9568","84","<b>לכו חזו מפעלות אלקים</b>: נסמן לעיל בפ' יתרו רנג, א."],["9569","85","<b>א\"ת שמות אלא שמות</b>: ברכות ז, ב. ראה גם לעיל פ' וארא עה, ג."],["9570","*86","<b>שבהם באים</b>: חט: שבאים."],["9571","86","<b>התורה</b>: חט: ליתא."],["9572","87","<b>ועצמיות</b>: ט: שבע'."],["9573","88","<b>שהלבושים</b>: חט: שהלבישם."],["9574","89","<b>אותי'</b>: שם: אותם."],["9575","90","<b>מצות הוי'</b>: ויקרא ד, ב. יג. כב. ועוד."],["9576","91","<b>אורחות הוי'</b>: תהלים כה, י. ראה לעיל פ' וארא סט, ד. וש\"נ."],["9577","92","<b>דרכי הוי'</b>: שמו\"ב כב, כב. הושע יד, י. תהלים יח, כב."],["9578","93","<b>והנגלות. . לשמור ולעשות</b>: ועד\"ז הובא לעיל פ' בא קיד, ב הערה 178."],["9579","94","<b>מצוה בא\"ת ב\"ש. . הוי'</b>: ראה ת\"ז תכ\"ט (עג, א). מאמרי אדה\"א נ\"ך ע' ג. וש\"נ."],["9580","95","<b>בה</b>: חט: ליתא."]]],[2300550292,"בלבוש חיצוני מאד ולע\"ל נאמר ולא יכנף עוד<sup data-n=\"9581\">96</sup> כו', וזהו זכרי עם ו\"ה גימ' רמ\"ח כמ\"ש במ\"א, לפי שסו\"מ דוקא עבמח\"ת כמ\"ש לעשות חסד ומשפט וצדקה בארץ<sup data-n=\"9582\">97</sup> דוקא כי באלה חפצתי כו' ע\"כ יש בהם יותר מעלה מו\"ה<sup data-n=\"9583\">98</sup> (כמשי\"ת). אבל הנסתרות לה' אלקינו כו' זהו בחי' י\"ה דשם הוי' שהן שס\"ה ל\"ת שהוא מ\"ש שמי עם י\"ה גימ' שס\"ה כנ\"ל והוא בחי' שם העיקר והעצם שלמעלה מזכרי שאינו רק זכרון השם כנ\"ל לפי ששרש הל\"ת<sup data-n=\"9584\">99</sup> הן יותר גבוהים משרש המ\"ע ע\"כ נק' נסתרות לה' אלקינו כו' למעלה ממ\"ע הנגלות לנו ולבנינו שהן בחי' י\"ה<sup data-n=\"9585\">100</sup> כנ\"ל.\n<b>וביאור</b> הענין הנה כתיב והחכ' מאין תמצא<sup data-n=\"9586\">101</sup> [פי'] מאין ליש תמצא, וכידוע דהחכ' נק' ראשית הגילוי<sup data-n=\"9587\">102</sup> אור בהשתל' כי למעלה מן החכ' עדיין אין גילוי אור במציאות <span data-k=\"pg\">1302</span> ּ כלל, והוא בחי' נקודה [דיו\"ד דשם הוי' שהוא בהתהוות האור דחכ' מבחי' ההעלם ואין דכת\"ר שנק' עה\"ע<sup data-n=\"9588\">103</sup> כו', ובחי' נקודה ד]יו\"ד עדיין גם הוא למעלה מן ההתפשטות בהשגה ותפיסא דבינה כמו מעיין הנובע מן ההעלם לגילוי טיפין טיפין לבד כו', ולפי שבא אור דחכ' עכ\"פ בבחי' גילוי אור קצת מן ההעלם נק' ראשית הגילוי והוא המתפשט ליש גמור בהשגה ותפיסא ממש. וז\"ש דביו\"ד דוקא נברא העוה\"ב<sup data-n=\"9589\">104</sup> וכל בריאה הוא מאין ליש<sup data-n=\"9590\">105</sup> דוקא כידוע, וגם העוה\"ב נברא מאין דיו\"ד דחכ' ליש והוא מה שבעוה\"ב נאמר להנחיל אוהבי י\"ש<sup data-n=\"9591\">106</sup> ממש (והוא בחי' עונג האלקי המורגש בהשגה דבינה, וכמו ת' עלמין דכסופין<sup data-n=\"9592\">107</sup> כו' להיות נהנין ומרגישי' בתענוג הפשוט העצמי ממש שנק' שעשועי המלך בעצמו<sup data-n=\"9593\">108</sup> ממש שהי' בבחי' ההעלם בעצמו ממש<sup data-n=\"9594\">109</sup> ויצא לגילוי אור במורגש [בהשגה], ויש מעין זה בכל שבת<sup data-n=\"9595\">110</sup> בג' סעודות השבת וכמ\"ש במ\"א). אמנם לפני התהוות האור דחכ' מאין ליש קודם שאמר יהי אור שהוא אור דח\"ע<sup data-n=\"9596\">111</sup> כו' הי' עדיין לפני מקור ההשתל' דאבי\"ע (וע\"כ אנו או' אין זולתך מלכינו<sup data-n=\"9597\">112</sup> לחיי העוה\"ב שנק' רק ביו\"ד דחכמה כנ\"ל), ושם אי'<sup data-n=\"9598\">113</sup> בס\"י לפני אחד מה אתה סופר<sup data-n=\"9599\">114</sup> שהוא בבחי' פנימי' אור הכתר שלמעלה מחשבון י\"ס הגלוים שנק' עה\"ע כו' שעליו אמר אנת הוא חד ולא בחושבן<sup data-n=\"9600\">115</sup> י\"ס לפי שאין התחלה וראשית הגילוי אור הוא רק ביו\"ד דחכ'. אבל באי\"ן והעלם דעצמות אור",[["9581","96","<b>ולא יכנף עוד</b>: ישעי' ל, כ. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' נה. דברים ח\"ב ר\"ע תקכב. קונטרסים ס\"ע שכב ואילך."],["9582","97","<b>לעשות חסד ומשפט וצדקה בארץ</b>: ירמי' ט, כג. [ושם: עושה — ראה לעיל פ' בשלח קלח, ד הערה 330]."],["9583","98","<b>מו\"ה</b>: חט: מי\"ה."],["9584","99","<b>הל\"ת</b>: בתו\"ח כאן נכפלו עוה\"פ התיבות: שהוא מ\"ש. . ששרש הל\"ת."],["9585","100","<b>י\"ה</b>: חט: ו\"ה."],["9586","101","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["9587","102","<b>דהחכ' נק' ראשית הגילוי</b>: ראה לעיל תמג, ב. וש\"נ."],["9588","103","<b>דכת\"ר שנק' עה\"ע</b>: ראה פרדס (שער אם הא\"ס הוא הכתר) ש\"ג, ספ\"א."],["9589","104","<b>דביו\"ד. . נברא העוה\"ב</b>: ראה גם לעיל תמג, ב. וש\"נ."],["9590","105","<b>וכל בריאה הוא מאין ליש</b>: ראה רמב\"ן בראשית א, א."],["9591","106","<b>שבעוה\"ב. . להנחיל אוהבי י\"ש</b>: משלי ח, כא. ראה גם לעיל תמג, ב. פ' שמות לד, סע\"א. וש\"נ."],["9592","107","<b>ת' עלמין דכסופין</b>: ראה גם לעיל פ' שמות כה, ד. וש\"נ."],["9593","108","<b>שעשועי המלך בעצמו</b>: נסמן לעיל פ' תרומה שיח, ב."],["9594","109","<b>ממש</b>: בתו\"ח כאן נכפלו עוה\"פ התיבות: שהי' בבחי'. . ממש."],["9595","110","<b>ויש מעין זה בכל שבת</b>: ראה סידור סדר סעודת שבת קצט, ג. ר, א."],["9596","111","<b>יהי אור. . דח\"ע</b>: ראה גם לעיל פ' תשא שפה, א ובהערה 62."],["9597","112","<b>אין זולתך מלכינו</b>: ברכת יוצר לשבת [ושם: ואין]."],["9598","113","<b>אי'</b>: חט: א'."],["9599","114","<b>לפני אחד מה אתה סופר</b>: נסמן לעיל בפ' תרומה שיב, ד."],["9600","115","<b>אנת הוא חד ולא בחושבן</b>: ת\"ז בהקדמה (יז, א)."]]],[2300550319,"הכתר הרי אינו בא לכלל גילוי מן ההעלם כלל ואינו מושג ובא גם בבחי' נקודה דיו\"ד כלל (וגם בחי' החכ' שבו נק' שכל הנעלם מכל רעיון<sup data-n=\"9601\">116</sup> ), וז\"ש דאפילו אור צח אור מצוחצח אוכם הוא<sup data-n=\"9602\">117</sup> לגבי עה\"ע עצמו, אור צח זהו בחי' נקודה דאור החכ' ואפי' אור מצוחצח שהוא ח\"ס חכ' שבכת\"ר אוכם הוא בלי גילוי אור במציאות כלל לגבי עה\"ע עצמו, וז\"ש אנת עילאה על כל עילאין<sup data-n=\"9603\">118</sup> כו' עד למתב\"כ, פי' אפי' מחה\"ק<sup data-n=\"9604\">119</sup> שנק' אור צח ומצוחצח כו' (וכמו טעמי מצות [ו]סודות ורזין דאורייתא שיתגלה בימוהמ\"ש).\n<b>אך</b> א\"כ לכאורה י\"ל דלפי הנ\"ל שבחי' עה\"ע עצמו הוא [בחי'] אור פשוט בתכלית וסתום ומופלא שנק' סדכ\"ס<sup data-n=\"9605\">120</sup> דלמתב\"כ עד שא\"א שיבא ויומשך ממנו שום מקור להשתל' השפע בבחי' עו\"ע שהוא מאי\"ן לי\"ש כלל, א\"כ ודאי גם אור החכ' כמו שה[י]א במקומה<sup data-n=\"9606\">121</sup> באין לא יוכל לבא מן ההעלם לגילוי אור במציאות חכמה מאין ליש כלל (משום דגם בחי' ח\"ס מקור החכ' אוכם הוא כו' כנ\"ל). ולפי\"ז לא יובן מ\"ש והחכמה מאין תמצא דמשמע מאין תמצא בהעלם וגילוי<sup data-n=\"9607\">122</sup>, ו[ר]אי ממה שמצינו ברזין וסודות טעמי תו' שבאים בגילוי מן ההעלם בג\"ע וימוהמ\"ש ועוה\"ב וגם עכשיו לנשמות גבוהות כרשב\"י וחביריו שעז\"א סוד ה' ליריאיו<sup data-n=\"9608\">123</sup> כו' (ואעפ\"י שיש סוד סתום שאינו בא לגילוי לעולם (ונק' רזא דרזין<sup data-n=\"9609\">124</sup> שאין יין דבינה<sup data-n=\"9610\">125</sup> [מ]וצא סוד זה לגילוי כלל) כמו בחי' שכל הנעלם מכל רעיון [ה]נ\"ל גם הוא יתגלה לע\"ל בעוה\"ב שזהו בחי' תענוג עצמי המורגש בהשגה דבינה כו' כנ\"ל).\n<span data-k=\"pg\">תרנא</span> ּ<b>אך</b> הענין הוא כידוע שזה שבא החכמה מאין ליש אינו אלא ע\"י בחי' צמצום והסתר אור העצמות בתחלה ואח\"כ יאיר אור שנק' הארה דהארה אז יוכל להיות גם התהוות החכ' מאין ליש, כמו בכל בריאה מאין ליש שא\"א להיות התהוות בע\"ג מבבע\"ג אם לא ע\"י צמצום והסתר העצמות כמא' כברייתו ש\"ע ברישא חשוכא<sup data-n=\"9611\">126</sup> כו' שהוא הצמצום דשם אלקים כידוע והוא מ\"ש בראשית ברא אלקים<sup data-n=\"9612\">127</sup> דוקא. וז\"ש ישת חושך סתרו<sup data-n=\"9613\">128</sup> בחי' העלם וצמצום הראשון שמסתיר א\"ע כמ\"ש ומשה נגש אל הערפל<sup data-n=\"9614\">129</sup> דוקא אשר שם האלקי' כו' שאלקים זה הוא [בחי'] הגורם להיות התהוות אור דחכ' שנק' אור צח כו' שעז\"א יהי אור אחר שהי' חושך והעלם בתחלה כמ\"ש והארץ היתה<sup data-n=\"9615\">130</sup> כו' וחושך ע\"פ תהום ורוח אלקים כו' כידוע. וא\"כ מאחר שנתעלם ונתצמצם כל עיקר אור העצמות דעה\"ע הנ\"ל ודאי שכל עיקר",[["9601","116","<b>שכל הנעלם מכל רעיון</b>: נסמן לעיל בפ' תצוה שמא, ד."],["9602","117","<b>אור צח. . אוכם הוא</b>: ראה ת\"ז ת\"ע (קלה, ב). לעיל פ' שמות יב, ב הערה 548."],["9603","118","<b>אנת עילאה על כל עילאין</b>: ת\"ז שם. ראה גם לעיל פ' בשלח קפד, ג."],["9604","119","<b>מחה\"ק</b>: חט: מח' סתימאה הקדומה."],["9605","120","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["9606","121","<b>במקומה</b>: חט: במקורה."],["9607","122","<b>תמצא בהעלם וגילוי</b>: ט: והעלם תמצא בגילוי."],["9608","123","<b>סוד ה' ליריאיו</b>: תהלים כה, יד. ראה גם סוטה ד, ב. לעיל פ' בשלח קסז, ב."],["9609","124","<b>רזא דרזין</b>: ראה זהר בראשית מא, א."],["9610","125","<b>יין דבינה</b>: ראה גם לעיל פ' ויקהל שצ, ב. וש\"נ."],["9611","126","<b>כברייתו ש\"ע ברישא חשוכא</b>: שבת עז, ב (כגי' רש\"י)."],["9612","127","<b>בראשית ברא אלקים</b>: בראשית א, א. ראה גם לעיל פ' שמות ל, ב. וש\"נ."],["9613","128","<b>ישת חושך סתרו</b>: תהלים יח, יב. ראה גם לעיל פ' בא קכג, ג ובהערה 445."],["9614","129","<b>ומשה נגש אל הערפל</b>: יתרו כ, יח."],["9615","130","<b>והארץ היתה</b>: בראשית א, ב."]]],[2300550344,"[האור] <b>והשפע</b> העצמית נשאר למעלה בעצמות הא\"ס שנק' מאור כו' בבחי' ההעלם דעצמות ולא יצא ונמשך למטה בגילוי מן ההעלם רק אפס קצהו שמתצמצם באור החכ' דתורה בפנימי' וחיצוני' שבה הנ\"ל, אבל בעצמות עה\"ע לית מחתב\"כ גם עתה (רק בעוה\"ב יתגלה מן ההעלם<sup data-n=\"9616\">131</sup> [דעצמו' ממש כי יוסר אז בחי' הצמצום] הראשון דשם אלקי' דחושך וערפל סתרו הנ\"ל וזהו בחי' התענוג של עצמות ממש הבא במורגש לנשים<sup data-n=\"9617\">132</sup>.\n<b>והנה</b> הגם שמע[צמות] דעה\"ע הנ\"ל לא בא בגילוי במציאות יש ממש אפי' באור דחכ' מאחר שאין יו\"ד דחכמה בא רק אחר הצמצום דעיקר אות הע'<sup data-n=\"9618\">133</sup> כנ\"ל, מ\"מ קצת גילוי יש גם [מ]עצמות דאור הכתר הנ\"ל רק שאינו בא בכלל השגה ותפיסא מאחר שאמר דלית מח\"ת כלל אלא הוא [בא] בדרך העלם דחכ' שנק' מ\"ה דחכ' כח מ\"ה<sup data-n=\"9619\">134</sup> כמו מה פשפשת<sup data-n=\"9620\">135</sup> כו', והוא הנק' דרך שלילה לבד כו'<sup data-n=\"9621\">136</sup> שבא בל\"ת דוקא בלאו שקודם להן כו'. דהנה יש ב' מיני השגה א' בהשגה שמשיג את השכל המושג בהבנה ותפיסא ממש והוא ע\"י המשכה דחכ' מאין ליש ממש כנ\"ל, והב' השגה בדבר שאינו מושג ומובן בשכל כלל, ואמנם אם אין הדבר בא בגדר שכל המושג האיך יתכן לומר בו ענין השגה. הענין הוא דהשגה זו אינו רק מה שמשיג איך הדבר אינו מושג שגם זה יחשב בכלל ההשגה כמו ענין מה פשפשת כו' מה ידעת, שזהו אחר שבא למעלה מכל[י] ההשגה מצד עומק המושג וקוצר המשיג עד שלא יכילנו כלל אז יתכן לו' הלשון מה פשפשת כו' שישיג עכ\"פ הפלאת הדבר איך שאינו מושג כו', וקודם שיבא לבחי' עונג<sup data-n=\"9622\">137</sup> הדבר נראה לו כמשיג ממש. ואמנם אם הדבר נסתר ונעלם לגמרי שלא יפול בו ענין השגה כלל וכלל [כשכל] הנעלם מכל רעיון כו'<sup data-n=\"9623\">138</sup> לגמרי לא יתכן לומר גם מה פשפשת כו' דהיינו גם זו שאיך הוא בהפלאה מן השגה<sup data-n=\"9624\">139</sup> כו'. ונמצא שבבחי' מ\"ה דחכ' כמו מה פשפשת שהוא בחי' הביטול מן ההשגה שקדמה יש בו קצת ידיעה בדבר [ה]מוסתר ומופלא רק שזהו [ידיעה] הבא בדרך <span data-k=\"pg\">1304</span> ּ שלילה לומר מה פשפשת כו', רק בהעדר השגה [ה]ראשונה כו' זה עצמו יחשב קצת ידיעה באפס קצה דבר המופלא אחר שיודע מה שאינו יודע משא\"כ כל מופלא<sup data-n=\"9625\">140</sup> ממנו לגמרי כו' וד\"ל.\n<b>ויובן</b> זה במשל השגת מהות הרוחני[ות] שא\"א שישיג[ו]הו במהותו ממש כ\"א [ב]דרך שלילה לבד, והוא מה שיודע הפשט[ת] הרוחניות מן הגשם לבד בכל פרטי התואר של הגשם איך שהרוחני[ות] מופשט ומושלל [מכ\"ז, אע\"פ שלא ראה והשיג",[["9616","131","<b>ההעלם</b>: בתו\"ח כאן נכפלו עוה\"פ התיבות: רק אפס. . וחיצוני' שבשו\"ה ההעלם."],["9617","132","<b>לנשים</b>: חט: לנש\"י."],["9618","133","<b>אות הע'</b>: שם: אור העצמות."],["9619","134","<b>דחכ' כח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א."],["9620","135","<b>מה פשפשת</b>: זהר בהקדמה ב, א."],["9621","136","<b>כו'</b>: ט: ליתא."],["9622","137","<b>עונג</b>: חט: עומק."],["9623","138","<b>כו'</b>: ח: ליתא. ט: חסר."],["9624","139","<b>השגה</b>: ח: ההשגה. ט: המושג."],["9625","140","<b>כל מופלא</b>: חט: [כ]שמופלא."]]],[2300550367,"במהות הרוחניות כלל, עכ\"ז יקרא שלילה זו שיודע בהפלאת הרוחניות איך שהוא מושלל] מן הגשם בשם קצת השגה בערך מהות הרוחני (וכן בידיעת השכל ע\"י המשל שאעפ\"י שאינו משיג למהות השכל ממש רק אפס קצהו נודע לו ע\"י התלבשותו במשל (שהוא כחומר לצורה שיובן קצת איכות הצורה מחומרו אחר הפשטת [המשל] מן הנמשל שזהו כמו הפשטת רוחנית מגשמיות) שאינו אלא כמו הרמז שמרמז על עצם השכל כו', וכה\"ג יובן גם במהות ועצם הנפש הרוחני' שא\"א שיושג מהותה ממש כ\"א [ב]דרך שלילה לבד והוא בדבר המנגד לו ממש כמו שאם יעשה דבר נגד רצונו העצמי' שלא יוכל לסובלו כלל, ומזה יבינו אפס קצה מהותו במה שהוא היפך ומושלל מדבר זה השנאוי לו ביותר שמסתמא זהו נגד נקודת עצמותו ממש (כמו שיבינו למהות הרוחני קצת מהיפוכו ושלילותו מן הגשם המנגדו כו'). משא\"כ במה שרצון הנפש נמשך ומתקשר בו אין [מ]זה עדיין השגה במהותו כלל כי אין המשכת רצון זה בדבר האהוב לנפשו רק חלק א' וקטן מעצם ומהות הנפש, ולא שהוא נחשב מהות ועצמות ממש. ונמצא שבבחי' השלילה שלו מהיפוך רצונו השנאוי לו מאד יותר יובן ויושג מעצם מהותו ממה שמושג מדבר האהוב לו כו', וזהו משל להבין בענין לאו דל\"ת שנגד רצונו שיושג מזה יותר במהו\"ע [ממ\"ע] שהן גילוי רצונו (כמשי\"ת).",[]],[2300550072,"<b>ביאור על התורה פ' פקודי<sup data-n=\"9626\">141</sup> </b>\n<b>ובכ\"ז</b> יובן שרש ענין השס\"ה ל\"ת שהוא דבר שנגד רצונו ית' כמו לא תאכל חלב ודם וכה\"ג אעפ\"י שאינו רק שב ואל תעשה לבד יש בזה שרש עליון יותר מן המ\"ע, דהיינו ששרש הל\"ת הוא למעלה מכל ההשתל' הבא בבחי' גילוי אור מן ההעלם מאין ליש בחו\"ב כו' שאינו אלא אחר הצמצום והעלם דעצמות כנ\"ל, אבל בבחי' העלם דעצמות ממש הוא שבא בלאו דל\"ת דוקא, להיותו רק בבחי' שליל[ה] במה שהוא ית' מושלל ומופשט מכל דבר כזה<sup data-n=\"9627\">142</sup> המנגד אליו שע\"כ ציוה עליה רק בל\"ת שלא יהי' דבר זה פוגם ומסתיר לאור [ה]עצמ[ו]ת ממש כו' (וכמ\"ש הפושעים בי בגופא דמלכא<sup data-n=\"9628\">143</sup> ממש שהוא פנימי' דאור הכתר טרם שמתצמצם באור דחכ' כנ\"ל). ונמצא שאין מקור<sup data-n=\"9629\">144</sup> דעצמות בא שם בבחי' גילוי אור במ\"ע כ\"א בבחי' העלם שזהו [ב]העדר היפוכו לבד שהוא רק בחי' הביטול בטל רצונך<sup data-n=\"9630\">145</sup> כו', שאינו רק שלא יהי' מסתיר ומנגד לקדושה האלקי' לבד בשב ואל תעשה כמו לא תלבש שעטנז<sup data-n=\"9631\">146</sup> ולא תאכל חלב",[["9626","141","<b>ביאור. . פקודי</b>: ניתוסף ע\"פ ד."],["9627","142","<b>דוקא. . רק. . כזה</b>: ט: ליתא."],["9628","143","<b>הפושעים בי בגופא דמלכא</b>: ישעי' סו, כד. ראה זהר יתרו פה, ב. עט\"ר ע' 132 ואילך. לעיל פ' תצוה שמג, ב הערה 849."],["9629","144","<b>מקור</b>: חט: אור."],["9630","145","<b>בטל רצונך</b>: אבות פ\"ב, מ\"ד."],["9631","146","<b>לא תלבש שעטנז</b>: תצא כב, יא."]]],[2300550104,"ודם וכה\"ג, שאינו אצלו<sup data-n=\"9632\">147</sup> מניעת המעשה הרע שלא יסתיר פנימי' ועצמי' שלו ויוכל לשכון בבחי' מ\"ה דחכ' שהוא הביטול י\"ה<sup data-n=\"9633\">148</sup> דלאו דל\"ת יותר מאור הנמשך במ\"ע, מטעם הנ\"ל שבדרך שלילה יוכל להיות מבחי' אור דעצמות יותר מבחי' <span data-k=\"pg\">תרנב</span> ּ הגילוי מאין ליש דח\"ע. וזהו משום דמלמעלה למטה הלאו קודם להן שהוא י\"ה דל\"ת שלמעלה מו\"ה דמ\"ע וע\"כ א' על ל\"ת הנסתרות לה' אלקינו מפני שהאור בא בדרך נסתר להיותו עדיין למעלה מההשתל' דחו\"ב כנ\"ל וד\"ל [ב]ענין ישת חשך סתרו דברישא חשוכא כו'.\n<b>(וזהו</b> בארץ לא זרועה<sup data-n=\"9634\">149</sup> שלא דל\"ת זרועה בארץ קודם לאור החסדים דמ\"ע. וזהו ג\"כ מ\"ש ששם עלו שבטים שבטי י\"ה<sup data-n=\"9635\">150</sup> על הביטול רצון דל\"ת דוקא ששרשם במקור די\"ה טרם שמתצמצם אור הכתר בחו\"ב אז נק' עלי' לשבטי י\"ה דחו\"ב שנק' נסתרות לה' אלקינו, ואח\"כ עדות לישראל להמשיך שם הוי' במ\"ע שזהו והנגלות לנו לשמור ולעשות שלמטה מן הנסתרות כי בחי' הנסתרות שהוא בבחי' מהו\"ע ית' לא יוכל לבא למטה לשכון בבחי' כלי ממש כמו מ\"ע אלא רק בבחי' השלילה לבד, והוא כמו במ\"ה דחכ' מה פשפשת כו' והוא הלאו דל\"ת שקודם להן דמ\"ע כנ\"ל וד\"ל (או פי' עדות לישראל להודות לשם ה' היינו להודות בבחי' ביטול דמ\"ה דחכ' טרם שבא[ה] מאין כענין מ\"ה פשפשת כו' שע\"י הל\"ת דוקא נמשך בחי' הביטול והודיה דמ\"ש<sup data-n=\"9636\">151</sup> ממש בהיות שאין מסתיר ומנגד כו' וד\"ל (וכמ\"ש במ\"א ע\"פ ולא תחללו את שם קדשי<sup data-n=\"9637\">152</sup> ונקדשתי [כו' דמיד שלא תחללו בחלל וחסרון ופגם דל\"ת כנ\"ל אזי ממילא ונקדשתי] בקדוש[ה] דמ\"ע לפי שיש בכלל מאתים מנה<sup data-n=\"9638\">153</sup> מטעם הנ\"ל וד\"ל). וזהו אחר שעלו שבטי י\"ה למעלה ממקור ההשתל' דחו\"ב כנ\"ל אזי נק' עדות לישראל כו', פי' עדות הוא ע[ל] ד[בר] הנסתר ונעלם דוקא לזה צריך עדות עדים שיודעים מדבר זה הנסתר מעין כל, אבל בדבר הנגלה ונראה לעין כל א\"צ עדות כלל, וכך יובן במ\"ש כאן עדות לישראל להודות לשם ה' הנסתר ונעלם שהוא בחי' עה\"ע עצמו כל<sup data-n=\"9639\">154</sup> שנק' סדכ\"ס דלית מחת\"ב כלל וע\"ז צריך עדות וישראל הם עדים ע\"ז כמ\"ש אתם עדי<sup data-n=\"9640\">155</sup> כו' (כי ישראל עלו במח'<sup data-n=\"9641\">156</sup> ס[תימאה] סדכ\"ס כו'), והיינו על בחי' הנסתרות לה' אלקינו בחי' י\"ה שהוא מלובש בלאו דל\"ת דוקא כו', אבל בחי' הנגלות לנו ולבנינו כו' שהן המ\"ע א\"צ עדות כלל (ועכ\"ז הרי המ\"ע נק' עדות כמ\"ש אלה העדות והחוקים<sup data-n=\"9642\">157</sup> כו' וכתיב עדות ה' נאמנה<sup data-n=\"9643\">158</sup> כו' כי מ\"ע בו\"ה הנגלות הן בחי' עדות על הנסתרות די\"ה בל\"ת כו').",[["9632","147","<b>אצלו</b>: חט: אלא."],["9633","148","<b>י\"ה</b>: גדט: זה."],["9634","149","<b>בארץ לא זרועה</b>: ירמי' ב, ב."],["9635","150","<b>ששם עלו שבטים שבטי י\"ה</b>: תהלים קכד, ב."],["9636","151","<b>דמ\"ש</b>: חט: דמ\"ה."],["9637","152","<b>ולא תחללו את שם קדשי</b>: אמור כב, לב. ראה גם מאמרי אדה\"א במדבר ח\"ה ע' א'תשפב. והנסמן לעיל פ' תצוה שנז, ב."],["9638","153","<b>שיש בכלל מאתים מנה</b>: ב\"ק עד, א."],["9639","154","<b>כל</b>: חט: הנ\"ל."],["9640","155","<b>אתם עדי</b>: ישעי' מג, י."],["9641","156","<b>ישראל עלו במח'</b>: ראה ב\"ר פ\"א, ד. הנסמן לעיל פ' שמות לב, ב. מאמרי אדה\"א במדבר ח\"ג ע' א'קמב."],["9642","157","<b>אלה העדות והחוקים</b>: ואתחנן ד, מה."],["9643","158","<b>עדות ה' נאמנה</b>: תהלים יט, ח."]]],[2300550136,"<b>וזהו</b> הטעם דשמי עם י\"ה בגימ' שס\"ה ל\"ת שנק' שמי בעצם שהוא עיקר השם דהוי' שהוא בבחי' ההעלם והסתר דעצמות שקדם לבחי' אור דחכמה שנמשך אחר הצמצום כו', וזהו בחי' הלאו דל\"ת שקדם להן דמ\"ע מטעם הנ\"ל, וזכרי עם ו\"ה שזהו<sup data-n=\"9644\">159</sup> בחי' הנגלות לנו כו' בתו\"מ שאינו אלא זכרון שם העצמ[ו]ת ממש כו' כנ\"ל בפי' קורא בשמותיו כו'. ולכך ע\"י תו\"מ הנגלות לנו נק' עדות לישראל על בחי' נסתרות לה' אלקינו שבשמי עם י\"ה כו', כי העדות הוא בא בגילוי להעיד על בחי' ההעלם והנסתר כנ\"ל וזהו דאורייתא סתים וגליא<sup data-n=\"9645\">160</sup> כידוע וד\"ל (וזהו שס\"ה ל\"ת הן שס\"ה גידים<sup data-n=\"9646\">161</sup> שהן הצנורות הנעלמים שמחברים מבחי' המקיפים בעצם הנפש שעי\"ז יוכל להיות אח\"כ חיבור הצורה בחומר הגשמי שנק' או\"כ שהן הרמ\"ח מ\"ע (ולכך א' תחלה סו\"מ ואח\"כ וע\"ט<sup data-n=\"9647\">162</sup> דהא בהא תליא [כו']), וכמו הצורה המלובשת בחומר <span data-k=\"pg\">1306</span> ּ הוא רק מעין ודוגמא דעצמות הנפש הנעלם שם כמו ידים<sup data-n=\"9648\">163</sup> ועורקים שמהציור דחומר יושג ויובן בהעלם כל מה שנעלם בעצמות כו' וכנ\"ל בהבנת עצם השכל מן המשל שנק' חומר [ל]צורה [ה]נעלמת בו, לפי שהמשל מעין ודוגמא של העצמות כו'. אך אין זה [נק'] ידיעה והשגה שבדרך שלילה לבד אלא דוקא באיכות הפשטות צורה הרוחניות מן החומר המלבישו אעפ\"י שנעשה בציור גשמי [כ]דוגמתו ממש כמו בצלם אדם בציור גופו כו', ויובן זה למעלה ג\"כ בבחי' התלבשות אלקות בעולמות שמחיה את כולן מאין ליש בציור אדם באברים בעיני' ואודני' דשכינתא כו') ומחומר זה נראה הצורה כו' האלקית בבחי' כח הפועל בנפעל כצורה בחומר שאינו רק בדוגמא בעלמא לגבי עצמות אור המל' כמו שהוא באצי' ממש. אך מ\"מ<sup data-n=\"9649\">164</sup> אין ערוך לך<sup data-n=\"9650\">165</sup> כו' שגם החיות אלקי שבעולמות אין לו ערוך כו' כידוע, הרי זהו מה שמשיגים הפלאות עיקר עצמות אור המל' שנק' סוכ\"ע בפרט איך שהוא רק קדוש ומושלל מכל תואר המשכה להחיות בע\"ג כמו חי ולא בחיים<sup data-n=\"9651\">166</sup> כו', זהו כמו שמשיגים השלילה והפשטות דרוחני' על הגשם, והגם שנק' ידיעה במקצת בדרך שלילה לבד אך זהו גבוה יותר מהשגת המהות דממכ\"ע וכמו\"כ הוא בלבוש דמשל לנמשל ממ\"ע ול\"ת הנ\"ל וד\"ל.\n<b>ובזה</b> יובן ג\"כ הטעם במא' דכד אתכפי' סט\"א דוקא אסתלק יקרא כו' הגם שאין כל מקור אחיזה ויניקה דחיצונים תופס מקום כלל כשממית בהיכל מלך כו'. אך הנה ידוע דשרש ההסתר וצמצום היותר אחרון דק\"נ נק' חשך גמור הוא בצמצום הראשון שלפני ההשתל' דהיינו בבחי' חשך סתרו",[["9644","159","<b>שזהו</b>: ט: רמ\"ח מ\"ע שהוא."],["9645","160","<b>דאורייתא סתים וגליא</b>: ראה זהר אחרי עא, ב. עג, א. וראה גם לעיל פ' תצוה שמא, ג."],["9646","161","<b>שס\"ה ל\"ת הן שס\"ה גידים</b>: זהר וישלח קע, ב. וראה גם לעיל פ' בא קג, ג."],["9647","162","<b>סו\"מ. . וע\"ט</b>: תהלים לד, טו."],["9648","163","<b>שם כמו ידים</b>: ט: שבגידים."],["9649","164","<b>מ\"מ</b>: חט: מ\"ש."],["9650","165","<b>אין ערוך לך</b>: ברכת יוצר לשבת. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תקמד ואילך. דברים ח\"ג ע' תתקפב."],["9651","166","<b>חי ולא בחיים</b>: נסמן לעיל פ' תצוה שכו, ד."]]],[2300550168,"שקדם לאור דחכ' הנ\"ל כמ\"ש ואלה המלכים<sup data-n=\"9652\">167</sup> כו' לפני מלוך כו' כידוע, וע\"כ בהיפוך החושך הגס דסט\"א למטה נעשה כך בדוגמא למעלה בחושך והעלם העליון שנהפך הוא עצמו [ל]אור שזהו יתרון האור הרבה מגופו של אור הבא אחר החושך וצמצום. וז\"ש דכד אתכפיא או אתהפכא כו' שזהו היפך חשוכא לנהורא ומרירו למיתקא<sup data-n=\"9653\">168</sup> כמו ע\"י תשובה אמיתי' שנהפך הרע עצמו לטוב, שעי\"ז הקללה עצמה נהפך לברכה והמות עצמו נהפך לחיים כו', ע\"כ אסתלק יקרא כו' שזה[ו] עילוי האור [ה]נק' יקרא דקוב\"ה עצמו שזהו עה\"ע במעלה ומדריגה יתירה שלא יוכל להיות ע\"י ההשתל' כלל כמ\"ש אפי' אור צח כו' משום דלמת\"ב כלל כנ\"ל. והיינו ענין הנ\"ל בל\"ת שגבוה ממ\"ע שאין האור דח\"ע<sup data-n=\"9654\">169</sup> מגיע לשם כלל (וראי' לזה מן העוה\"ב שגם שע\"י מצות מעשיות דוקא בא השכר בעוה\"ב כמ\"ש כ\"י יש להם<sup data-n=\"9655\">170</sup> כו' לפי שכולם צדיקים במצות, אך עיקר [ה]עוה\"ב הוא רק גילוי אור דע[צמו' א]א\"ס ממש שלא ע\"י העלם והסתר כלל וכלל וכמ\"ש ולא יכנף עוד כו' (וכמו שלע\"ל יוציא חמה מנרתקה<sup data-n=\"9656\">171</sup> [כו' והוא נרתק דשם אלקי' שמסתיר לשם הוי'] שהוא בחי' אלקי' דצמצום הראשון) וכתיב הנה אלקינו זה<sup data-n=\"9657\">172</sup> ממש, ואין זה רק ע\"י [היפך] החושך גמור למטה ע\"י תשומע\"ט בעוה\"ז באתכפיא ואתהפכא ולכך אמר דכל מאן דלא מהפך<sup data-n=\"9658\">173</sup> חשוכא לנהורא בהאי עלמא דוקא לית לי' חולקא [בההוא עלמא] בעוה\"ב אע\"פ שיש בידו תו\"מ הרבה וד\"ל (ואע\"פ שיזכה לגילוי רזין וסודות התורה בג\"ע וכמו בימוהמ\"ש שיתגלו כל טעמי תורה ומצות<sup data-n=\"9659\">174</sup> כמו שהן למעלה ממש וכמ\"ש ולא ילמדו כו' <span data-k=\"pg\">תרנג</span> ּ כי כולם ידעו אותי<sup data-n=\"9660\">175</sup> כו' אין זה מגיע רק בהעלם דח\"ס חכ' שבכתר שנק' אור צח שיוכל לבוא לגילוי לנשמות ואמנם הרי אוכם הוא לגבי עה\"ע עצמו שיתגלה בעוה\"ב וד\"ל).\n<b>ואחכ\"ז</b> יובן בדרך כלל ענין הפ' הזאת במ\"ש אלה פקודי המשכן משכן העדות כו', דהנה מה שכפל לומר ב\"פ משכן סתם ומשכן העדות זהו ענין ב' מדרגות הנ\"ל בל\"ת ומ\"ע שהן הנסתרות והנגלות שבשם ה' כנ\"ל. דמ\"ש המשכן סתם זהו בחי' תו\"מ הנגלות לנו ולבנינו כו' שהוא בו\"ה דשם הוי' כנ\"ל שנק' משכן סתם ע\"ש בחי' גילוי שכינה בתחתונים דוקא בכל פרטי המצות ביחו\"ע דקוב\"ה ושכינתי' שבא למטה בארץ וכנ\"ל בפי' שמות בארץ כו', ומ\"ש משכן העדות זהו בחי' נסתרות די\"ה שבלאו דל\"ת כו' (כמשי\"ת). והנה תחלה יש להבין ענין המשכן סתם מ\"ש אלה פקודי המשכן מהו ענין אלה ל' רבים כו', דהנה כתי' שאו מרום עיניכם וראו מי ברא אלה<sup data-n=\"9661\">176</sup> [פי'] מי הוא בינה<sup data-n=\"9662\">177</sup>",[["9652","167","<b>ואלה המלכים</b>: נסמן לעיל פ' יתרו ער, ד הערה 67."],["9653","168","<b>היפך חשוכא לנהורא ומרירו למיתקא</b>: נסמן בהערה 173."],["9654","169","<b>דח\"ע</b>: ח: דמ\"ע. ט: מטושטש."],["9655","170","<b>כ\"י יש להם</b>: סנהדרין ר\"פ חלק (צ, א)."],["9656","171","<b>שלע\"ל יוציא חמה מנרתקה</b>: ראה ע\"ז ג, סע\"ב. לעיל פ' שמות לט, ב. וש\"נ."],["9657","172","<b>הנה אלקינו זה</b>: ישעי' כה, ט."],["9658","173","<b>דכל מאן דלא מהפך</b>: ראה זהר בהקדמה ד, א. לעיל פ' שמות ט, א. וש\"נ."],["9659","174","<b>בימוהמ\"ש שיתגלו כל טעמי תורה ומצות</b>: נסמן לעיל פ' תצוה שנד, ג."],["9660","175","<b>ולא ילמדו. . אותי</b>: ירמי' לא, לג."],["9661","176","<b>שאו מרום עיניכם. . אלה</b>: ישעי' מ, כו."],["9662","177","<b>מי הוא בינה</b>: נסמן לעיל תמג, ד."]]],[2300550200,"שנק' אם הבנים<sup data-n=\"9663\">178</sup> שהוא השגת השכל שמוליד את המדות שהן ששה וכל א' כלול מוי\"ו והיינו מספר אלה<sup data-n=\"9664\">179</sup> סופ\"ו<sup data-n=\"9665\">180</sup> עולה ל\"ו מספר אלה כידוע. וזהו מי ברא אלה בחי' ההשגה והתבוננות דבינה שנק' מי דקיימא לשאלה<sup data-n=\"9666\">181</sup> כמו מי הוא זה כו' הוא שברא והוליד לאל\"ה שהן ו\"ק דז\"א כו', והוא מ\"ש לך ה' הגדולה והגבורה<sup data-n=\"9667\">182</sup> כו' עד כי כל כו' שהוא בחי' יסוד<sup data-n=\"9668\">183</sup> שהן ו' מדות עליונות דאצי' חג\"ת נה\"י שכולם בטלים ונכללים בבינה אימא עילאה<sup data-n=\"9669\">184</sup> דאצי' שז\"ש לך ה' לך הם מספר נש\"ב<sup data-n=\"9670\">185</sup>, וע\"כ אמר לך הוי' הגדולה כו' ולז\"א שאו מרום כו' (שזהו פסיעה לבר שהוא רגל הקצר כו'<sup data-n=\"9671\">186</sup> זעירא שבה' עילאה דבינה<sup data-n=\"9672\">187</sup> דאצי' בהיותה בבחי' עיבור כמ\"ש בזהר בלק ע\"פ כי מראש צורים<sup data-n=\"9673\">188</sup> כו'). וזהו אלה אותיות לאה<sup data-n=\"9674\">189</sup> דלאה ילדה ו' בנים<sup data-n=\"9675\">190</sup> והוא בחי' חיצוני' דבינה שנק' מל' דתבונה<sup data-n=\"9676\">191</sup> כו' ואח\"כ אמר לך ה' הממלכה שהוא בנין המל' שה[י]א מדת המל' שכלולה בו\"ק דז\"א כו' ונבנית בבנין פרצוף בפ\"ע כידוע בענין הנסירה<sup data-n=\"9677\">192</sup> כו', וזהו ואחר ילדה בת ושמה דינה<sup data-n=\"9678\">193</sup> כו' שהוא בחי' מל'<sup data-n=\"9679\">194</sup> שנק' אדנ\"י<sup data-n=\"9680\">195</sup> אותיות דינא<sup data-n=\"9681\">196</sup> שנק' דינא דמלכותא<sup data-n=\"9682\">197</sup> כו' הוא בחי' יחו\"ת דבשכמל\"ו<sup data-n=\"9683\">198</sup> שנמשך מדלי\"ת רבתי דאחד<sup data-n=\"9684\">199</sup> כידוע וד\"ל.\n<b>וביאור</b> הענין יובן בכללות בבנין<sup data-n=\"9685\">200</sup> דתו\"מ שמבואר למעלה בבחי' הנגלות לנו כו' שהן ו\"ה דשם הוי' הוי\"ו הוא בבחי' המדות שבתו' דאורייתא מח\"ע נפקת היינו בחי' הוי\"ו מדות דז\"א הנ\"ל כמ\"ש להבדיל בין טמא לטהור<sup data-n=\"9686\">201</sup> כו', ולכך נק' תורה ענין הוראה<sup data-n=\"9687\">202</sup> להבדיל בין טו\"ר בבחי' החכ' שבמדות והן שית[א] סדרי משנה<sup data-n=\"9688\">203</sup> בכלל סדר זרעים בבחי' החסד<sup data-n=\"9689\">204</sup> כו' (כמשי\"ת). והמצות הן בבחי' ה' אחרונה דשם הוי' שנק' מצות המלך<sup data-n=\"9690\">205</sup> שבא בחי' אור דתורה להשפיע בכלים מכלים שונים כנ\"ל בענין כי נר מצוה ותורה אור ומפני זה ת\"ת כנגד כולן כו', וזהו [ו]התורה והמצוה שהוא יחוד זו\"נ דאצי' שנק' יחוד קוב\"ה ושכינתי'<sup data-n=\"9691\">206</sup> בכלל ובפרט בכל מצוה<sup data-n=\"9692\">207</sup> ומצוה כו' (והיינו ענין הנ\"ל במי ברא אל\"ה שהן הוי\"ו מדות דז\"א שנמשכים ומשפיעים לבחי' המל' ה' אחרונה שנק' דינא דמלכותא שז\"ש לך ה' הממלכה כו' כנ\"ל). וז\"ש אלה פקודי <span data-k=\"pg\">1308</span> ּ המשכן פי' פקוד\"י",[["9663","178","<b>בינה שנק' אם הבנים</b>: נסמן לעיל בפ' משפטים רצו, ב."],["9664","179","<b>המדות שהן ששה. . מוי\"ו. . מספר אלה</b>: נסמן לעיל שם רצא, ד. וראה לעיל תמח, ג."],["9665","180","<b>סופ\"ו</b>: (ח)ט: דוא\"ו פעמים וא\"ו."],["9666","181","<b>מי דקיימא לשאלה</b>: זהר בהקדמה א, ב."],["9667","182","<b>לך ה' הגדולה והגבורה</b>: דהי\"א כט, יא."],["9668","183","<b>כי כל. . יסוד</b>: ראה זהר בראשית לא, א. לעיל פ' וארא נג, ד הערה 39."],["9669","184","<b>בבינה אימא עילאה</b>: נסמן לעיל פ' תצוה שמט, ג."],["9670","185","<b>לך הם מספר נש\"ב</b>: נסמן לעיל תמג, ד."],["9671","186","<b>כו'</b>: חט: דו[י\"ו]."],["9672","187","<b>שבה\"א עילאה דבינה</b>: ראה פרדס (שער האותיות) שכ\"ז, פ\"ח. הנסמן במאמרי אדה\"א בראשית ע' רלג."],["9673","188","<b>בזהר בלק ע\"פ כי מראש צורים</b>: בלק כג, ט. זהר שם רג, ב. לעיל פ' שמות יט, א. וש\"נ."],["9674","189","<b>אלה אותיות לאה</b>: נסמן לעיל תמג, ד הערה 83."],["9675","190","<b>דלאה ילדה ו' בנים</b>: ויצא ל, כ."],["9676","191","<b>חיצוני' דבינה שנק' מל' דתבונה</b>: ראה שעה\"י קי, ב. מאמרי אדה\"א דברים ח\"א ע' רפג. תו\"ח בראשית כב, א הערה 1."],["9677","192","<b>בנין המל'. . הנסירה</b>: ראה שעה\"י קמא, ב. ובהנסמן לשם."],["9678","193","<b>ואחר ילדה בת ושמה דינה</b>: נסמן לעיל פ' משפטים רצו, ד."],["9679","194","<b>דינה. . מל'</b>: ראה לקו\"ת להאריז\"ל פ' ויצא (ענין בני לאה (צא, ב) בשם הזהר)."],["9680","195","<b>מל' שנק' אדנ\"י</b>: ראה זהר ויקרא יא, א. לעיל פ' וארא עה, ב. וש\"נ."],["9681","196","<b>אדנ\"י אותיות דינא</b>: ראה זהר (רע\"מ) משפטים קיח, א. פינחס רנז, סע\"ב. לעיל פ' בא פח, א. וש\"נ."],["9682","197","<b>דינא דמלכותא</b>: גיטין י, ב."],["9683","198","<b>יחו\"ת דבשכמל\"ו</b>: זהר בראשית יח, ב."],["9684","199","<b>מדלי\"ת רבתי דאחד</b>: ראה ד\"ה זה במאמרי אדה\"א דברים ח\"א ע' רפג. וש\"נ."],["9685","200","<b>בבנין</b>: חט: בענין."],["9686","201","<b>להבדיל בין טמא לטהור</b>: שמיני יא, מז [ושם: הטמא ובין הטהור]."],["9687","202","<b>תורה ענין הוראה</b>: ראה זהר מצורע נג, ב. לעיל פ' שמות יא, א הערה 489."],["9688","203","<b>שית[א] סדרי משנה</b>: נסמן לעיל תמט, ב."],["9689","204","<b>סדר זרעים בבחי' החסד</b>: נסמן לעיל בפ' ויקהל תלט, ד הערה 1913."],["9690","205","<b>שנק' מצות המלך</b>: ראה אסתר ג, ג. לעיל פ' בשלח קסט, ד. וש\"נ."],["9691","206","<b>יחוד זו\"נ. . קוב\"ה ושכינתי'</b>: ראה גם תו\"ח ח\"ש קלח, ג הערה 22."],["9692","207","<b>יחוד קוב\"ה ושכינתי'. . בכל מצוה</b>: נסמן לעיל בפ' תצוה שלט, ב."]]],[2300550232,"כמו ענין פקיד\"ה לתולדה וליחוד דו\"נ כמ\"ש חייב אדם לפקוד [את] אשתו<sup data-n=\"9693\">208</sup> כו', והוא ענין זכרון ופקידה דמשפיע למקבל כמו וה' פקד את שרה<sup data-n=\"9694\">209</sup> כו' ליתן לה הריון לטובה כו' שזהו פקידות עקרות, וכן בענין הגאולה אמר פקד פקדת\"י אתכם<sup data-n=\"9695\">210</sup> כו' וכה\"ג. וכך יובן כאן ג\"כ בדרך כלל במ\"ש אלה פקודי המשכן שמשכן זה סתם הוא בחי' המל'<sup data-n=\"9696\">211</sup> משכן דלתתא בחי' ה' אחרונה דשם הוי' שמתייחדת בבעלה שהוא בוי\"ו דמדות דז\"א כנ\"ל וד\"ל בענין התו\"מ, שהוא יחוד דזו\"נ למעלה ולמעלה היינו יחוד קובה\"ו בכנ\"י ע\"י המצות מעשיות בכל מצוה ומצוה בפרטיות כנ\"ל. וזהו ענין הפקידה למשכן שהן כנ\"י בבחי' מצות המלך לפקוד אותם דהיינו ביחוד ו\"ה הנגלות לנו בתו\"מ כנ\"ל בענין לפקוד אשתו ממש ביחוד דו\"נ כו', והמשפיע הוא בחי' המדות [דתו' שהן ו' מדות] דאצי' חג\"ת נה\"י כו' והן ששה סדרי משנה שכל סדר כלול מכל הי\"ס<sup data-n=\"9697\">212</sup> סדר זרעים בבחי' החסד כלול מה\"ס [כו' כ]ו' המדות שכאו\"א כלול מו' שעולה מספר ל\"ו שהוא גימ' דאלה, ולהיות השכינה שורה בישראל נק' משכן כמ\"ש ושכנתי בתוכם ע\"כ אמר אלה פקודי המשכן כלומר אלה הן בחי' הפקודים [ב]יחו\"ע דו\"ע<sup data-n=\"9698\">213</sup> בתו\"מ [הנגלות] כו' וד\"ל<sup data-n=\"9699\">214</sup> כי באלה דוקא שהן הו' מדות דתורה הנ\"ל הן כל פקוד\"י היחודים דמשכן שיפקוד לאשתו כו' וד\"ל. וז\"ש אלה ל' רבים כמו מי ברא אל\"ה כי באמת רבים המה כל פרטי היחו\"ע דו\"ה דמצות בכמה אופנים ומדרגות שונים שהרי אנו אומרים על כל מצוה בפרט לשם יחוד<sup data-n=\"9700\">215</sup> והן רמ\"ח מ\"ע ונחלקים לכמה מדרגות פרטיות כידוע וד\"ל.\n<b>והנה</b> כ\"ז הוא בבחי' פקודי המשכן סתם כנ\"ל שזהו בחי' ו\"ה דתו\"מ הנגלות לנו כו' ולכך אמר אלה פקודי כו', אלה משמע לנוכח כשבא הדבר בהתגלות ממש לעין כל רואה אז אומר אלה כלומר לנוכח אל\"ה וכמו מי ברא אלה כו' שהן המדות הבאים בתולדה בגילוי מן ההעלם דבינה כו'. וכ\"מ שנא' אלה ענינו הבא בגילוי לנוכח כו' (וכמו [ו]אלה המשפטים<sup data-n=\"9701\">216</sup> כו' אלה תולדות נח<sup data-n=\"9702\">217</sup> כו' אלה תולדות יעקב יוסף<sup data-n=\"9703\">218</sup> וכה\"ג ולע\"ל א' הגדיל ה' לעשות עם אלה<sup data-n=\"9704\">219</sup> כו' וזהו המשכן הידוע שהוא ה'",[["9693","208","<b>חייב אדם לפקוד [את] אשתו</b>: נסמן לעיל תמד, א."],["9694","209","<b>וה' פקד את שרה</b>: וירא כא, א."],["9695","210","<b>פקד פקדת\"י אתכם</b>: שמות ג, טז."],["9696","211","<b>שמשכן. . בחי' המל'</b>: נסמן לעיל פ' ויקהל תלט, ג הערה 1896."],["9697","212","<b>הי\"ס</b>: חט: הו' סדרי'."],["9698","213","<b>דו\"ע</b>: שם: דו\"ה."],["9699","214","<b>כו' וד\"ל</b>: ח: כנ\"י כו'. ט: כו' כנ\"ל."],["9700","215","<b>אנו אומרים על כל מצוה בפרט לשם יחוד</b>: נסמן לעיל בפ' תצוה שלט, ב הערה 747."],["9701","216","<b>[ו]אלה המשפטים</b>: משפטים כא, א."],["9702","217","<b>אלה תולדות נח</b>: נח ו, ט."],["9703","218","<b>אלה תולדות יעקב יוסף</b>: וישב לז, ב."],["9704","219","<b>הגדיל ה' לעשות עם אלה</b>: תהלים קכו, ב."]]],[2300550263,"אחרונה הנ\"ל. אבל מ\"ש עוד משכן העדות אינו מדבר בבחי' ו\"ה שבא בהתגלות שא\"צ עדות כלל ע\"ד הנגלה לעין כו', אלא מדבר בבחי' משכן דלעילא שהוא ביחו\"ע דאו\"א דאצי' שהן אותיות י\"ה דהוי' שנק' נסתרות לה' אלקינו כו' משום שזהו בבחי' [ה]הסתר וההעלם דחו\"ב מאין ליש בטרם שנולדו המדות שהוא ו' כנ\"ל בפי' לך הוי' הגדולה כו', והוא כמו קודם שמ\"י דבינה ברא אל\"ה כנ\"ל זהו שנק' משכן העדות לפי שע\"ד הנסתר ונעלם צריך עדות כמ\"ש עדות לישראל כו' לפי שעלו שבטי י\"ה בשרשן במזלות דחו\"ב כו'. והוא שרש הל\"ת שהוא בחי' אור הנעלם שבעצמות הכתר שלא יוכל לבא למטה בבחי' כלים מכלים שונים בח\"ע<sup data-n=\"9705\">*220</sup> אלא רק בבחי' הביטול דמ\"ה דחכ', והוא ענין השלילה מפני שמלמעלה <span data-k=\"pg\">תרנד</span> ּ למטה הלאו קודם להן כו' והוא ענין הצמצום הראשון ישת חושך סתרו שלא יוכל להתצמצם כלל באו\"כ וזהו שמי עם י\"ה שס\"ה ל\"ת שלמעלה מו\"ה דמ\"ע כנ\"ל וד\"ל.\n<b>אך</b> הנה עדיין י\"ל בטעם שקוראין בשם משכן העדות, הנה לבד [זה] הטעם [לפי] שהעדות לא שייך רק בדבר הנסתר שהן י\"ה שנק' נסתרות כנ\"ל שאין זה מתיישב עדיין במשמעות הפשוט שאמר אלה פקודי המשכן משכן העדות [דמשמע] דאלה פקודי קאי על משכן העדות ג\"כ מאחר שכוללם יחד ואמר [ה]משכן משכן העדות, משום דיחו\"ע ויחו\"ת שוין ממש משום<sup data-n=\"9706\">220</sup> דבחי' [ה]העלם ובחי' הגילוי שוין קמי' עצמות המאציל, וז\"ש ביום ההוא יהי' ה' אחד ושמו אחד<sup data-n=\"9707\">221</sup> וכמ\"ש כגוונא דאינון מתייחדין לעילא<sup data-n=\"9708\">222</sup> ביחו\"ע דחו\"ב אוף הכי כו', אך צ\"ל עוד טעם שני למה נק' משכן העדות דוקא דעדות זה הוא מלשון עדי וקישוט וכמו ותבואי בעדי עדיים<sup data-n=\"9709\">223</sup> כו' וכמ[\"ש] ויתנצלו את עדיי\"ם<sup data-n=\"9710\">224</sup> כו'. ותחלה י\"ל פי' הפסוק רבבה כצמח השדה נתתיך ותרבי<sup data-n=\"9711\">225</sup> ותגדלי כו' דקאי זה בגלות מצרים שהיו בנ\"י כצמח השדה שצומחים בלי שיעור כלל מצד כח הצומח שבארץ שהוא ר[ך כ]עפר תיחוח ביותר שאז יצמח בריבוי יותר (והוא [היפך ה]מדבר הקשה שאינו מצמיח<sup data-n=\"9712\">226</sup> כלום), כידוע שא\"א להיות התהוות יש מיש כ\"א יש מאין דוקא והוא בבחי' ביטול דיש וגסות לאין בהתכללות בכח הצומח תחלה ברקבון הגרעין בארץ<sup data-n=\"9713\">227</sup> (וכהפסד הזרע בקליטתו<sup data-n=\"9714\">228</sup> וכן באפרוח<sup data-n=\"9715\">229</sup> כידוע) (אז יומשך בו",[["9705","*220","<b>בח\"ע</b>: ג: במ\"ע. דט: כמ\"ע."],["9706","220","<b>משום</b>: ט: ליתא."],["9707","221","<b>ביום ההוא יהי'. . ושמו אחד</b>: זכרי' יד, ט."],["9708","222","<b>כגוונא דאינון מתייחדין לעילא</b>: זהר תרומה קלה, סע\"א."],["9709","223","<b>ותבואי בעדי עדיים</b>: נסמן בהערה 225."],["9710","224","<b>ויתנצלו את עדיי\"ם</b>: נסמן לקמן הערה 242."],["9711","225","<b>רבבה כצמח השדה נתתיך ותרבי</b>: יחזקאל טז, ז."],["9712","226","<b>כ]עפר. . ה]מדבר. . שאינו מצמיח</b>: ראה חולין פח, ב. לעיל פ' יתרו רנה, ד הערה 315."],["9713","227","<b>ברקבון הגרעין בארץ</b>: נסמן לעיל תמד, ב."],["9714","228","<b>וכהפסד הזרע בקליטתו</b>: ראה לעיל פ' תצוה שכ, ג הערה 76."],["9715","229","<b>וכן באפרוח</b>: נסמן לעיל שם הערה 77."]]],[2300550293,"כח הצומח להצמיחו בריבוי בכפלי כפליים כו'. וכן פי'<sup data-n=\"9716\">230</sup> הענין בגלות מצרים שהיו משועבדים שם בתכלית העבודה הקשה וימררו את חייהם<sup data-n=\"9717\">231</sup> בשפלות ורוח נשברה ביותר עד שנעשה ביטול [ה]גסות הלב בתכלית ובא לבחי' אין ממש ע\"י בחי' לב נשבר ונדכה<sup data-n=\"9718\">232</sup> רק כעפר תיחוח כו', אז הי' ענין הצמיחה וריבוי בתולדתן עד שצמחו ורבו ביותר כצמח השדה בלי שיעור וכמ\"ש [ו]כאשר יענו [אותו] כן ירבה<sup data-n=\"9719\">233</sup> כו' ויפרו וירבו ויעצמו במאד<sup data-n=\"9720\">234</sup> כו' עד שהגדילו יותר לזכות לקבלת התו' פב\"פ. וזהו רבבה כצמח כו' ואח\"כ ותרבי ותגדלי יותר כמ\"ש גפן ממצרים תסיע<sup data-n=\"9721\">235</sup> כסו הרים צלה<sup data-n=\"9722\">236</sup> שזהו למעלה גם מן האבות שנק' הרים<sup data-n=\"9723\">237</sup> [כידוע] כמ\"ש ושמי ה' לא נודעתי להם<sup data-n=\"9724\">238</sup> כמו במ\"ת לכנ\"י כו' וד\"ל. ואח\"כ ותבואי בעדי עדיים עדי זה הן הקישוטים שנק' עדי<sup data-n=\"9725\">239</sup> [ו]היינו ב' כתרים דנעשה ונשמע<sup data-n=\"9726\">240</sup> שנמשך לכאו\"א מישראל (מבחי' עטרה שעטרה לו אמו ביום חתונתו זו מ\"ת<sup data-n=\"9727\">241</sup> כו') ע\"י המלאכים עליונים להיות בבחי' עטרה ומקיף על [ה]ראש כאו\"א כו', וכשחטאו בעגל נפסק מהם הכתרים ועדיים הללו כמ\"ש ויתנצלו בנ\"י את עדיים<sup data-n=\"9728\">242</sup> מהר חורב וכידוע.\n<b>ולהבין</b> ביאור ענין העטרה וכתר זה הנה זהו בחי' אור הכת\"ר עצמו שהוא בחי' רצה\"ע שנק' רדכ\"ר<sup data-n=\"9729\">243</sup> כו' שלמעלה מן החכמה שבמוח כמ\"ש כצנה רצון תעטרנו<sup data-n=\"9730\">244</sup> כו', ועטרה זו נעשי' מקישוטין הרבה בכמה מדרגות שונות זו מזו ובכללות זהו כמו ב' עטרות שעטרה לו אמו כו' שהן ב' מיני אבנים טובות <span data-k=\"pg\">1310</span> ּ כשהם וישפה שזה בהיר בעצם הווייתו<sup data-n=\"9731\">245</sup> וזה בהיר בזיכוך<sup data-n=\"9732\">246</sup> עפרותו עד שמתנוצץ בעין ונק' או\"י ואו\"ח<sup data-n=\"9733\">247</sup> כידוע. והיינו ענין הב' כתרים אחד כנגד נעשה בביטול הרצון לקעומ\"ש לעשות רצונו כענין בטל רצונך מפני רצונו כדי שיעשה רצונו<sup data-n=\"9734\">248</sup> כו' וכנגד נשמע שהוא קבלת הרצה\"ע דאהבה ורצון שמצד אה\"ר העצמי' שבכנ\"י מלמטה למעלה ע\"כ זכו שיותן להם ב' כתרים עליונים, ועטרה שעטרה לו אמו (כמשי\"ת<sup data-n=\"9735\">249</sup> משל למלך שעשה ג' עטרות<sup data-n=\"9736\">250</sup> ב' נתן לבניו כו') והוא בחי' אור הכת\"ר הפנימי דרצה\"ע שבו שורה אוא\"ס ממש שנק' רדכ\"ר שמתגלה בבחי' מקיף בעטרה וכתר ע\"ג הראש דכאו\"א מישראל והוא מ\"ש אנכי הוי' אלקיך<sup data-n=\"9737\">251</sup> אנכי מי שאנכי<sup data-n=\"9738\">252</sup> כו' בחי' סדכ\"ס דלא ידע לי' בר איהו<sup data-n=\"9739\">253</sup> כו'. והיינו בחי' הרצה\"פ העצמי ממש שלמעלה גם",[["9716","230","<b>פי'</b>: חט: הי'."],["9717","231","<b>וימררו את חייהם</b>: שמות א, יד."],["9718","232","<b>לב נשבר ונדכה</b>: תהלים נא, יט."],["9719","233","<b>[ו]כאשר יענו [אותו] כן ירבה</b>: שמות א, יב."],["9720","234","<b>ויפרו וירבו ויעצמו במאד</b>: שמות א, ז [ושם: פרו וישרצו וירבו — וראה גם לעיל תמד, ב הערה 96]."],["9721","235","<b>גפן ממצרים תסיע</b>: תהלים פ, ט."],["9722","236","<b>כסו הרים צלה</b>: תהלים שם, יא."],["9723","237","<b>האבות שנק' הרים</b>: ראה ר\"ה יא, א. לעיל פ' וארא עז, ג. וש\"נ."],["9724","238","<b>ושמי ה' לא נודעתי להם</b>: נסמן לעיל פ' יתרו רנא, א והערה 16."],["9725","239","<b>הקישוטים שנק' עדי</b>: נסמן לעיל תמד, ב."],["9726","240","<b>ב' כתרים דנעשה ונשמע</b>: ראה שבת פח, א."],["9727","241","<b>עטרה. . ביום חתונתו זו מ\"ת</b>: שה\"ש ג, יא. תענית כו, ב. ראה מאמרי אדה\"א דברים ח\"ג ע' תתמז בהערה."],["9728","242","<b>ויתנצלו בנ\"י את עדיים</b>: תשא לג, ו."],["9729","243","<b>רדכ\"ר</b>: נסמן לעיל פ' תצוה שנח, ב."],["9730","244","<b>כצנה רצון תעטרנו</b>: תהלים ה, יג."],["9731","245","<b>כשהם. . בהיר בעצם הווייתו</b>: ראה גם לעיל פ' שמות ז, א. וש\"נ."],["9732","246","<b>וישפה. . בהיר בזיכוך</b>: ראה גם לעיל שם ד, ג הערה 195."],["9733","247","<b>כשהם וישפה. . או\"י ואו\"ח</b>: ראה לקו\"ת ראה כז, ד. מאמרי אדה\"א דברים ח\"ב ע' תע. תו\"א תשא קיב, ג."],["9734","248","<b>בטל רצונך. . שיעשה רצונו</b>: ראה לעיל פ' שמות ט, א."],["9735","249","<b>כמשי\"ת</b>: ט: כמו שא'."],["9736","250","<b>משל למלך שעשה ג' עטרות</b>: ראה לעיל פ' תצוה שנ, א. וש\"נ."],["9737","251","<b>אנכי הוי' אלקיך</b>: יתרו כ, ב."],["9738","252","<b>אנכי מי שאנכי</b>: נסמן לעיל פ' יתרו רנד, ג."],["9739","253","<b>דלא ידע לי' בר איהו</b>: נסמן לעיל פ' ויקהל שפח, א."]]],[2300550320,"ממקור השכל וטעם לרצון כו' וד\"ל ואינו בא מוגבל בגילוי אור בכלי כלל ואין בחי' כלי לאור פשוט ועצמי כזה, רק שהוא בא בבחי' ההעלם דמקיף ששורה בעטרה וכתר שע\"ג הראש מלמעלה דוקא שא\"א שיומשך בגילוי אור ג\"כ<sup data-n=\"9740\">254</sup> באור דח\"ס שבמוח כנ\"ל בענין והחכ' מאין כו'. וזהו ענין הקישוט והעדי שע\"ג הראש שקיבלו בנ\"י במ\"ת כנ\"ל ונק' ג\"כ בחי' כתר תורה, פי' בחי' כתר ועטרה המקיף ע\"ג הראש<sup data-n=\"9741\">255</sup> אור החכמה דתורה שגנוז ומלובש רק כעטרה<sup data-n=\"9742\">256</sup> ע\"ג הראש דוקא לפי שזה בא מצד ביטול הרצון כענין בטל רצונך כו' למעלה מן הטעם לגמרי שא\"א שיוגבל בחכמה כו' וד\"ל. וזהו ותבואי בעדי עדיים דהיינו ב' כתרים דנעשה ונשמע נק' עדי[י'] והן מ\"ע ומל\"ת ששמעו במ\"ת ואנכי ולא יהי' לך כוללים כל הרמ\"ח מ\"ע ושס\"ה ל\"ת, ואמנם עדי הכולל כל העדיי' הוא מבחי' רעדכ\"ר שבעצמות אור הכתר שנק' רצה\"פ זהו אינו בא בגילוי רק בבחי' ההעלם שבכתר שקודם לאור והוא בחי' חושך סתרו כו', והיינו בלאו דל\"ת שקודם להן שנק' נסתרות להוי' אלקינו כו', והיינו בלאוין דל\"ת שביו\"ד הדברות כמו לא תרצח<sup data-n=\"9743\">257</sup> כו' ששרשן גבוה ממ\"ע דכבד את אביך וזכור<sup data-n=\"9744\">258</sup> כו' מטעם הנ\"ל וד\"ל.\n<b>ובזה</b> מתורץ ענין מ\"ש אלה פקודי כו' גם על משכן העדות שנק' נסתרות שצריך עדות, דעדות זה ל' קישוט [הוא], וקישוטין הללו היינו ב' כתרים דנעשה ונשמע הנ\"ל שבאים מקיום המצות בעומ\"ש בביטול הרצון שזהו אלה פקודי המשכן סתם שהוא ו\"ה הנגלות לנו לשמור ולעשות, וזהו הכתר דנעשה שמזה יבא ממילא הקישוט דאו\"י במשכן העדות די\"ה דהוי' כנגד נשמע שהוא בל\"ת בלאו שקודם להן שעז\"א עדות לישראל כו', ואין נק' עדות לשון עדי עדיים כ\"א בי\"ה בנסתרות שהוא בל\"ת ששם בא מלמעלה למטה בבחי' ההעלם דכת\"ר עצמו שהוא עטרה ע\"ג הראש כו' וד\"ל (וזהו שבע\"ת גדולים מצדיקים גמורים<sup data-n=\"9745\">259</sup> ע\"י ביטול הרצון הזר בלב נשבר מאד שנמשך על נשמתו מבחי' רעדכ\"ר למחול ולסלוח העון עד שהקטיגור נעשה סניגור<sup data-n=\"9746\">260</sup> כו' וקללה עצמה נהפך לברכה כמו בקללות דבלעם שאמר ויהפוך ה'<sup data-n=\"9747\">261</sup> כו' כי אהבך כו', וז\"ש ברצות ה' דרכי איש<sup data-n=\"9748\">262</sup> ע\"י תשובה שלימה גם אויביו המקטרגים ישלימו עמו כו', וז\"ש בזהר זכאה <span data-k=\"pg\">תרנה</span> ּ ב\"נ דקוב\"ה אתרעי בי'<sup data-n=\"9749\">263</sup> בבחי' רדכ\"ר כו' ונק' נערה אשר חפץ בה המלך<sup data-n=\"9750\">264</sup> כו' (וכמו נתן דצוציתא<sup data-n=\"9751\">265</sup> כו').",[["9740","254","<b>ג\"כ</b>: גט: גם."],["9741","255","<b>הראש</b>: חט: ליתא."],["9742","256","<b>כעטרה</b>: ח: בעטרה. ט: בלבוש דעטרה."],["9743","257","<b>לא תרצח</b>: יתרו כ, יג."],["9744","258","<b>דכבד את אביך וזכור</b>: שם שם, יב. ח."],["9745","259","<b>שבע\"ת גדולים מצדיקים גמורים</b>: ראה ברכות לד, ב. לעיל פ' שמות מא, א. וש\"נ."],["9746","260","<b>שהקטיגור נעשה סניגור</b>: ע\"פ ברכות נט, א."],["9747","261","<b>ויהפוך ה'</b>: תצא כג, ו. ראה מאמרי אדה\"א דברים ח\"ב ע' תרס ואילך [ובהנסמן בריש המאמר שם]. לעיל פ' תצוה שעו, א."],["9748","262","<b>ברצות ה' דרכי איש</b>: משלי טז, ז."],["9749","263","<b>זכאה ב\"נ דקוב\"ה אתרעי בי'</b>: ראה זהר שלח קסא, א. ח\"ש קכט, א."],["9750","264","<b>נערה אשר חפץ בה המלך</b>: ע\"פ אסתר ב, יג. יד. ראה לעיל פ' בא קכה, ד הערה 599."],["9751","265","<b>נתן דצוציתא</b>: ראה שבת נו, ב. לעיל פ' יתרו רסו, ג ובהערה 162."]]],[2300550345,"<b>אך</b> במ\"א מבואר להיפוך מכל הנ\"ל (בפ' יתרו<sup data-n=\"9752\">266</sup> ) דמלמעלה למטה הן קודם ללאו וה[ו]א אנכי שרש רמ\"ח מ\"ע שקדם ללא יהי' לך שהוא שרש הל\"ת ומלמטה למעלה לאו דסו\"מ קודם להן דוע\"ט דמ\"ע כו' (משום דמן המשפיע אל המקבל הוא בא בבחי' מטול\"מ מטי תחלה כמו ורוח אלקים מרחפת כו' נוגע ואינו נוגע<sup data-n=\"9753\">268</sup> כו', ומן המקבל אל המשפיע בחי' רצוא קודם לשוב<sup data-n=\"9754\">267</sup> וראי' מדפיק[ו] דלבא כו'<sup data-n=\"9755\">269</sup>, ולכך ביטול רצון דסו\"מ קודם כו' [ובכאן משמע להיפוך דבחי' אנוכי סדכ\"ס שנק' רדכ\"ר אינו בא רק בבחי' הלאו דל\"ת שהוא בחי' ההעלם דכתר עצמו שקודם לאור כו']. אמנם באמת הכל ענין א' הוא דבבחי' או\"ח הרצוא בביטול רצון זר כו' קודם והוא בחי' כת\"ר דנעשה כו', ועי\"ז נמשך מבחי' המקיף העליון ונעלם יותר דאנכי מי שאנכי הנ\"ל שיאיר מהעלמו ודוקא בבחי' הביטול דלאו דל\"ת כי לא יכילנו שום כלי דמ\"ע כו'. וז\"ש אנכי ולא כו' בדיבור א' נאמרו<sup data-n=\"9756\">270</sup> דמ\"ש אנכי היינו רק במה שלא יהי' לך כו' בסומ\"ר דל\"ת ולא יוכל להתלבש בכלים דמ\"ע כו' וכענין ולא תחללו כו' וממילא ונקדשתי<sup data-n=\"9757\">271</sup> כו'. וזהו מפני שגילוי דאנכי סתימא דכ\"ס בא בבחי' מטי ולא מטי שהוא בחי' מקיף דאו\"ח שעיקר השראתו [רק] בהעלם וביטול הכלי כו' ומקיף כזה בא מצד עלי' דמקבל ברצוא קודם לשוב ו[הוא] כת\"ר דנעשה כו', וזהו הטעם שע\"י יחו\"ת דוקא נעשה יחו\"ע דמשכן העדות כו'.\n<b>והנה</b> יש עוד פי' שלישי<sup data-n=\"9758\">272</sup> בלשון עדי שהוא ענין נצחיי' כמו לעדי עד ימלוך<sup data-n=\"9759\">273</sup> כו' וכן אנו אומרים משובח ומפואר עדי עד<sup data-n=\"9760\">274</sup> כו', וכן א' כ\"מ שנא' נצח סלה ועד<sup data-n=\"9761\">275</sup> אין לו הפסק כלל וכלל<sup data-n=\"9762\">276</sup>, וכמו הכל ירוממוך סלה<sup data-n=\"9763\">277</sup> כו' שזהו בחי' השבח והתהילה ברוממות העצמו' דא\"ס שאין לו שיעור כלל, כי יש בשבח ותהלה קץ וגבול כאשר המשובח הוא בבחי' גבול בחכמתו [א]ו גדולתו וחסדו וטובו וכה\"ג שאז יכול להגיע לתכלית השבח ויופסק שלא יוכל לשבחו עוד ביתר מכפי מדתו כו', אבל ברוממות עצמות דא\"ס שאין לו שיעור וסוף למעלה מעלה בהתנשאות עצמותו וגדולתו המתפשטת למטה עד אין תכלית שלגדולתו אין חקר<sup data-n=\"9764\">278</sup> למעלה ולמטה, וכן בחכ' העצמיות שנק' חכים ולא בחכ' ידיעא כלל דלתבונתו אין מספר<sup data-n=\"9765\">279</sup> כו' וכן במדותיו וחסדו כי לא תמו חסדיו<sup data-n=\"9766\">280</sup> כו' בבחי' א\"ס ממש",[["9752","266","<b>בפ' יתרו</b>: לעיל רנב, א. וראה גם פ' תצוה שכא, א."],["9753","268","<b>ורוח אלקים. . נוגע ואינו נוגע</b>: בראשית א, ב. ראה ב\"ר פ\"ב, ד. רש\"י האזינו לב, יא."],["9754","267","<b>מטול\"מ. ֿ. רצוא קודם לשוב</b>: ראה גם לעיל פ' וארא סג, ד. וש\"נ."],["9755","269","<b>מדפיק[ו] דלבא</b>: ראה גם לעיל פ' וארא סג, ד. וש\"נ."],["9756","270","<b>אנכי ולא כו' בדבור א' נאמרו</b>: ראה גם לעיל תנא, ג. וש\"נ."],["9757","271","<b>ולא תחללו. . ונקדשתי</b>: ראה גם לעיל תמג, ד."],["9758","272","<b>פי' שלישי</b>: ראה לקמן תנז, ג: כל הד' פירושים הנ\"ל בעדי שהוא קישוט או עדות או הפסק ונצחית."],["9759","273","<b>לעדי עד ימלוך</b>: פיוט מלך עליון — מוסף לר\"ה."],["9760","274","<b>משובח ומפואר עדי עד</b>: ברכת ברך שאמר."],["9761","275","<b>כ\"מ שנאמר נצח סלה ועד</b>: ראה ערובין נד, א."],["9762","276","<b>וכלל</b>: חט: ליתא."],["9763","277","<b>הכל ירוממוך סלה</b>: נסמן לעיל תמד, ד הערה 109."],["9764","278","<b>שלגדולתו אין חקר</b>: ע\"פ תהלים קמה, ג."],["9765","279","<b>דלתבונתו אין מספר</b>: תהלים קמז, ה."],["9766","280","<b>כי לא תמו חסדיו</b>: ראה גם מאמרי אדה\"א דרושי חתונה ח\"א ע' לה [ושם: שנא']."]]]]});
